% Appendix A 
\section{drUCCD}
\label{app:drUCCD}
Within the quasi-boson approximation, the drUCCD amplitude and energy expression can be deduced from the following effective bosonic Hamiltonian \cite{ring2004nuclear} 
\begin{equation}
    \hat{H}_\text{B} 
    = \sum_{IJ} A^\RPA_{IJ} \hat{b}^\dagger_I \hat{b}_J 
    + \frac{1}{2} \sum_{IJ} B^\RPA_{IJ} \qty( \hat{b}^\dagger_I \hat{b}^\dagger_J + \hat{b}_I \hat{b}_J ),
\end{equation}
with $A^\RPA_{IJ}$ and $B^\RPA_{IJ}$ being the (direct) RPA response matrices of Eqs.~\eqref{eq:ARPA} and \eqref{eq:BRPA}.
Furthermore, $\hat{b}^\dagger_I$/$\hat{b}_I$ denote bosonic creation/annihilation operators.
All non-number-conserving bosonic contributions can be removed by the unitary transformation $\bar{H}_\text{B} = e^{-\hat{\sigma}} \hat{H}_\text{B} e^{\hat{\sigma}}$, with
\begin{equation}
    \hat{\sigma} = \frac{1}{2} \sum_{IJ} t_{IJ} \left( \hat{b}^\dagger_I \hat{b}^\dagger_J - \hat{b}_I \hat{b}_J \right).
\end{equation}
The amplitudes $t_{IJ}$ are determined from the following set of equations:
\begin{equation} \label{eq:AmplitudeEquation}
    J_{IJ} = \mel{0}{ \comm{ \bar{H}_\text{B} }{ \hat{b}^\dagger_I \hat{b}^\dagger_J - \hat{b}_I \hat{b}_J } }{0} \overset{!}{=} 0,
\end{equation}
where $\ket{0}$ is the HF reference determinant.
Within the CC formalism, the ground-state energy is defined as
\begin{equation} \label{eq:drUCCD}
    E_0 
    = E_0^{\HF} + \mel{0}{\bar{H}_\text{B}}{0}
    = E_0^{\HF} + E_\text{c}^\text{drUCCD}
\end{equation}
which is identical to Eq.~\eqref{eq:plasmon}.

% Appendix B
\section{BSE@$GW$ Lagrangian}
\label{app:working_equations}

\subsection{Definition}

The nuclear gradient is calculated from the Lagrangian defined in Eq.~\eqref{eq:lagrangian} as
\begin{equation} \label{eq:EnergyGrad}
\begin{split}
    \boldsymbol{G}_\nu 
    & = \pdv{\cL_\nu}{\bR}  
    \\
    & =  \sum_{pq} \pdv{h_{pq}}{\bR} \gamma_{\nu,pq} + \frac{1}{2} \sum_{pqrs} \pdv{(pq|rs)}{\bR} \Gamma_{\nu,pqrs} 
    \\
    & + \sum_{pq} \pdv{S_{pq}}{\bR} M_{pq},
\end{split}
\end{equation}
where $h_{pq}$ is an element of the one-electron Hamiltonian and the other quantities are defined in Sec.~\ref{sec:BSL}.
As readily seen in Eq.~\eqref{eq:EnergyGrad}, the evaluation of the nuclear gradients requires the first- and second-order reduced density matrices (1RDM and 2RDM) associated with the $\nu$th excited state, $\boldsymbol{\gamma}_{\nu}$ and $\boldsymbol{\Gamma}_{\nu}$, respectively.

The elements of the 1RDM consist of the following contributions
\begin{equation}
    \gamma_{\nu,pq} = \gamma^\HF_{pq} + \gamma^\GW_{pq} + \gamma^\BSE_{\nu,pq} + \gamma^{\lambda}_{pq} + \gamma^Z_{pq},
\end{equation}
(with $\gamma^\HF_{ij} = \delta_{ij}$) while the elements of the 2RDM can be decomposed as
\begin{equation}
    \Gamma_{\nu,pqrs} = \Gamma^\GW_{pqrs} + \Gamma^\BSE_{\nu,pqrs} + \Gamma^Z_{pqrs} + \Gamma^{1}_{\nu,pqrs},
\end{equation}
where $\Gamma^{1}_{\nu,pqrs}$ denotes contributions from the 1RDM:
\begin{equation}
\begin{split}
    \Gamma^{1}_{\nu,pqrs} 
    & = 2 \delta_{pi} \delta_{qi} \gamma_{\nu,rs} + 2 \delta_{ri} \delta_{si} \gamma_{\nu,pq} 
    \\
    & - \delta_{qi} \delta_{ri} \gamma_{\nu,ps} - \delta_{pi} \delta_{si} \gamma_{\nu,qr}.
\end{split}
\end{equation}
The spin-integrated contributions to $\gamma^\GW_{pq}$/$\Gamma^\GW_{pqrs}$, $\gamma^Z_{\nu,pq}$/$\Gamma^Z_{pqrs}$ are presented in Secs.~\ref{sec:GWdensity_matrices} and \ref{sec:Z-Lagrange}, respectively, whereas the expressions of $\gamma^{\lambda}_{pq}$ and $M_{pq}$ are presented, for example, in Ref.~\onlinecite{levchenko2005analytic}.

The BSE contributions, central to this work, can be separated into quasiparticle (QP) and kernel ($K$) terms:
\begin{subequations}
\begin{align}
    \gamma^\BSE_{\nu,pq} & = \pdv{\cE_{\nu}}{F_{pq}} = \gamma^\QP_{\nu,pq} + \gamma^K_{\nu,pq},
    \\
    \Gamma^{\BSE}_{\nu,pqrs} & = \pdv{\cE_\nu}{(pq|rs)} = \Gamma^\QP_{\nu,pqrs} + \Gamma^K_{\nu,pqrs}.
\end{align}
\end{subequations}
The QP contributions, $\gamma^\QP_{\nu,pq}$ and $\Gamma^\QP_{\nu,pqrs}$, are outlined in Secs.~\ref{sec:QP1DM} and \ref{sec:QP2DM}, while the kernel contributions, $\gamma^K_{\nu,pq}$ and $\gamma^K_{\nu,pqrs}$, are reported in Secs.~\ref{sec:K1DM} and \ref{sec:K2DM}.

\subsection{$G_0W_0$ ground-state density matrices}
\label{sec:GWdensity_matrices}

The elements of the ground-state correlation density matrices, $\gamma^\GW_{pq}$ and $\Gamma^\GW_{pqrs}$, associated with the energy functional defined in Eq.~\eqref{eq:drUCCD} are given by
\begin{subequations}
\begin{align}
    \gamma^\GW_{pq} & = \pdv{E^\text{drUCCD}_\text{c} }{F_{pq}},
    \\
    \Gamma^\GW_{pqrs} & = \pdv{E^\text{drUCCD}_\text{c} }{(pq|rs)} = \Gamma^{A}_{pqrs} + \Gamma^{B}_{pqrs}.
\end{align}
\end{subequations}
The non-zero contributions to $\gamma^\GW_{pq}$ and $\Gamma^\GW_{pqrs}$ are
\begin{subequations}
\begin{align}
    \gamma^\GW_{ab} &= + \sum_{i} \Gamma^{A}_{iaib},
    \\
    \gamma^\GW_{ij} &= - \sum_{a} \Gamma^{A}_{iaja},
    \\
    \Gamma^\GW_{iajb} & = 4 \qty( \Gamma^{A}_{iajb} +  \Gamma^{B}_{iajb} ).
\end{align}
\end{subequations}
The components $\Gamma^{A/B}_{iajb}$ are defined as expectation values of similarity-transformed operators:
\begin{equation}
    \Gamma^{A/B}_{iajb} = \mel{0}{ \bar{\Gamma}^{A/B}_{IJ} \ket{0} = \bra{0} \qty( e^{-\hat{\sigma}} \hat{\Gamma}^{A/B} e^{\hat{\sigma}} )_{IJ} }{0},
\end{equation}
with 
\begin{align}
    \hat{\Gamma}^{A} &= \sum_{IJ} \hat{b}^\dagger_{I} \hat{b}_{J},
    &
    \hat{\Gamma}^{B} &= \frac{1}{2} \sum_{IJ} \qty( \hat{b}^\dagger_{I} \hat{b}^\dagger_{J} + \hat{b}_{I} \hat{b}_{J} ).
\end{align}
In practice, the similarity-transformed operators $\bar{\Gamma}^{A/B}$ are computed iteratively via
\begin{equation}
    \qty(\bar{\Gamma}^{A/B})^{(n+1)} = \comm{ \qty(\bar{\Gamma}^{A/B})^{(n)} }{ \hat{\sigma} },
\end{equation}
until the convergence condition $\norm*{ \qty( \bar{\Gamma}^{A/B})^{(n)} } / n! < 10^{-9}$ is met.
This procedure is analogous to the construction of $\bar{H}_\text{B}$ (see Appendix \ref{app:drUCCD}).
Further implementation details can be found in Appendix A of Ref.~\onlinecite{tolle2024ab}.

\subsection{Quasiparticle contributions to the first-order density matrix}
\label{sec:QP1DM}

The QP contribution to the 1RDM can be decomposed as
\begin{equation}
	\gamma^\QP_{\nu,pq} = \gamma^{\QP,1}_{\nu,pq} + \gamma^{\QP,2}_{\nu,pq},
\end{equation}
with
\begin{subequations}
\begin{align}
    \gamma^{\QP,1}_{\nu,pq} 
    = & \sum_{ia} X_{ia,\nu} \pdv{\eps^\QP_a}{F_{pq}} X_{ia,\nu}  - \sum_{ia} X_{ia,\nu} \pdv{\eps^{\QP}_i}{F_{pq}} X_{ia,\nu},   
    \\
    \gamma^{\QP,2}_{\nu,pq}
    = & \sum_{ia} Y_{ia,\nu} \pdv{\eps^\QP_a}{F_{pq}} Y_{ia,\nu} - \sum_{ia} Y_{ia,\nu} \pdv{\eps^\QP_i}{F_{pq}} Y_{ia,\nu}.
\end{align}
\end{subequations}
Note that the second contribution is zero when the TDA is enforced at the BSE level as $\bY = \bO$.
Closed-form expressions for the derivatives $\pdv*{\boldsymbol{\eps}^\QP}{F_{pq}}$ are presented in Sec.~\ref{sec:QPdensity_matrices} (see also Ref.~\onlinecite{toelle2024fully}).

\subsection{Kernel contributions to the first-order density matrix}
\label{sec:K1DM}

Similarly, the kernel contribution to the 1RDM is decomposed as
\begin{equation}
	\gamma^K_{\nu,pq} 
	= \gamma^{K,1}_{\nu,pq} 
	+ \gamma^{K,2}_{\nu,pq} + \gamma^{K,3}_{\nu,pq} + \gamma^{K,4}_{\nu,pq}.
\end{equation}
Among these, only $\gamma^{K,1}_{\nu,pq}$ is non-zero when the TDA is applied at the BSE level
\begin{equation}
    \gamma^{K,1}_{\nu,pq} = 4 \sum_{iajb} X_{ia,\nu} D_{pq}^{ia,jb} X_{jb,\nu},
\end{equation}
where we define for notational convenience
\begin{equation}
	D_{pq}^{ia,jb} = \sum_{\tI \tJ} (ij|\tI) \frac{\partial \left[ \bC^{-1} \right]_{\tI\tJ}}{\partial F_{pq}} (\tJ|ab) 
\end{equation}
which can be easily evaluated using the following expression:
\begin{equation}
    \pdv{\bC^{-1}}{F_{pq}} = - \bC^{-1} \cdot \pdv{\bC}{F_{pq}} \cdot \bC^{-1}.
\end{equation}
The general form of $\bC$ is 
\begin{equation}
    C_{\tI\tJ} = \delta_{\tI\tJ} \sum_{iajb}  V^\RPA_{ia,\tI} M_{ia,jb} V^\RPA_{jb,\tI},
\end{equation}
where the definition of $V^\RPA_{ia,\tI}$ and $M_{ia,jb}$ depends on whether the TDA is applied at the RPA level (i.e., to compute the screened Coulomb interaction):
\begin{subequations}
\begin{align}
    M_{ia,jb} & = 
    \begin{cases}
        A^\RPA_{ia,jb}, & \text{(TDA)},
        \\
        A^\RPA_{ia,jb} + B^\RPA_{ia,jb}, & \text{(RPA)},
    \end{cases}
    \\
    V^\RPA_{ia,\tI} & = 
    \begin{cases}
        X^\RPA_{ia,\tI}, & \text{(TDA)},
        \\
        X^\RPA_{ia,\tI} + Y^\RPA_{ia,\tI}, & \text{(RPA)}.
    \end{cases}
\end{align}
\end{subequations}
Furthermore, realizing that [see Eqs.~\eqref{eq:Wsta} and \eqref{eq:excitation_density}]
\begin{multline} \label{eq:Wsimplified}
   \sum_{iajb} \sum_{\tI\tJ} (pq|ia) V^\RPA_{ia,\tI}  \left[\bC^{-1}\right]_{\tI \tJ}  V^\RPA_{jb,\tJ} (jb|rs)
   \\
   = \sum_{iajb} (pq|ia)   \left[\bM^{-1}\right]_{ia,jb} (jb|rs),
\end{multline}
the derivative reads 
\begin{equation}
    \pdv{\left[ \bM \right]_{ia,jb}}{F_{pq}} = \delta_{ij} \delta_{ap} \delta_{bq} - \delta_{ab} \delta_{ip} \delta_{jq}.
\end{equation}
The remaining kernel contributions for the ``full'' BSE are
\begin{subequations}
\begin{align}
    \gamma^{K,2}_{\nu,pq} & = 4 \sum_{iajb} X_{ia,\nu} D_{pq}^{ia,bj} Y_{jb,\nu}, 
    \\
    \gamma^{K,3}_{\nu,pq} & = 4 \sum_{iajb} Y_{ia,\nu} D_{pq}^{ia,bj} X_{jb,\nu},
    \\
    \gamma^{K,4}_{\nu,pq} & = 4 \sum_{iajb} Y_{ia,\nu} D_{pq}^{ia,jb} Y_{jb,\nu}. 
\end{align}
\end{subequations}

\subsection{Quasiparticle contributions to the second-order density matrix}
\label{sec:QP2DM}

Making use of the same nomenclature as above, the QP contributions to the 2RDM read 
\begin{equation}
	\Gamma^\QP_{\nu,pqrs} = \Gamma^{\QP,1}_{\nu,pqrs} + \Gamma^{\QP,2}_{\nu,pqrs},
\end{equation}
with
\begin{subequations}
\begin{align}
\begin{split}
    \Gamma^{\QP,1}_{\nu,pqrs}
    & = \sum_{ia} X_{ia,\nu} \pdv{\eps^\QP_a}{(pq|rs)} X_{ia,\nu} 
    \\
    & - \sum_{ia} X_{ia,\nu} \pdv{\eps^\QP_i}{(pq|rs)} X_{ia,\nu},
\end{split}
    \\
\begin{split}
    \Gamma^{\QP,2}_{\nu,pqrs}
    & = \sum_{ia} Y_{ia,\nu} \pdv{\eps^\QP_a}{(pq|rs)} Y_{ia,\nu} 
    \\
    & - \sum_{ia} Y_{ia,\nu} \pdv{\eps^\QP_i}{(pq|rs)} Y_{ia,\nu}. 
\end{split}
\end{align}
\end{subequations}
Again, only the first contribution has to be considered in the case of the TDA.
The expression for $\pdv*{\boldsymbol{\eps}^\QP}{(pq|rs)}$ is given in Sec.~\ref{sec:QPdensity_matrices} (see also Ref.~\onlinecite{toelle2024fully}).

\subsection{Kernel contributions to the second-order density matrix}
\label{sec:K2DM}

The kernel contributions to $\Gamma^K_{\nu,pqrs} = \sum_{\ell=1}^{20} \Gamma^{K,\ell}_{\nu,pqrs}$ are
\begin{subequations}
\begin{align}
    \Gamma^{K,1}_{\nu,iajb} & = 2 X_{ia,\nu} X_{jb,\nu}, &
    \Gamma^{K,2}_{\nu,iajb} & = 2 X_{ia,\nu} Y_{jb,\nu}, \\
    \Gamma^{K,3}_{\nu,iajb} & = 2 Y_{ia,\nu} X_{jb,\nu}, &
    \Gamma^{K,4}_{\nu,iajb} & = 2 Y_{ia,\nu} Y_{jb,\nu}, \\
    \Gamma^{K,5}_{\nu,ijab} & = - X_{ia,\nu} X_{jb,\nu}, &
    \Gamma^{K,6}_{\nu,ijab} & = - Y_{ia,\nu} Y_{jb,\nu}, \\
    \Gamma^{K,7}_{\nu,iabj} & = - X_{ia,\nu} Y_{jb,\nu}, &
    \Gamma^{K,8}_{\nu,iabj} & = - Y_{ia,\nu} X_{jb,\nu}.  
\end{align}
\end{subequations}
Note that these contributions also arise in the (linear-response) time-dependent HF formalism. 

For BSE, one additionally has 
\begin{subequations}
\begin{align}
    \Gamma^{K, 9}_{\nu,ijkc} & =  4 \sum_{ab} X_{ia,\nu} \bar{T}_{ab,kc} X_{jb,\nu}, 
    \\
    \Gamma^{K,10}_{\nu,abkc} & = 4 \sum_{ij} X_{ia,\nu} \bar{T}_{ij,kc} X_{jb,\nu}, 
    \\
    \Gamma^{K,11}_{\nu,kcld} & = - 4 \kappa \sum_{iajb}  X_{ia,\nu} \bar{T}_{ij,kc} \bar{T}_{ab,ld} X_{jb,\nu}, 
    \\
    \Gamma^{K,12}_{\nu,ijkc} & = 4 \sum_{ab} Y_{ia,\nu} \bar{T}_{ab,kc} Y_{jb,\nu}, 
    \\
    \Gamma^{K,13}_{\nu,abkc} & = 4 \sum_{ij} Y_{ia,\nu} \bar{T}_{ij,kc} Y_{jb,\nu}, 
    \\
    \Gamma^{K,14}_{\nu,kcld} & = - 4 \kappa \sum_{iajb} Y_{ia,\nu} \bar{T}_{ij,kc} \bar{T}_{ab,ld} Y_{jb,\nu}, 
    \\
    \Gamma^{K,15}_{\nu,ibkc} & = 4 \sum_{aj} X_{ia,\nu} \bar{T}_{ja,kc} Y_{jb,\nu}, 
    \\
    \Gamma^{K,16}_{\nu,kcja} & = 4 \sum_{ib} X_{ia,\nu} \bar{T}_{ib,kc} Y_{jb,\nu}, 
    \\
    \Gamma^{K,17}_{\nu,kcld} & = - 4 \kappa \sum_{iajb} X_{ia,\nu} \bar{T}_{ib,kc} \bar{T}_{ja,ld} Y_{jb,\nu}, 
    \\
    \Gamma^{K,18}_{\nu,ibkc} & = 4 \sum_{aj} Y_{ia,\nu} \bar{T}_{ja,kc} X_{jb,\nu}, 
    \\
    \Gamma^{K,19}_{\nu,kcja} & = 4 \sum_{ib} Y_{ia,\nu} \bar{T}_{ib,kc} X_{jb,\nu}, 
    \\
    \Gamma^{K,20}_{\nu,kcld} & = - 4 \kappa \sum_{iajb} Y_{ia,\nu} \bar{T}_{ib,kc} \bar{T}_{ja,ld} X_{jb,\nu},
    \label{eq:GammaK20}
\end{align}
\end{subequations}
where we have defined the following intermediate
\begin{equation}
    \bar{T}_{pq,kc} 
    = \sum_{ld} (pq|ld) \left[ \bM^{-1} \right]_{ld,kc}.
\end{equation}
In the case of full RPA [see Eq.~\eqref{eq:RPA}], we have $\kappa = 2$, while $\kappa = 1$ in the TDA [see Eq.~\eqref{eq:TDA}] for the screened Coulomb interaction [see Eq.~\eqref{eq:Wsta}].
Again, the term that survives in the TDA can be easily identified as $\bY = \bO$ in this case.

\subsection{$G_0W_0$ quasiparticle density matrices}
\label{sec:QPdensity_matrices}

The expressions of $\gamma^\QP_{\nu,pq}$ and $\Gamma^\QP_{\nu,pqrs}$ for the different BSE@$GW$ variants require the derivative of the $G_0W_0$ quasiparticle energies $\eps_r^\QP$ with respect to the elements of the Fock matrix $F_{pq}$ and the electron repulsion integrals $(pq|st)$.
As discussed in Ref.~\onlinecite{toelle2024fully}, these read
\begin{align}
    \pdv{\eps_r^\QP}{F_{pq}} & = \gamma^\GW_{r,pq},
	& 
	\pdv{\eps_{r}^\QP}{(pq|st)} & = \Gamma^\GW_{r,pqst}.
\end{align}
Note that these density matrices should not be confused with the ground-state $G_0W_0$ correlation density matrices, $\gamma^\GW_{pq}$ and $\Gamma^\GW_{pqrs}$, defined in Sec.~\ref{sec:GWdensity_matrices}.

The elements of the $GW$ 1RDM associated with the $r$th quasiparticle energy are determined as follows:
\begin{subequations}
    \begin{align}
        \begin{split}
        	\gamma^\GW_{r,ij} 
        	& = X^\GW_{r,i} X^\GW_{r,j} + \sum_{kc} X^{\GW}_{r,i(kc)} X^\GW_{r,j(kc)} 
        	\\
        	& + \sum_{ka} \tilde{X}^\GW_{r,k(ja)}\tilde{X}^\GW_{r,k(ia)} - \sum_{ba} \tilde{X}^\GW_{r,(ib)a}\tilde{X}^\GW_{r,(jb)a},  
		\end{split}
        \\
        \begin{split}
        	\gamma^\GW_{r,ab} 
			& = X^\GW_{r,a} X^\GW_{r,b} + \sum_{kc}  X^\GW_{r,(kc)a} X^\GW_{r,(kc)b}
        	\\
        	& + \sum_{ic} \tilde{X}^\GW_{r,(ia)c} \tilde{X}^\GW_{r,(ib)c} - \sum_{kj} \tilde{X}^\GW_{r,k(ja)} \tilde{X}^\GW_{r,k(jb)}, 
		\end{split}
        \\
        \gamma^\GW_{r,ia} & = X^\GW_{r,i} X^\GW_{r,a}, 
        \\
        \gamma^\GW_{r,ai} & = X^\GW_{r,a} X^\GW_{r,i},
    \end{align}
\end{subequations}
where $\bX^\GW_r$ denoting the excitation vector within the frequency-free $G_0W_0$ scheme, \cite{bintrim2021full,tolle2023exact} and
\begin{subequations}
\begin{align}
    \tilde{X}^\GW_{r,k(ia)} & = \sum_{jb}X^\GW_{r,k(jb)} \qty[ e^{\bt} ]_{jb,ia},
    \\
    \tilde{X}^\GW_{r,(ia)c} & = \sum_{jb}X^\GW_{r,(jb)c} \qty[ e^{\bt} ]_{jb,ia}.
\end{align}
\end{subequations}
Similarly, the contributions to the 2RDM are 
\begin{subequations}
\begin{align}
   \Gamma^{\GW,1}_{r,iajb} & = 4 \kappa  \sum_{c} \tilde{X}^\GW_{r,(ia)c} \tilde{X}^\GW_{r,(jb)c}, 
   \\
   \Gamma^{\GW,2}_{r,iajb} & = -4 \kappa \sum_{k} \tilde{X}^\GW_{r,k(ia)} \tilde{X}^\GW_{r,k(jb)}, 
   \\
   \Gamma^{\GW,3}_{r,iajb} & = 4 \sqrt{2} \qty( X^\GW_{r,i} \tilde{X}^\GW_{r,(jb)a} + X^\GW_{r,a}\tilde{X}^\GW_{r,i(jb)} ), 
\end{align}
\end{subequations}
so that $\Gamma^\GW_{r,iajb} = \Gamma^{\GW,1}_{r,iajb} + \Gamma^{\GW,2}_{r,iajb} + \Gamma^{\GW,3}_{r,iajb}$.
Additional contributions are 
\begin{subequations}
\begin{align}
   \Gamma^\GW_{r,ijkc} & = 2 \sqrt{2} X^\GW_{r,i} \tilde{X}^\GW_{r,j(kc)}, 
   \\
   \Gamma^\GW_{r,kcij} & = 2 \sqrt{2} \tilde{X}^\GW_{r,j(kc)} X^\GW_{r,i}, 
   \\
   \Gamma^\GW_{r,abkc} & = 2 \sqrt{2} X^\GW_{r,a} \tilde{X}^\GW_{r,(kc)b}, 
   \\
   \Gamma^\GW_{r,kcab} & = 2 \sqrt{2} \tilde{X}^\GW_{r,(kc)b} X^\GW_{r,a},
\end{align}
\end{subequations}
with $\kappa = 1$ or $2$ for TDA [see Eq.~\eqref{eq:TDA}] or RPA [see Eq.~\eqref{eq:RPA}] for the evaluation of the screened Coulomb interaction, respectively.

\subsection{$Z$-Lagrange multipliers}
\label{sec:Z-Lagrange}

We now present the working equations for obtaining the $Z$-Lagrange multipliers, along with their corresponding 1RDM and 2RDM contributions. 
These equations follow from the stationarity condition of the Lagrangian with respect to the amplitude parameters, i.e.,
\begin{equation}
    \pdv{\cL_\nu}{t_{I J}} \overset{!}{=} 0.
\end{equation}
In contrast to the contributions shown in Ref.~\onlinecite{toelle2024fully}, one, in principle, needs to consider both the quasiparticle and kernel contributions:
\begin{equation} \label{eq:dcEdtIJ}
    \pdv{\cE_\nu}{t_{I J}} = W^\QP_{\nu,I J} +  W^K_{\nu,I J}.
\end{equation}

The kernel term, $W^K_{\nu, IJ}$, takes the form
\begin{equation}
    W^K_{\nu,I J} = 4 \sum_{iajb}  X_{ia,\nu} \sum_{\tI \tJ} (ij|\tI) \frac{\partial \left[ \bC^{-1} \right]_{\tI \tJ}}{\partial t_{IJ}}  (\tJ|ab) X_{jb,\nu}.
\end{equation}
However, since this term does not explicitly depend on the amplitudes $\boldsymbol{t}$ [see Eqs.~\eqref{eq:RPAdrUCCD} and \eqref{eq:Wsimplified}], we have $W^K_{\nu,I J} = 0$.
As a result, only the quasiparticle contributions $W^\QP_{\nu,I J}$ need to be retained in Eq.~\eqref{eq:dcEdtIJ}.

The quasiparticle contribution $W^\QP_{\nu,I J} = W^{\QP,1}_{\nu,I J} + W^{\QP,2}_{\nu,I J}$ can be obtained from
\begin{subequations}
\begin{align}
    W^{\QP,1}_{\nu,I J}
    & = \sum_{ia} X_{ia,\nu} \pdv{\eps^\QP_a}{t_{I J}} X_{ia,\nu} - \sum_{ia} X_{ia,\nu} \pdv{\eps^\QP_i}{t_{I J}}  X_{ia,\nu},  
    \\
    W^{\QP,2}_{\nu,I J}
    & = \sum_{ia} Y_{ia,\nu} \pdv{\eps^\QP_a}{t_{I J}} Y_{ia,\nu} - \sum_{ia} Y_{ia,\nu} \pdv{\eps^\QP_i}{t_{I J}} Y_{ia,\nu} .
\end{align}
\end{subequations}
The derivatives of the quasiparticle energies are given by
\begin{equation}
    \pdv{\eps^\QP_p}{t_{I J}} = Q_{p,I J} = \sum_{\ell=1}^{10} Q^\ell_{p,I J},
\end{equation}
with 
\begin{subequations}
\begin{align}
    Q^1_{p,I J} &=  \sqrt{2} \sum_{ijK L} X^\GW_{p,i} (ij|K) \pdv{}{t_{I J}} \left[ e^{\bt} \right]_{K L} X^\GW_{p,j L},  
    \\
    Q^2_{p,I J} &= \sqrt{2}\sum_{ijK L} X^\GW_{p,jL} \pdv{}{t_{I J}} \left[ e^{\bt} \right]_{L K} (K|ij)  X^\GW_{p,i}, 
    \\
    Q^3_{p,I J} &= \sqrt{2} \sum_{abK L} X^\GW_{p,a} (ab|K) \pdv{}{t_{I J}} \left[ e^{\bt} \right]_{K L} X^\GW_{p,L b}, 
    \\
    Q^4_{p,I J} &= \sqrt{2} \sum_{ab K L} X^\GW_{p,L a} \pdv{}{t_{I J}} \left[ e^{\bt} \right]_{LK } (K|a b)  X^\GW_{p,b}, 
    \\
    Q^5_{p,I J} &= \sqrt{2} \sum_{iaK L} X^\GW_{p,i} (ia|K) \pdv{}{t_{I J}} \left[ e^{\bt} \right]_{K L} X^\GW_{p,L a}, 
    \\
    Q^6_{p,I J} &= \sqrt{2} \sum_{iaK L}  X^\GW_{p,L a} \pdv{}{t_{I J}} \left[ e^{\bt} \right]_{LK} (L|i a) X^\GW_{p,i}, 
    \\
    Q^7_{p,I J} &=  \sqrt{2} \sum_{iaK L} X^\GW_{p,a} (ia|L) \pdv{}{t_{I J}} \left[ e^{\bt} \right]_{LK} X^\GW_{p,iK}, 
    \\
    Q^8_{p,I J} &= \sqrt{2} \sum_{iaK L} X^\GW_{p,iK} \pdv{}{t_{I J}} \left[ e^{\bt} \right]_{KL} (L|i a) X^\GW_{p,a},  
    \\
    Q^9_{p,I J} &= - \sum_{i K L} X^\GW_{p,iK} \pdv{}{t_{I J}} \left[ \bar{\bM}\right]_{LK} X^\GW_{p,i L},  
    \\
    Q^{10}_{p,I J} &= \sum_{aK L} X^\GW_{p,K a} \pdv{}{t_{I J}} \left[\bar{\bM}\right]_{LK} X^\GW_{p, L a},
    \label{eq:Q10}
\end{align}
\end{subequations}
where $\bar{\bM} = e^{\bt^\dagger} \cdot ( \bA^\RPA + \bB^\RPA ) \cdot e^{\bt}$ and 
\begin{equation} \label{eq:dertIJ}
    \pdv{}{t_{I J}} \left[ e^{\bt} \right]_{K L} = \sum^N_{n=0} \frac{1}{\left(n+1\right)!} \sum^{n}_{k=0} \left[ \bt^{n-k}\right]_{I K} \left[\bt^{k}\right]_{L J}.
\end{equation}
As in the previous study, \cite{toelle2024fully} we set $N = 5$ in Eq.~\eqref{eq:dertIJ}.

The Lagrange multipliers and the density matrix contributions are then obtained from
\begin{equation}
     \pdv{\cL_\nu}{t_{I J}} = W^{\QP}_{\nu,I J} + \sum_{K L} Z_{K L} \pdv{J_{K L}}{t_{I J}} = 0,
     \label{eq:ZLagrange}
\end{equation}
with 
\begin{equation}
    \pdv{J_{K L}}{t_{I J}} = \pdv{}{t_{I J}} \left[ \bar{\mathbf{B}} + \bar{\mathbf{B}}^\dagger \right]_{K L} .
\end{equation}
The derivative is determined, after rewriting $\bar{\mathbf{B}}$ as 
\begin{equation}
\begin{split}
    \bar{B}_{K L} 
    & = \frac{1}{2} \left( \sum_{IJ}\left[ e^{\bt^\dagger} \right]_{K I} \left[\mathbf{A} + \mathbf{B}\right]_{I J} \left[ e^{\bt} \right]_{J L}  \right.
    \\ 
    & \left. + \sum_{I J}\left[ e^{-\bt^\dagger} \right]_{K I} \left[\mathbf{B} - \mathbf{A}\right]_{I J} \left[ e^{-\bt} \right]_{J L}\right).
\end{split}
\end{equation}
Equation \eqref{eq:ZLagrange} is solved through the LGMRES\cite{baker2005lgmres} algorithm as implemented in \textsc{Scipy} \cite{virtanen2020scipy}(convergence details are presented in Sec.~\ref{sec:CompDetails}). 

The resulting density matrices associated with the $Z$-Lagrange multipliers are obtained from
\begin{subequations}
\begin{align}
   \gamma^Z_{pq} & = \pdv{\sum_{iajb} Z_{ia,jb} J_{ia,jb}}{F_{pq}},
    \\
   \Gamma^Z_{pqrs} & = \pdv{\sum_{iajb} Z_{ia,jb} J_{ia,jb}}{(pq|rs)}.
\end{align}
\end{subequations}
In practice, these terms are evaluated based on the invariance of the trace under cyclic permutations. 
The different non-zero contributions read
\begin{subequations}
\begin{align}
    \gamma^Z_{\ij} & = -2 \sum_{a} \qty( \tilde{Z}_{ia,ja} - \tilde{\tilde{Z}}_{ia,ja} ),
    \\
    \gamma^Z_{ab} & = 2 \sum_{i} \qty( \tilde{Z}_{ia,ib} - \tilde{\tilde{Z}}_{ia,ib} ),
\end{align}
\end{subequations} 
where
\begin{subequations}
\begin{align}
    \tilde{Z}_{ia,jb} & = \sum_{kcld} \left[ e^{\bt^\dagger}\right]_{ia,kc} Z_{kc,ld} \left[ e^{\bt} \right]_{ld,jb},
    \\
    \tilde{\tilde{Z}}_{ia,jb} & = \sum_{kcld} \left[ e^{-\bt^\dagger}\right]_{ia,kc} Z_{kc,ld} \left[ e^{-\bt} \right]_{ld,jb}.
\end{align}
\end{subequations}
Making use of the same intermediates, the only non-vanishing contribution to $\Gamma^Z_{\nu,pqrs}$ is $\Gamma^Z_{\nu,iajb} = 16 \tilde{Z}_{ia,jb}$.

% Appendix C
\section{Validation of the analytic nuclear gradients}
\label{app:ana_vs_num}

We assess the accuracy of the analytical nuclear gradients by comparing them with numerical (finite-difference) gradients for a set of five diatomic molecules: \ce{H2}, \ce{HCl}, \ce{HF}, \ce{N2}, and \ce{CO}, all evaluated at their equilibrium bond length $R_\text{eq}$. 
The numerical gradients are computed using the following fourth-order central difference formula:
\begin{multline}
	G_\nu^\text{num} 
	= \frac{1}{12\Delta} \Big( E_\nu[R_\text{eq} - 2 \Delta ] - 8E_\nu[R_\text{eq} - \Delta ] 
	\\
	+ 8E_\nu[R_\text{eq} + \Delta ] - E_\nu[R_\text{eq} + 2\Delta ] \Big),
\end{multline}
where $E_\nu$ is the total energy of the $\nu$th excited state [see Eq.~\eqref{eq:BSE_energy}]. A step size of $\Delta = \SI{0.01}{\AA}$ was used for all systems except CO, for which a smaller step of $\Delta = \SI{0.001}{\AA}$ was employed to ensure numerical stability.

All calculations were performed using the def2-TZVPP basis set and convergence thresholds as described in Sec.~\ref{sec:CompDetails}, and include the energetically lowest $N_\text{occ}$ occupied and \titou{$N_\text{occ}$} virtual quasiparticle states.

The absolute differences between analytical and numerical gradients are reported in Table \ref{tab:BSEGrad}. 
In all cases, the discrepancy remains below \SI{2d-6}{\hartree\per\AA}, demonstrating excellent agreement. 
These results confirm the correctness of our derivation and implementation of analytical nuclear gradients for the various BSE@$GW$ variants.

