    \section{Counting isomorphism classes of \texorpdfstring{$E/\Fb_q(t)$}{P}}
    \label{sec:Ell_32}

    In counting the exact unweighted number of isomorphism classes of $E/\Fb_q(t)$, it is vital to understand the families of elliptic curves that are non-constant (i.e. height $n \ge 1$) and isotrivial (i.e. a fixed $j$-invariant) with extra automorphisms (i.e. more than the generic hyperelliptic involution automorphism of order 2) having strictly additive bad reductions (i.e. potentially good reduction) which leads to various lower order main terms that are hidden from the exact weighted number of isomorphism classes of $E/\Fb_q(t)$ (c.f. \cite[Rmk 9.8]{BPS}).

    \medskip

    In this regard, for $\text{char} (\Fb_q) = 3,2$, the automorphism group of a geometric point of $\mathcal{M}_{1,1}$ is of order 2 away from $j=0$ (c.f. \cite[Ap. A, Prop. 1.2]{Silverman}).  In $\text{char} (\Fb_q) = 2$, the generic geometric points with $j_{g} \neq 0$ have the stabilizer groups of $Z = \Spec k[x]/(x^2-1)$ which is non-reduced as $x^2 - 1 = (x-1)^2$. The automorphism group of a geometric point at $j=0$ is $Q_{12}$ (resp. $Q_{24}$) the dicyclic group of order 12 (resp. 24). The dicyclic groups are non-abelian with order $4n$ for $n \ge 3$ and each contains a unique element of order 2.

    \medskip

    A given generalized Weierstrass form $F = x^3 + a_2x^2 + a_4x + a_6 - y^2 - a_1xy - a_3y$, where $a_i \in H^0(\Oc_{\Pb^1}(in))$ defines an $E/\Fb_q(t)$ and if $F$ defines an $E/\Fb_q(t)$ with a fixed $j$-invariant then as explained in \cite[Ap. A, Prop. 1.1]{Silverman} there exists a coordinate change of the form $x \mapsto x + b_1$ and $y \mapsto y + b_1x + b_3$ with $b_i \in H^0(\Oc_{\Pb^1}(in))$ such that for $\text{char} (\Fb_q) = 3$ and $j=0$ has the following normal Weierstrass form 
        \[
        y^2 = x^3 + a_4 x + a_6
        \]
    As explained in \cite[\S 4.13 (b2)]{dJ2}, there exists a unique choice of the pair $(b_1, b_3)$ so that we get 
        \[
        y^2 = x^3 + a'_4 x + a'_6
        \]
    where $a'_4$ is a nonzero section of $\Oc(4n)$ and $a'_6$ is any section of $\Oc(6n)$. As in the paragraph before \cite[Prop. 4.14]{dJ2}, we have $(q^{4n+1} - 1)q^{6n+1}q^{4n+2}$ as the total number of Weierstrass polynomials which are non-constant and isotrivial with $j=0$ where $(q^{4n+1} - 1)$ corresponds to counting a nonzero section of $\Oc(4n)$ and $q^{6n+1}$ corresponds to counting any section of $\Oc(6n)$ and $q^{4n+2}$ corresponds to counting any sections of $\Oc(n)$ and $\Oc(3n)$ due to $(b_1, b_3)$ worth of freedom.

    \medskip

    After dividing out the coordinate change factor of $q^{6n+3}(q-1)$ consisting of $(b_1, b_2, b_3)$ worth of freedom and a nonzero scalar $\lambda \in k^*$, we have 

        \[
        (q^{4n} + \ldots + 1) \cdot q^{4n} = (q^{8n} + \ldots + q^{4n}) = (q^{8n} + \ldots + 1) - (q^{4n-1} + \ldots + 1)
        \]

    This expression is the total number of minimal Weierstrass forms that are isotrivial with $j=0$ upto height $n$. Using the relation of \cite[(4.13.1)]{dJ2}, we see that counting the weighted number of rational points of height $n \ge 1$ on the classifying stacks $\mathcal{B} Q_{12}$ (the stacky point of $\mathcal{M}_{1,1}$ at $j=0$) has the same cardinality as counting the weighted number of rational points on $\Pc(8) - \Pc(\check{4})$. 

    \begin{prop}\label{prop:Wmin_preq_P3}
    The classes $\left\{ \cW_{n}^{\mathrm{min}} \right\}$ for the classifying stack $\mathcal{B} Q_{12}$ of dicyclic group of order 12 are given by the following formulas:
        \begin{align*}
            \left\{ \cW_{0}^{\mathrm{min}} \right\} &=  1 \\
            \left\{ \cW_{1}^{\mathrm{min}} \right\} 
            &= (\Lb^{8} + \ldots + \Lb^{2}) - (\Lb^{3} + \Lb^{2} + \Lb + 1) \\
            %&= \Lb^{8} + \Lb^{7} + \Lb^{6} + \Lb^{5} + \Lb^{4} - \Lb - 1  \\
            \left\{ \cW_{n \ge 2}^{\mathrm{min}} \right\} 
            &= \Lb^{(n-2)8 + 2} ( \Lb^{7} - 1 ) \{\Pb^{7}\} - \Lb^{(n-2)4 + 1} ( \Lb^{3} - 1 ) \{\Pb^{3}\}
        \end{align*} 
        %\begin{align*}
            %= \left[ ( \Lb^{8n} + \ldots + \Lb^{8n-6} ) - ( \Lb^{8n-8} + \ldots + \Lb^{8n-14} ) \right] &- \left[ ( \Lb^{4n-1} + \ldots + \Lb^{4n-3} ) - ( \Lb^{4n-5} + \ldots + \Lb^{4n-7} ) \right] \\
        %\end{align*}    
    \end{prop}

    %$\Pc(8) - \Pc(\check{4})$

    \begin{proof} 

    At height $n=0$ we only have a constant map to $j=0$ which means $\cW_{0}^{\mathrm{min}}$ has the motive of $\left\{ \Pb^0 \right\} = 1$. For height $n=1$, we have the motive of $\left\{ \cW_{1}^{\mathrm{min}}(\Pc(8),\Oc(1)) \right\} = \Lb^8 + \Lb^7 + \Lb^6 + \Lb^5 + \Lb^4 + \Lb^3 + \Lb^2$ from this we need to subtract $\left\{ \cW_{1}^{\mathrm{min}}(\Pc(\check{4}),\Oc(1)) \right\} = \Lb^3 + \Lb^2 + \Lb + 1$. For height $n \ge 2$, we have the motive of $\left\{ \cW_{n \ge 2}^{\mathrm{min}}(\Pc(8),\Oc(1)) \right\} = \Lb^{8n-14} ( \Lb^{7} - 1 ) \{\Pb^{7}\}$ from this we subtract $\left\{ \cW_{n \ge 2}^{\mathrm{min}}(\Pc(\check{4}),\Oc(1)) \right\} = \Lb^{4n-7} ( \Lb^{3} - 1 ) \{\Pb^{3}\}$.

    \end{proof} 

    As for $\text{char} (\Fb_q) = 2$ and $j \neq 0$ has the following normal Weierstrass form 
        \[
        y^2 + a_1xy = x^3 + a_2 x^2 + a_6
        \]
    As explained in \cite[\S 4.13 (c1)]{dJ2}, there exists a unique choice of the pair $(b_2, b_3)$ so that we get 
        \[
        y^2 + a'_1xy = x^3 + a'_2 x^2 + (a'_1)^6
        \]
    where $a'_1$ is a nonzero section of $\Oc(n)$ and $a'_2$ is any section of $\Oc(2n)$. As in the paragraph before \cite[Prop. 4.14]{dJ2}, we have $(q-1)(q^{n+1} - 1)q^{2n+1}q^{5n+2}$ as the total number of Weierstrass polynomials which are non-constant and isotrivial with a certain fixed $j_{g} \neq 0$ where $(q-1)$ corresponds to $\mathcal{M}_{1,1} - \{j=0\}$ and $(q^{n+1} - 1)$ corresponds to counting a nonzero section of $\Oc(n)$ and $q^{2n+1}$ corresponds to counting any section of $\Oc(2n)$ and $q^{5n+2}$ corresponds to counting any sections of $\Oc(2n)$ and $\Oc(3n)$ due to $(b_2, b_3)$ worth of freedom.

    \medskip

    After dividing out the coordinate change factor of $q^{6n+3}(q-1)$ consisting of $(b_1, b_2, b_3)$ worth of freedom and a nonzero scalar $\lambda \in k^*$, we have 

        \[
        (q^{n} + \ldots + 1) \cdot q^{n} = (q^{2n} + \ldots + q^{n}) = (q^{2n} + \ldots + 1) - (q^{n-1} + \ldots + 1)
        \]

    This expression is the total number of minimal Weierstrass forms that are isotrivial with $j_{g} \neq 0$ upto height $n$. Using the relation of \cite[(4.13.1)]{dJ2}, we see that counting the weighted number of rational points of height $n \ge 1$ on the classifying stack $\mathcal{B} Z$ (the generic stacky point of $\mathcal{M}_{1,1}$ at $j_{g} \neq 0$) has the same cardinality as counting the weighted number of rational points on $\Pc(2) - \Pc(\check{1})$. 

    \begin{prop}\label{prop:Wmin_preq_P2Z}
    The classes $\left\{ \cW_{n}^{\mathrm{min}} \right\}$ for the classifying stack $\mathcal{B} Z$ of non-reduced group scheme of order 2 are given by the following formulas:
        \begin{align*}
            \left\{ \cW_{0}^{\mathrm{min}} \right\} &=  1 \\
            \left\{ \cW_{1}^{\mathrm{min}} \right\} 
            &= \Lb^{2} - 1 \\
            %&= \Lb^{9} + \Lb^{8} + \Lb^{7} + \Lb^{6} - \Lb - 1  \\
            \left\{ \cW_{n \ge 2}^{\mathrm{min}} \right\} 
            &= \Lb^{(n-2)2 + 2} ( \Lb - 1 ) \{\Pb^{1}\}
        \end{align*}   
    \end{prop}

    \begin{proof} 

    At height $n=0$ we only have a constant map to $j=0$ which means $\cW_{0}^{\mathrm{min}}$ has the motive of $\left\{ \Pb^0 \right\} = 1$. For height $n=1$, we have the motive of $\left\{ \cW_{1}^{\mathrm{min}}(\Pc(2),\Oc(1)) \right\} = \Lb^2$ from this we need to subtract  $\left\{ \cW_{1}^{\mathrm{min}}(\Pc(\check{1}),\Oc(1)) \right\} = 1$. For height $n \ge 2$, we have the motive of $\left\{ \cW_{n \ge 2}^{\mathrm{min}}(\Pc(2),\Oc(1)) \right\} = \Lb^{2n-2} ( \Lb - 1 ) \{\Pb^{1}\}$ from this we subtract nothing as $\left\{ \cW_{n \ge 2}^{\mathrm{min}}(\Pc(\check{1}),\Oc(1)) \right\} = 0$.

    \end{proof} 

    Lastly, as for $\text{char} (\Fb_q) = 2$ and $j=0$ has the following normal Weierstrass form 
        \[
        y^2 + a_3y = x^3 + a_4 x + a_6
        \]
    As explained in \cite[\S 4.13 (c2)]{dJ2}, there exists a unique choice of $b_2$ so that we get 
        \[
        y^2 + a'_3y = x^3 + a'_4 x + a'_6
        \]
    where $a'_3$ is a nonzero section of $\Oc(3n)$ and $a'_4$ (resp. $a'_6$) is any section of $\Oc(4n)$ (resp. $\Oc(6n)$). As in the paragraph before \cite[Prop. 4.14]{dJ2}, we have $(q^{3n+1} - 1)q^{4n+1}q^{6n+1}q^{2n+1}$ as the total number of Weierstrass polynomials which are non-constant and isotrivial with $j=0$ where $(q^{3n+1} - 1)$ corresponds to counting a nonzero section of $\Oc(3n)$ and $q^{4n+1}$ (resp. $q^{6n+1}$) corresponds to counting any section of $\Oc(4n)$ (resp. $\Oc(6n)$) and $q^{2n+1}$ corresponds to counting any sections of $\Oc(2n)$ due to $b_2$ worth of freedom.

    \medskip

    After dividing out the coordinate change factor of $q^{6n+3}(q-1)$ consisting of $(b_1, b_2, b_3)$ worth of freedom and a nonzero scalar $\lambda \in k^*$, we have 

        \[
        (q^{3n} + \ldots + 1) \cdot q^{6n} = (q^{9n} + \ldots + q^{6n}) = (q^{9n} + \ldots + 1) - (q^{6n-1} + \ldots + 1)
        \]

    This expression is the total number of minimal Weierstrass forms that are isotrivial with $j=0$ upto height $n$. Using the relation of \cite[(4.13.1)]{dJ2}, we see that counting the weighted number of rational points of height $n \ge 1$ on the classifying stacks $\mathcal{B} Q_{24}$ (the stacky point of $\mathcal{M}_{1,1}$ at $j=0$) has the same cardinality as counting the weighted number of rational points on $\Pc(9) - \Pc(\check{6})$. 

    \begin{prop}\label{prop:Wmin_preq_P2}
    The classes $\left\{ \cW_{n}^{\mathrm{min}} \right\}$ for the classifying stack $\mathcal{B} Q_{24}$ of dicyclic group of order 24 are given by the following formulas:
        \begin{align*}
            \left\{ \cW_{0}^{\mathrm{min}} \right\} &=  1 \\
            \left\{ \cW_{1}^{\mathrm{min}} \right\} 
            &= (\Lb^{9} + \ldots + \Lb^{2}) - (\Lb^{5} + \ldots + 1) \\
            %&= \Lb^{9} + \Lb^{8} + \Lb^{7} + \Lb^{6} - \Lb - 1  \\
            \left\{ \cW_{n \ge 2}^{\mathrm{min}} \right\} 
            &= \Lb^{(n-2)9 + 2} ( \Lb^{8} - 1 ) \{\Pb^{8}\} - \Lb^{(n-2)6 + 1} ( \Lb^{5} - 1 ) \{\Pb^{5}\}
        \end{align*}   
    \end{prop}

    \begin{proof} 

    At height $n=0$ we only have a constant map to $j=0$ which means $\cW_{0}^{\mathrm{min}}$ has the motive of $\left\{ \Pb^0 \right\} = 1$. For height $n=1$, we have the motive of $\left\{ \cW_{1}^{\mathrm{min}}(\Pc(9),\Oc(1)) \right\} = \Lb^9 + \Lb^8 + \Lb^7 + \Lb^6 + \Lb^5 + \Lb^4 + \Lb^3 + \Lb^2$ from this we need to subtract $\left\{ \cW_{1}^{\mathrm{min}}(\Pc(\check{6}),\Oc(1)) \right\} = \Lb^5 + \Lb^4 + \Lb^3 + \Lb^2 + \Lb + 1$. For height $n \ge 2$, we have the motive of $\left\{ \cW_{n \ge 2}^{\mathrm{min}}(\Pc(9),\Oc(1)) \right\} = \Lb^{9n-16} ( \Lb^{8} - 1 ) \{\Pb^{8}\}$ from this we subtract $\left\{ \cW_{n \ge 2}^{\mathrm{min}}(\Pc(\check{6}),\Oc(1)) \right\} = \Lb^{6n-11} ( \Lb^{5} - 1 ) \{\Pb^{5}\}$.

    \end{proof} 

    We are now ready to prove Theorem~\ref{thm:ell_curve_count_char_32}.

    \begin{proof}[Proof of Theorem~\ref{thm:ell_curve_count_char_32}]

    We prove for $q = 3^r$ case first. We recall that the weighted count $\Nc^w(\Fb_q(t),~B)$ in \cite[Theorem 9.7]{BPS} is the same for all positive characteristic as shown in \cite[Proposition 4.12]{dJ2}. As for the unweighted count, we multiply $2$ to the weighted count $\Nc^w(\Fb_q(t),~B)$ since any stacky point away from $j=0$ has the hyperelliptic involution automorphism group of order 2 (c.f. \cite[Ap. A, Prop. 1.2]{Silverman}).

    \medskip

    For $j=0$, we take the weighted count in Proposition \ref{prop:Wmin_preq_P3} and multiply appropriate factors which are $(4-2)=2$ for r odd case and $(6-2)=4$ for r even case depending on the parity of prime power of 3 as there are 4 isomorphism classes (resp. 6 isomorphism classes) of supersingular elliptic curves for r odd case (resp. r even case) (c.f. \cite[Thm. 3.5]{CJ}) and -2 comes from taking into account the hyperelliptic involution.

    \medskip  

    Thus for the unweighted count, we would like to compute the following. \\

    When r is odd:
    \begin{align*}
    \Nc(\Fb_q(t), B) &= 2 \cdot \Nc^w(\Fb_q(t),~B) + 2 \cdot ( \#_q\cW_{n,\Pb^1}(8) - \#_q \cW_{n,\Pb^1}(\check{4}) )
    \end{align*}

    When r is even:
    \begin{align*}
    \Nc(\Fb_q(t), B) &= 2 \cdot \Nc^w(\Fb_q(t),~B) + 4 \cdot ( \#_q\cW_{n,\Pb^1}(8) - \#_q \cW_{n,\Pb^1}(\check{4}) )
    \end{align*}

    \noindent We first compute the following by summing over $n \ge 2$ 
    \begin{align*}
    \sum_{n = 2}^{\left \lfloor \frac{log_q B}{12} \right \rfloor} \#_q\cW_{n,\Pb^1}(8) &= \frac{q^7 - 1}{q^7 - q^6} \cdot ( B^{2/3} - q^8 ) \\ 
    \sum_{n = 2}^{\left \lfloor \frac{log_q B}{12} \right \rfloor} \#_q\cW_{n,\Pb^1}(\check{4}) &= - \left( \frac{q^3 - 1}{q \cdot (q^3 - q^2)} \right) \cdot ( B^{1/3} - q^4 )
    \end{align*}

    which leads to the following as we sum over all $n \ge 0$:

    \begin{align*}
     \#_q\cW_{n,\Pb^1}(8) - \#_q \cW_{n,\Pb^1}(\check{4}) &= \left( \frac{q^7 - 1}{q^7 - q^6} \right) \cdot ( B^{2/3} - q^8 ) - \left( \frac{q^3 - 1}{q^4 - q^3} \right) \cdot ( B^{1/3} - q^4 ) \\
    &\phantom{=}\text{ } + (q^{8} + \ldots + q^{2}) - (q^{3} + q^{2} + q + 1) + 1 \\
    &= \left( \frac{q^{7}-1}{q^{7}-q^{6}} \right) B^{2/3} -  \left( \frac{q^{3} - 1}{q^{4}-q^3} \right) B^{1/3} \\
    \end{align*}

    from which the result follows.

    \bigskip

    We now prove for $q = 2^r$ case. We recall that the weighted count $\Nc^w(\Fb_q(t),~B)$ in \cite[Theorem 9.7]{BPS} is the same for all positive characteristic as shown in \cite[Proposition 4.12]{dJ2}. As for the unweighted count, we multiply $2$ to the weighted count $\Nc^w(\Fb_q(t),~B)$ since any stacky point away from $j=0$ has the hyperelliptic involution automorphism group of order 2 (c.f. \cite[Ap. A, Prop. 1.2]{Silverman}). There needs to be an adjustment, however, as the weighted number of rational points on $\Pc(2)$ and $\Pc(2) - \Pc(\check{1})$ differ at height $n=1$. The difference of $\left\{ \cW_{1}^{\mathrm{min}}(\Pc(2)) \right\} = \Lb^{2}$ and $\left\{ \cW_{1}^{\mathrm{min}}(\Pc(2) - \Pc(\check{1})) \right\} = \Lb^{2} - 1$ is $-1$. 

    \medskip

    Thus taking account of all points for every $j_{g} \neq 0$, we need to subtract $(q-1)$ from the total number of weighted count corresponding to $\mathcal{M}_{1,1} - \{ j=0 \}$ for a certain fixed $j_{g} \neq 0$. And then we need to add $1$ from the total number of weighted count as we subtract the rational points landing on $j = \infty$ since we do not want to count the generically singular $j = \infty$ isotrivial elliptic curves.

    \medskip

    %non-constant and isotrivial with  where 

    Lastly for $j=0$, we take the weighted count in Proposition \ref{prop:Wmin_preq_P2} and multiply appropriate factors which are $(3-2)=1$ for r odd case and $(7-2)=5$ for r even case depending on the parity of prime power of 2 as there are 3 isomorphism classes (resp. 7 isomorphism classes) of supersingular elliptic curves for r odd case (resp. r even case) (c.f. \cite[Thm. 3.6 \& 3.7]{Menezes}) and -2 comes from taking into account the hyperelliptic involution.

    \medskip  

    Thus for the unweighted count, we would like to compute the following. \\

    When r is odd:
    \begin{align*}
    \Nc(\Fb_q(t), B) &= 2 \cdot ( \Nc^w(\Fb_q(t),~B) - (q-1) + 1 ) + ( \#_q\cW_{n,\Pb^1}(9) - \#_q \cW_{n,\Pb^1}(\check{6}) )
    \end{align*}

    When r is even:
    \begin{align*}
    \Nc(\Fb_q(t), B) &= 2 \cdot ( \Nc^w(\Fb_q(t),~B) - (q-1) + 1 ) + 5 \cdot ( \#_q\cW_{n,\Pb^1}(9) - \#_q \cW_{n,\Pb^1}(\check{6}) )
    \end{align*}

    \noindent We first compute the following by summing over $n \ge 2$ 
    \begin{align*}
    \sum_{n = 2}^{\left \lfloor \frac{log_q B}{12} \right \rfloor} \#_q\cW_{n,\Pb^1}(9) &= \frac{q^8 - 1}{q^8 - q^7} \cdot ( B^{3/4} - q^9 ) \\ 
    \sum_{n = 2}^{\left \lfloor \frac{log_q B}{12} \right \rfloor} \#_q\cW_{n,\Pb^1}(\check{6}) &= - \left( \frac{q^5 - 1}{q \cdot (q^5 - q^4)} \right) \cdot ( B^{1/2} - q^6 )
    \end{align*}

    which leads to the following as we sum over all $n \ge 0$:

    \begin{align*}
     \#_q\cW_{n,\Pb^1}(9) - \#_q \cW_{n,\Pb^1}(\check{6}) &= \frac{q^8 - 1}{q^8 - q^7} \cdot ( B^{3/4} - q^9 ) - \left( \frac{q^5 - 1}{q^6 - q^5} \right) \cdot ( B^{1/2} - q^6 ) \\
    &\phantom{=}\text{ } + (q^{9} + \ldots + q^{2}) - (q^{5} + q^{4} + q^{3} + q^{2} + q + 1) + 1 \\
    &= \left( \frac{q^8 - 1}{q^8 - q^7} \right) B^{3/4} -  \left( \frac{q^5 - 1}{q^6 - q^5} \right) B^{1/2} \\
    \end{align*}

    from which the result follows.

    \begin{comment}

    \medskip

    For r odd,

    \begin{align*}
    \Nc(\Fb_q(t), B) =& (2\frac{q^9 - 1}{q^8 - q^7} \cdot B^{5/6} + 2) - (2B^{1/6} + 2) \\
    +& 2 \cdot \frac{q^7 - 1}{q^7 - q^6} \cdot B^{2/3} + 2 \\ 
    -& 2 \cdot \frac{q^3 - 1}{q \cdot (q^3 - q^2)} \cdot B^{1/3} - 2
    \end{align*}

    For r even,

    \begin{align*}
    \Nc(\Fb_q(t), B) =& (2\frac{q^9 - 1}{q^8 - q^7} \cdot B^{5/6} + 2) - (2B^{1/6} + 2) \\
    +& 4 \cdot \frac{q^7 - 1}{q^7 - q^6} \cdot B^{2/3} + 4 \\ 
    -& 4 \cdot \frac{q^3 - 1}{q \cdot (q^3 - q^2)} \cdot B^{1/3} - 4
    \end{align*}

    \end{comment}





    \end{proof}



