	\section{Proofs of Theorems}\label{SecC}
    \subsection{Proof of Theorem~\ref{theorem1}}\label{SecC.1}


		We begin the proof with defining some notation.
		Let  
        $$g^{\star} = \argmin_{g\in\mathcal{I}_{L, w_0}} \sum_{i=1}^n \left(U_i - F(g, \boldsymbol{X}_i)\right)^2,$$ 
        and that $g^{(b)}(\vv{x}) = \boldsymbol{1}\{ \vv{u}^{\top}\vv{f}(\vv{x}) > c\}$ for some unit-length weight vector $\vv{u}$, bias $c\in  \mathbb{R}$, and $\vv{f}\in \mathcal{F}_{L-1, w_0}$. Suppose there are $L_1$ idle neuron units in $\boldsymbol{1}\{ \vv{u}^{\top}\vv{f}(\vv{x}) > c\}$, and let their indices be denoted by $\{(l_{k}, h_{k})\}_{k=1}^{L_1}$ for some $l_{k} \in \{1, \dots, L-1\}$ and $h_{k} \in \{1 , \dots, p_{l_{k}}\}$. Let $\{(\vv{w}_{l_k, h_k}, c_{l_k, h_k})\}_{k=1}^{L_{1}}$ denote the corresponding weight vectors and biases of the idle neuron units of $\boldsymbol{1}\{ \vv{u}^{\top}\vv{f}(\vv{x}) > c\}$.


Now, in light of Condition \ref{sparsity.1}, there exists a function $\vv{f}^\star \in \mathcal{F}_{L-1, w_0}$ such that $g_2(\vv{x}) = \boldsymbol{1}\{ \vv{u}^{\top} \vv{f}^\star(\vv{x}) > c \}$, where $ \boldsymbol{1}\{ \vv{u}^{\top} \vv{f}^\star(\vv{x}) > c \}$ is a function whose active neuron units share the same weights and biases as those of $ \boldsymbol{1}\{ \vv{u}^{\top} \vv{f}(\vv{x}) > c \}$. This implies $g_2(\vv{x}) = g^{(b)}(\vv{x})$. Furthermore,  $g^\star(\vv{x}) = \boldsymbol{1}\{ (\vv{u}')^{\top} \vv{f}^\star(\vv{x}) > c' \}$, for some unit-length  $\vv{u}^{'}$ with $\|\vv{u}'\|_0 \le w_0$ and $c' \in \mathbb{R}$. Additionally, the sets of active neuron unit indices for $ \boldsymbol{1}\{ \vv{u}^{\top} \vv{f}^\star(\vv{x}) > c \}$ and $\boldsymbol{1}\{ (\vv{u}')^{\top} \vv{f}^\star(\vv{x}) > c' \}$ are disjoint. Denote the weights and biases of the $(l_k, h_k)$ unit in $g_2(\vv{x})$ by $(\vv{w}_{l_k, h_k}^{\dagger}, c_{l_k, h_k}^{\dagger})$ for each $k \in \{1, \dots, L_1\}$. Without loss of generality, we assume that each pair of weights and biases is nontrivial, in the sense that it defines two subsamples, each of size greater than 0 but less than $n$. 


Next, we define two pairs of weights and biases as sample-equivalent if they induce identical partitions of the input indices. It is worth noting that the input vectors may refer either to the original feature vectors $\boldsymbol{X}_1, \dots, \boldsymbol{X}_n$, or to the binary outputs produced by the preceding layer. At the end of 
$b$th update round, define 
		$$\mathcal{B}_{b} = \{(\vv{w}_{l_k, h_k}^{\dagger}, c_{l_k, h_k}^{\dagger}) \text{ and } (\vv{w}_{l_k, h_k}, c_{l_k, h_k}) \text{ are sample-equivalent  for all } k \in \{1, \dots, L_1\}\},$$
    where we remark that the weights and biases are functions of $b$, though this dependence is suppressed to simplify the notation. 


    % as defined in equation~\eqref{sample-euquivalent} of Lemma~\ref{lemma10}


By Lemma~\ref{lemma10}, the definition of each $(\vv{w}_{l_k, h_k}, c_{l_k, h_k})$ according to Exploit-Explore Optimizing from Section~\ref{sec3.1} and Section~\ref{sec3.1.2} (recall that the updated weights and biases at each optimization step are uniformly sampled from $K+1$ parameter candidates for each idle neuron), the nontriviality of the pairs $(\vv{w}_{l_k, h_k}^{\dagger}, c_{l_k, h_k}^{\dagger})$, and the finiteness of $L_1$ and $n$, the probability of the event $\mathcal{B}_b$ is positively bounded away from zero by some constant $\varepsilon > 0$ that is independent of $b$, the current configuration of active units in $\boldsymbol{1}\{ \vv{u}^{\top}\vv{f}(\vv{x}) > c\}$, and the indices of idle neurons. This lower bound depends on the input sample, which is conditioned on and thus treated as fixed. In particular, for each $b \ge 1$, we have
$$
\mathbb{P}(\mathcal{B}_b \mid \mathcal{X}_n, \boldsymbol{1}_{\mathcal{B}_1^c}, \dots, \boldsymbol{1}_{\mathcal{B}_{b-1}^c}) \ge \varepsilon,
$$
where $\boldsymbol{1}_{\mathcal{B}_0^c}$ is defined to be zero.
 As a result,
		\begin{equation}
			\label{proposition.sure.2}
            \begin{split}
            \mathbb{P}\left( \bigcup_{l=1}^b \mathcal{B}_{l} \mid \mathcal{X}_n\right) & = 1 - \mathbb{P}\left( \bigcap_{l=1}^b \mathcal{B}_{l}^c \mid \mathcal{X}_n \right) \\
            & = 1-  \mathbb{E}[ \prod_{l=1}^{b-1} \boldsymbol{1}_{\mathcal{B}_{l}^c} \times \mathbb{E}( \boldsymbol{1}_{\mathcal{B}_{b}^c} |  \mathcal{X}_n, \boldsymbol{1}_{\mathcal{B}_{1}^c}, \dots, \boldsymbol{1}_{\mathcal{B}_{b-1}^c} ) \mid \mathcal{X}_n] \\
            & \ge \cdots \\
            & \ge 1 - (1 - \epsilon)^b.
            \end{split}
		\end{equation}


Now, let us turn to the output layer. On the event $\mathcal{B}_b$, regardless of the current status of active units, Lemma \ref{lemma10} guarantees a positive probability of sampling the optimal pair of weights and bias for the $(L,1)$th output neuron at the $(b+1)$th update round. In this context, the outputs of the $(L-1)$th layer are regarded as input vectors for the application of Lemma~\ref{lemma10}. Once this optimal pair is sampled, Exploit-Explore Optimizing ensures that
$$
\sum_{i=1}^n \left(U_i - F(g^{(b+1)}, \boldsymbol{X}_i)\right)^2 = \inf_{g \in \mathcal{I}_{L, w_0}} \sum_{i=1}^n \left(U_i - F(g, \boldsymbol{X}_i)\right).
$$
Moreover, since each optimization step includes the current model as a candidate (i.e., $g_{K+1}$ in \eqref{eew.opti}), it follows that
$$
\sum_{i=1}^n \left(U_i - F(g^{(b_1)}, \boldsymbol{X}_i)\right)^2 = \inf_{g \in \mathcal{I}_{L, w_0}} \sum_{i=1}^n \left(U_i - F(g, \boldsymbol{X}_i)\right)
$$
for every $b_1 > b$.


        With \eqref{proposition.sure.2} and the arguments above, we have completed the proof of Theorem~\ref{theorem1}.



    \subsection{Proof of Theorem~\ref{theorem2}}\label{SecC.2}

The proof of Theorem \ref{theorem2} closely follows that of Theorem 1 in \citep{temlyakov2000weak}, but with a major distinction stemming from its application to boosting prediction. We provide a self-contained proof below, employing only auxiliary lemmas from \citep{temlyakov2000weak}.

	By \eqref{lemma2.1} and recursively applying \eqref{pursuit.1}, we derive that
		\begin{equation}
			\begin{split}\label{theorem.appr.3}
				m_{s}(\boldsymbol{X}) & = m(\boldsymbol{X}) - \gamma\sum_{q=1}^{s}  \sum_{l=0}^{1} \frac{\boldsymbol{1}\{ g_{q}(\vv{x}) = l\} }{\sqrt{\mathbb{P}(g_{q}(\boldsymbol{X}) =l) }} \times \mathbb{E}( \frac{\boldsymbol{1}\{ g_{q}(\boldsymbol{X}) = l\} }{\sqrt{\mathbb{P}(g_{q}(\boldsymbol{X}) =l) }} m_{q-1}(\boldsymbol{X})) \\
                & = m(\boldsymbol{X}) - \widehat{m}_{s}(\boldsymbol{X}),
			\end{split}
		\end{equation}
		and for $s>q>0$,
		\begin{equation}
			\begin{split}\label{theorem.appr.4}
				\mathbb{E}(m_{s}(\boldsymbol{X}))^2 & = \mathbb{E}(m_{s-1}(\boldsymbol{X}))^2 + \gamma^2 \times \mathcal{P}(g_s, m_{s-1}(\boldsymbol{X})) - 2 \gamma \times \mathcal{P}(g_s, m_{s-1}(\boldsymbol{X})) \\
				& = \mathbb{E}(m_{q}(\boldsymbol{X}))^2  - \sum_{l=q+1}^{s}\gamma(2-\gamma)\mathcal{P}(g_l, m_{l-1}(\boldsymbol{X}))\\
				& = \mathbb{E}(m(\boldsymbol{X}))^2  - \gamma(2-\gamma)\sum_{l=1}^{s}\mathcal{P}(g_l, m_{l-1}(\boldsymbol{X})).
			\end{split}
		\end{equation}


		With \eqref{theorem.appr.4}, we deduce that 
		\begin{equation}\label{theorem.appr.7}
			\sum_{q=1}^{\infty}\mathcal{P}(g_q, m_{q-1}(\boldsymbol{X})) \le \frac{\mathbb{E}(m(\boldsymbol{X}))^2}{\gamma(2-\gamma)} < \infty.
		\end{equation}
        Additionally, a direct calculation shows that for every $s>q$,
		{\small\begin{equation}
				\begin{split}\label{theorem.appr.5}
					\mathbb{E}(m_{s}(\boldsymbol{X}) - m_{q}(\boldsymbol{X}))^2  
					& = \mathbb{E}(m_q(\boldsymbol{X}))^2  - \mathbb{E}(m_s(\boldsymbol{X}))^2 - 2\mathbb{E}[(m_{q}(\boldsymbol{X}) - m_{s}(\boldsymbol{X})) m_{s}(\boldsymbol{X}) ].
				\end{split}
		\end{equation}}%

Using \eqref{theorem.appr.7}–\eqref{theorem.appr.5} and Lemma 2.4 of \citep{temlyakov2000weak}, it suffices to show that the absolute value of the second term in \eqref{theorem.appr.5} tends to zero as \eqref{convergence.sequence} below, in order to conclude that $m_s(\boldsymbol{X})$ converges in the $L_2$-norm (as in \eqref{theorem.appr.10} below).


		For each $i>0$ and each $l\in \{0, 1\}$, denote $a_i(l) = |\mathbb{E}( \frac{\boldsymbol{1}\{g_i(\boldsymbol{X}) = l\}}{ \sqrt{\mathbb{P}(g_i(\boldsymbol{X}) = l) } } m_{i-1}(\boldsymbol{X}))|$. In light of \eqref{theorem.appr.3}, we deduce that for every $s> q$,
		\begin{equation}
			\begin{split}\label{theorem.appr.6}
				& |\mathbb{E}[(m_{q}(\boldsymbol{X}) - m_{s}(\boldsymbol{X})) m_{s}(\boldsymbol{X}) ] | \\
				& \le \gamma\sum_{i=q+1}^{s}  \sum_{l=0}^{1} \frac{ |\mathbb{E}(m_{s}(\boldsymbol{X})\boldsymbol{1}\{g_i(\boldsymbol{X}) = l\})| }{\sqrt{\mathbb{P}(g_i(\boldsymbol{X}) = l) }} \times a_{i}(l) \\
				& \le \gamma\sum_{i=q+1}^{s} \sqrt{ \mathcal{P}(g_i, m_s(\boldsymbol{X})) } \sum_{l=0}^{1}   a_{i}(l) \\
				& \le \gamma\sum_{i=q+1}^{s} \sqrt{  \mathcal{P}(g_{s+1}, m_s(\boldsymbol{X})) t^{-1}} \sum_{l=0}^{1}   a_{i}(l)\\
				& \le \gamma \sqrt{  \mathcal{P}(g_{s+1}, m_s(\boldsymbol{X})) t^{-1}}\sum_{i=q+1}^{s} \sqrt{ 2 \mathcal{P}(g_{i}, m_{i-1}(\boldsymbol{X}))}.
			\end{split}
		\end{equation}
		The second inequality holds because
		$$\frac{ |\mathbb{E}(m_{s}(\boldsymbol{X})\boldsymbol{1}\{g(\boldsymbol{X}) = l\})| }{\sqrt{\mathbb{P}(g(\boldsymbol{X}) = l) }} \le \sqrt{\sum_{l=0}^{1} [\frac{ |\mathbb{E}(m_{s}(\boldsymbol{X})\boldsymbol{1}\{g(\boldsymbol{X}) = l\})| }{\sqrt{\mathbb{P}(g(\boldsymbol{X}) = l) }}]^2 } = \sqrt{ \mathcal{P}(g, m_s(\boldsymbol{X})) }$$ 
		for each $g \in \mathcal{I}_{L, w_0}$. The third inequality follows from that the definition of $g_{s+1}$ and \eqref{pursuit.1}. The fourth inequlaity results from the definition of $a_{i}(l)$ and that
		\begin{equation*}
			\begin{split}
				\left(\sum_{l=0}^{1}   a_{i}(l) \right)^2 \le 2\sum_{l=0}^{1}  \left( a_{i}(l) \right)^2 =  2\mathcal{P}(g_{i}, m_{i-1}(\boldsymbol{X})).
			\end{split}    
		\end{equation*}



		By \eqref{theorem.appr.7}, Lemma 2.3 of \citep{temlyakov2000weak}, and \eqref{theorem.appr.6}, we conclude that  
        \begin{equation}
            \label{convergence.sequence}
            \lim_{s\rightarrow\infty}\max_{q< s}\left|\mathbb{E}[(m_q(\boldsymbol{X}) - m_s(\boldsymbol{X})) m_s(\boldsymbol{X})] \right| = 0.
        \end{equation}        
        Furthermore, from \eqref{theorem.appr.4}--\eqref{theorem.appr.7} and the Monotone Convergence Theorem for sequences of real numbers, it follows that \( \mathbb{E}[(m_s(\boldsymbol{X}))^2] \) converges. Combining the result of \eqref{convergence.sequence}, the convergence of $\mathbb{E}[(m_s(\boldsymbol{X}))^2]$, \eqref{theorem.appr.5}, and Lemma 2.4 from \citep{temlyakov2000weak}, we conclude that $m_s(\boldsymbol{X})$ converges in the $L_2$-norm.



		Next, we prove by contradiction that $m_{s}(\boldsymbol{X})$ converges to the zero function with $\lim_{s\rightarrow\infty}\mathbb{E}(m_{s}(\boldsymbol{X}))^2 = 0$. By Lemma \ref{universal.lemma.1} and the definition of $\overline{\mathcal{D}}$, both \(m(\boldsymbol{X})\) and each \(m_s(\boldsymbol{X})\) lie, by construction, in $\overline{\mathcal{D}}$. In light of the definition of $\overline{\mathcal{D}}$, we conclude that
		\begin{equation}
			\label{theorem.appr.10}
			\lim_{s\rightarrow\infty }\mathbb{E}[m_{s}(\boldsymbol{X}) - \nu(\boldsymbol{X})]^2 =0
		\end{equation}
		for some measurable function $\nu:\mathbb{R}^{p}\longmapsto\mathbb{R}$ in $\overline{\mathcal{D}}$. In what follows, we consider the nontrivial case where \(\mathbb{E}[\nu(\boldsymbol{X})]^2 > 0\). 


		For some $\delta >0$, some $g\in\mathcal{I}_{L, w_0}$, and some $l\in \{0, 1\}$, it holds that 
		\begin{equation}
			\label{theorem.appr.9}
			| \mathbb{E}( \nu(\boldsymbol{X})\times \frac{\boldsymbol{1}\{g(\boldsymbol{X}) = l\}}{ \sqrt{\mathbb{P}(g(\boldsymbol{X}) = l) } }) | \ge 2\delta.
		\end{equation}
		For if not, then $\mathbb{E}(\nu(\boldsymbol{X})\times \frac{\boldsymbol{1}\{g(\boldsymbol{X}) = l\}}{ \sqrt{\mathbb{P}(g(\boldsymbol{X}) = l) } } ) = 0$ for every $g\in \mathcal{I}_{L, w_0}$ and each $l\in \{0, 1\}$, implying that $\mathbb{E}[f_{m}(\boldsymbol{X}) - \nu(\boldsymbol{X})]^2 = \mathbb{E}[f_m(\boldsymbol{X})]^2  +\mathbb{E}[\nu(\boldsymbol{X})]^2 \ge \mathbb{E}[\nu(\boldsymbol{X})]^2  >0$ for every $f_m \in \mathcal{D}$. Such a result contradicts the fact that $\nu(\boldsymbol{X}) \in \overline{\mathcal{D}}$, i.e., there exist $f_m \in \mathcal{D}$ with $\mathbb{E}[(f_m(\boldsymbol{X}) - \nu(\boldsymbol{X}))^2] \to 0$.





		By \eqref{theorem.appr.10}--\eqref{theorem.appr.9} and the definitions of $\mathcal{I}_{L, w_0}$, there exists $N_0>0$, $l\in \{0, 1\}$, and $g \in \mathcal{I}_{L, w_0}$ such that $| \mathbb{E}( \frac{\boldsymbol{1}\{g(\boldsymbol{X}) = l\}}{ \sqrt{\mathbb{P}(g(\boldsymbol{X}) = l) } } m_q(\boldsymbol{X})) | \ge \delta$ for all $q > N_0$. Therefore, 
		for all $q > N_0$, 
		\begin{equation}
			\label{theorem.appr.15}
			\sup_{g\in \mathcal{I}_{L, w_0}}\mathcal{P}(g, m_{q}(\boldsymbol{X})) \ge \delta^2.
		\end{equation}


		By the definition of $g_s$'s in \eqref{pursuit.1}, \eqref{theorem.appr.4}, and \eqref{theorem.appr.15},  we derive that for each $s > q > N_{0}$,
		\begin{equation}
			\begin{split}\label{theorem.appr.2}
				\mathbb{E}(m_{s}(\boldsymbol{X}))^2 & \le  \mathbb{E}(m_{q}(\boldsymbol{X}))^2  -  \gamma(2-\gamma) \delta^2 \sum_{i>q}^s t^{-2}.
			\end{split}
		\end{equation}
		This result contradicts the non-negativity of \(\mathbb{E}[m_s(\boldsymbol{X})]^2 \ge 0\). Hence, we conclude the desired result  that $\lim_{s\rightarrow\infty}\mathbb{E}(m_{s}(\boldsymbol{X}))^2 = 0$. 

	By this result and \eqref{theorem.appr.3}, we have completed the proof of Theorem~\ref{theorem2}.






