\section{Proofs of Lemmas}\label{SecD}
    \subsection{Proof of Lemma~\ref{lemma10}}\label{SecD.1}



		We begin the proof by showing that, for a given pair $(\vv{w}, c)$, there exists a set of weight–bias pairs $\mathcal{A}(\vv{w}, c)$ such that \textnormal{(1)} $\{ \vv{w}' : (\vv{w}', c') \in \mathcal{A}(\vv{w}, c) \}$ is measurable with positive surface measure  on the  $k$-dimensional unit sphere, and \textnormal{(2)} $\{\vv{u} \in \mathcal{N}: (\vv{w}^{'})^{\top}\vv{u} - c^{'} > 0\} = \{\vv{u} \in \mathcal{N}: \vv{w}^{\top}\vv{u} - c > 0\}$ for every $(\vv{w}^{'}, c^{'}) \in \mathcal{A}(\vv{w}, c)$.

		In what follows, we prove the above claim. First, 
		define $\delta>0$ such that $2\delta = \min\{1, \min \{ a  :\vv{u}\in\mathcal{N}, a = \vv{w}^{\top} \vv{u} - c > 0 \}\}$, where we define $\min\{ \emptyset\} = \infty$. Then, $\{ \vv{u}\in\mathcal{N}: \vv{w}^{\top} \vv{u} - c - \delta >0\} = \{ \vv{u}\in\mathcal{N}: \vv{w}^{\top} \vv{u} - c > 0\} \eqqcolon\mathcal{N}_{+}$. Additionally, define 
		$$\mathcal{A}(\vv{w}, c) = \{ (\vv{w}^{'}, c^{'}): \norm{\vv{w}^{'} - \vv{w}}_2 \le \frac{\delta}{4\sqrt{k}}, \norm{\vv{w}^{'} }_2 = 1 , |c^{'} - (c + \frac{1}{2}\delta)| < \frac{\delta}{4}\},$$
		and notice that $\mathcal{A}(\vv{w}, c)$ satisfies the first requirement listed above: $\{ \vv{w}' : (\vv{w}', c') \in \mathcal{A}(\vv{w}, c) \}$ is measurable  with some positive surface measure $\varepsilon(\vv{w}, c) > 0$ on the  $k$-dimensional unit sphere.

		For each $\vv{u}\in \mathcal{N}_{+}$ and $(\vv{w}^{'}, c^{'}) \in \mathcal{A}(\vv{w}, c)$, it holds that 
		$$(\vv{w}^{'})^{\top} \vv{u} - c^{'} > \vv{w}^{\top} \vv{u}  - \frac{\delta}{4} - (c+ \frac{\delta}{2}) - \frac{\delta}{4}\ge \min\{\vv{w}^{\top} \vv{u} - c - \delta, \vv{w}^{\top} \vv{u} - c \} > 0, $$
		where the first inequality holds because  $\norm{ (\vv{w}^{'} - \vv{w})^{\top} \vv{u} }_2 \le \frac{\delta}{4\sqrt{k}} \sqrt{k}$ due to the Cauchy-Schwarz inequality (recall that $\mathcal{N}$ consists of elements from $[0, 1]^k$, and therefore $\norm{\vv{u}}_2 \le \sqrt{k}$) and $|c^{'} - (c + \frac{1}{2}\delta)| < \frac{\delta}{4}$. The second and third inequalities result from the definition of $\delta$. By these results and the definition of $\mathcal{N}_{+}$, it holds that  $\mathcal{A}(\vv{w}, c)$ satisfies the second requirement listed above: $\{\vv{u} \in \mathcal{N}: (\vv{w}^{'})^{\top}\vv{u} - c^{'} > 0\} = \{\vv{u} \in \mathcal{N}: \vv{w}^{\top}\vv{u} - c > 0\}$ for every $(\vv{w}^{'}, c^{'}) \in \mathcal{A}(\vv{w}, c)$.

		Next, note that the above arguments applies to each distinct sample separation, and that there are at most $2^{\texttt{\#}\mathcal{N}}$  distinct ways to separate $\mathcal{N}$ into two subsamples by hyperplanes. For each separation, we can pick up a representative split. Eventually, we collect a finite set of representative splits, denoted by $\{(\vv{w}_{l}^{\dagger}, c_{l}^{\dagger})\}_{l=1}^{L_0}$ for some integer $L_0>0$. Furthermore, each of these splits correspond to a measure lower bound $\varepsilon(\vv{w}_{l}^{\dagger}, c_{l}^{\dagger}) >0$. As there are finitely many distinct separations, we conclude that $\varepsilon = \min_{1\le l\le  L_0} \varepsilon(\vv{w}_{l}^{\dagger}, c_{l}^{\dagger}) >0$. 



		Define $\mathcal{E}(\vv{w}, c) = \{ \vv{w}' : (\vv{w}', c') \in \mathcal{A}(\vv{w}, c) \}$. To conclude the proof, let us observe that for each pair $(\vv{w}, c)$, there exists some $\vv{v}\in \mathcal{N}$ such that $\{\vv{u} \in \mathcal{N}: \vv{w}^{\top}\vv{u} - \vv{w}^{\top}\vv{v} > 0\} = \{\vv{u} \in \mathcal{N}: \vv{w}^{\top}\vv{u} - c > 0\}$ when $\texttt{\#} \{\vv{u} \in \mathcal{N}: \vv{w}^{\top}\vv{u} - c > 0\} < \texttt{\#} \mathcal{N}$. By this and the construction of $\mathcal{E}(\vv{w}, c)$, we have completed the proof of Lemma~\ref{lemma10}.


    \subsection{Proof of Lemma~\ref{lemma2}}\label{SecD.2}


    By the definition of $ F_s(g, \vv{x})$ in \eqref{update.1} under finite sample setting, it holds for each $g\in\mathcal{I}_{L, w_0}$ that 
	\begin{equation}
		\begin{split}
			\label{sec2.eq1}
	  \sum_{i=1}^{n} (m_{s-1}(\boldsymbol{X}_i) - F_s(g, \boldsymbol{X}_i))^2 & =   (\sum_{i=1}^{n} m_{s-1}(\boldsymbol{X}_i)^2 ) - \sum_{i=1}^{n} (F_s(g, \boldsymbol{X}_i))^2,\\       
       F_{s}(g, \vv{x}) & = \frac{\sum_{i=1}^{n} m_{s-1}(\boldsymbol{X}_i) \times  \boldsymbol{1}\{g(\boldsymbol{X}_i) = g(\vv{x}) \} }{\sum_{i=1}^{n} \boldsymbol{1}\{g(\boldsymbol{X}_i) = g(\vv{x}) \} } \\
			& = \sum_{l=0}^{1}\frac{n^{-1}\sum_{i=1}^{n} m_{s-1}(\boldsymbol{X}_i) \times  \boldsymbol{1}\{g(\boldsymbol{X}_i) = l \} }{ \sqrt{ n^{-1}\sum_{i=1}^{n} \boldsymbol{1}\{g(\boldsymbol{X}_i) = l \} } }\\
            & \quad\times \frac{ \boldsymbol{1}\{g(\vv{x}) = l \}  }{ \sqrt{ n^{-1}\sum_{i=1}^{n} \boldsymbol{1}\{g(\boldsymbol{X}_i) = l \} } },
		\end{split}
	\end{equation}
which, in combination with $n^{-1}\sum_{i=1}^{n} \big(\frac{ \boldsymbol{1}\{g(\boldsymbol{X}_i) = l \}  }{ \sqrt{ n^{-1}\sum_{q=1}^{n} \boldsymbol{1}\{g(\boldsymbol{X}_q) = l \} } } \big)^2 = 1$  for $l\in \{0, 1\}$ and $\boldsymbol{1}\{g(\boldsymbol{X}_i) = 0 \}\times \boldsymbol{1}\{g(\boldsymbol{X}_i) = 1 \} = 0$, concludes that 
\begin{equation}
    \begin{split}\label{sec2.eq3}
        n^{-1}\sum_{i=1}^{n} (F_s(g, \boldsymbol{X}_i))^2 & = \sum_{l=0}^{1} \left(\frac{n^{-1} \sum_{q=1}^{n} m_{s-1}(\boldsymbol{X}_q) \times  \boldsymbol{1}\{g(\boldsymbol{X}_q) = l \} }{ \sqrt{ n^{-1}\sum_{q=1}^{n} \boldsymbol{1}\{g(\boldsymbol{X}_q) = l \} } } \right)^2.
    \end{split}
\end{equation}


The results in \eqref{sec2.eq1}--\eqref{sec2.eq3} imply that, in the update rule \eqref{update.1},
\begin{equation}		
		\begin{split}\label{sec2.eq4}
g_s & = \argmax_{g \in \mathcal{I}_{L, w_0} } \sum_{l=0}^{1} \left(\frac{n^{-1} \sum_{q=1}^{n} m_{s-1}(\boldsymbol{X}_q) \times  \boldsymbol{1}\{g(\boldsymbol{X}_q) = l \} }{ \sqrt{ n^{-1}\sum_{q=1}^{n} \boldsymbol{1}\{g(\boldsymbol{X}_q) = l \} } } \right)^2.
\end{split}
	\end{equation}

According to \eqref{sec2.eq1} and \eqref{sec2.eq4} and the definition of the infinite-sample boosted 01Neuro, which has been introduced in Section~\ref{Sec4.new}, the infinite-sample analogue of \eqref{update.1} is given by
\begin{equation}		
		\begin{split}
			F_{s}(g, \vv{x}) &= \sum_{l=0}^{1} \frac{\boldsymbol{1}\{ g(\vv{x}) = l\} }{\sqrt{\mathbb{P}(g(\boldsymbol{X}) =l) }} \times \mathbb{E}( \frac{\boldsymbol{1}\{ g(\boldsymbol{X}) = l\} }{\sqrt{\mathbb{P}(g(\boldsymbol{X}) =l) }} m_{s-1}(\boldsymbol{X})),\\
			g_s & = \argmax_{g \in \mathcal{I}_{L, w_0} }\sum_{l=0}^{1} \left[\mathbb{E}\left( \frac{\boldsymbol{1}\{ g(\boldsymbol{X}) = l\} \times  m_{s-1}(\boldsymbol{X})}{\sqrt{\mathbb{P}(g(\boldsymbol{X}) =l) }} \right) \right]^2, \\
		m_{s}(\boldsymbol{X}) &= m_{s-1}(\boldsymbol{X}) - \gamma F_{s}(g_s, \boldsymbol{X}),    
		\end{split}
	\end{equation}
    which concludes \eqref{pursuit.1}.



    \subsection{Proof of Lemma~\ref{universal.lemma.1}}\label{SecD.3}



We begin the proof by demonstrating that the class $\mathcal{D}$ includes all linear combinations of finitely many rectangular indicator functions, where each indicator function depends on only $k$ coordinates. Note that it suffices to show that an 01Neuro with configuration $w_0 = 2$ and $L= 2 + \lceil \log_{2} k \rceil$ can approximate any rectangular indicator function depending on $k$-coordinates. Specifically, for any rectangle $R' = [a_1, b_1] \times \cdots \times [a_k, b_k] \subset [0, 1]^k$, any index set $\{i_1, \dots, i_k\} \subset \{1, \dots, p\}$, and the corresponding set
$R = \left\{ \vv{x} \in [0,1]^p : (x_{i_1}, \dots, x_{i_k}) \in R' \right\},$ we construct a 01Neuro with $w_0 = 2$ and $L= 2 + \lceil \log_{2} k \rceil$ as follows. The following construction adheres to the Exploit-Explore Optimizing method introduced in Section~\ref{sec3.1}, including the use of $w_0$-sparse unit-length weight vectors and specific bias sampling rules.


    For the first and second layers, we construct that $f_{2, q}(\vv{x}) = \boldsymbol{1}\{\frac{\sqrt{2}}{2}f_{1, 2q - 1} (\vv{x})- \frac{\sqrt{2}}{2}f_{1, 2q} (\vv{x}) >0\}$,  $f_{1, 2q-1}(\vv{x}) =\boldsymbol{1}\{ x_{i_{q}}> a_q\}$, and $f_{1, 2q}(\vv{x}) = \boldsymbol{1}\{ x_{i_{q}}> b_q\}$ for $q\in \{1, \dots, k\}$. Eventually, we shall see that there are exactly $a_2 = k$ and $a_1 = 2k$ active units respectively at the second and first layers.


    For the third layer, we construct that $f_{3, r}(\vv{x}) = \boldsymbol{1}\{\frac{\sqrt{2}}{2} f_{2, 2r - 1} (\vv{x}) +  \frac{\sqrt{2}}{2} f_{2, 2r} (\vv{x}) > \frac{\sqrt{2}}{2} \}$ for $r \in \{1, \dots, \lfloor\frac{k}{2} \rfloor\}$ and $f_{3, \lceil\frac{k}{2} \rceil }(\vv{x}) = \boldsymbol{1}\{f_{2, k} (\vv{x})  > 0 \}$ if $\frac{k}{2} > \lfloor\frac{k}{2} \rfloor$. Eventually, we shall see that there are at most $a_3 = \lceil\frac{k}{2} \rceil = \lceil\frac{a_2}{2} \rceil$ active units at the third layer. The $l$th layer, for $l > 3$, is defined in a manner analogous to the third layer, implying that there are at most $a_l = \lceil \frac{a_{l-1}}{2} \rceil$ active units at layer $l$.

We repeat this construction until we reach the output layer and construct $f_{L, 1}(\vv{x}) = \boldsymbol{1}\{\frac{\sqrt{2}}{2} f_{L-1, 1}(\vv{x}) + \frac{\sqrt{2}}{2} f_{L-1, 2}(\vv{x}) > \frac{\sqrt{2}}{2}\}$, where we define $a_L = 1$. A simple calculation shows that $L = 2 + \lceil \log_2 k \rceil = \min\{ l : a_l = 1 \}$, which is the minimum depth $L$ needed for the constructed network $f_{L, 1}(\vv{x})$.


Now, the construction of $f_{L, 1}(\vv{x})$ forms the desired rectangular indicator function, yielding
$$\int_{[0, 1]^p} \Big| f_{L, 1}(\vv{x}) - \boldsymbol{1}\{\vv{x} \in R\} \Big| d\vv{x} = 0,$$
and implying that
$$\inf_{f \in \mathcal{I}_{L, w_0}} \int_{[0, 1]^p} \Big| f(\vv{x}) - \boldsymbol{1}\{\vv{x} \in R\} \Big| d\vv{x} = 0.$$
Such a results and the definition of $\mathcal{D}$ conclude that $\mathcal{D}$ includes all linear combinations of finitely many rectangular indicator functions, where each indicator function depends on only $k$ coordinates.

On the other hand, it is well known that $p$-dimensional step functions, defined as linear combinations of finitely many rectangular indicator functions, each depending on at most $p$ coordinates, can approximate any measurable function on a compact domain, such as $[0, 1]^p$, in the Lebesgue measure sense~\citep{stein2009real, cohn2013measure}. However, since our focus is on the distribution of $\boldsymbol{X}$ rather than the Lebesgue measure, we assume in Condition~\ref{dist.1} that $\boldsymbol{X}$ has a bounded probability density function to apply existing results. Under this assumption, there exists a constants $C_2 > 0$ such that for any measurable function $f: [0, 1]^p \to \mathbb{R}$,
$$
 \mathbb{E}[f^2(\boldsymbol{X})] \le C_2 \int_{[0,1]^p} f^2(\vv{x})\, d\vv{x}.
$$
This equivalence between $L_2$-norms under the probability measure and the Lebesgue measure allows us to apply standard approximation results~\citep{cohn2013measure, stein2009real}.

In particular, by arguments similar to those in Proposition 3.4.3 of~\citep{cohn2013measure} and Theorem 4.3 of~\citep{stein2009real}, the class $\overline{\mathcal{D}}$ contains $\mathcal{L}(k)$. That is, for every $m \in \mathcal{L}(k)$, there exists a sequence $f_i \in \mathcal{D}$ such that $\lim_{i \to \infty} \mathbb{E}\big[(m(\boldsymbol{X}) - f_i(\boldsymbol{X}))^2\big] = 0$. Here, we highlight two extensions in our setting in comparison to the similar results presented in \citep{stein2009real, cohn2013measure}: first, we consider the distribution of $\boldsymbol{X}$ instead of the Lebesgue measure, and second, we account for $k$-sparse measurable functions in $\mathcal{L}(k)$. Nevertheless, with Condition~\ref{dist.1}, the standard arguments in the cited references apply directly, and the detailed proof is omitted for simplicity.




To finish the proof of Lemma~\ref{universal.lemma.1}, note that by the previous results it holds that for each $m^{(r)}\in\mathcal{L}(k)$, there exists $f_{i}^{(r)}\in \mathcal{D}$ such that $\mathbb{E}\big[(m^{(r)}(\boldsymbol{X}) - f_i^{(r)}(\boldsymbol{X}))^2\big]$ approaches zero. By this result and an application of the Minkowski inequality, it holds that 
$$\sqrt{ \mathbb{E} \{ [ \sum_{r=1}^{R_0} m^{(r)}(\boldsymbol{X}) ] - \sum_{r=1}^{R_0} f_i^{(r)}(\boldsymbol{X})\}^2}\le \sum_{r=1}^{R_0} \sqrt{\mathbb{E}\big[(m^{(r)}(\boldsymbol{X}) - f_i^{(r)}(\boldsymbol{X}))^2\big]} \rightarrow 0 \textnormal{ as } i \rightarrow \infty,$$
which, in combination with the facts that $\sum_{r=1}^{R_0} m^{(r)} \in \mathcal{L}(k, R_{0})$ and $\sum_{r=1}^{R_0} f_i^{(r)} \in \mathcal{D}$, concludes the desired results that $\overline{\mathcal{D}}$ contains $\mathcal{L}(k, R_{0})$. We have  completed the proof of Lemma~\ref{universal.lemma.1}.


