    \caption{SME at 20th percentile}
    \label{fig:sme20}
  \end{subfigure}
  \begin{subfigure}{0.32\textwidth}
    \includegraphics[width=\linewidth]{figs/sme50}
    \caption{SME at 50th percentile}
