    \includegraphics[clip, width=.85\linewidth, trim={0 0 0 0.65cm},]{Figures/bitrate_boxes_obss_80_80.pdf}
    \caption{VF-RTT and target bitrate under Scenario~1, considering a single 80~MHz OBSS.
