% Our notion of scheduler depends on a distribution of states, rather than on a state.
% We define a scheduler as depending on a distribution---or their history in the memoryful case, rather than a state.
In our general framework, a configuration of an MDP is a distribution over states.
\begin{definition}[configuration, scheduler]\label{def:scheduler}
  %  \begin{itemize}
  %   \item general scheduler (potentially memoryful)
  %   \item memoryless semantics
  %  \end{itemize}
  %Let $\act$ be a finite set of action. A \emph{superposition action} $\bar{a}\in\dist(\act)$ is a distribution over actions.
A \emph{configuration} of an MDP ${\cal M}=(Q,\act,\delta)$ is a distribution $d\in \dist(Q)$. 
  A \emph{(configuration-based) scheduler} for
%  ${\cal M}=(Q,\act,\delta)$ 
$\mathcal{M}$
is a function $\sigma\colon\dist(Q)^{+}\to \dist(\act)$ that maps a sequence of configurations to a distribution over actions.  A scheduler is \emph{memoryless} if its value only depends on the last element of its input, that is for any sequence $d_{1}d_{2}...d_{n}\in\dist(Q)^{+}$, $\sigma(d_{1}d_{2}...d_{n})=\sigma(d_{n})$. Therefore, a memoryless scheduler is a function of the type $\sigma\colon\dist(Q)\to \dist(\act)$. A scheduler is \emph{pure} if it always gives a Dirac distribution, that is for any $p\in\dist(Q)^{+}$, $\sigma(p)(a)=1$ for some $a\in\act$. Otherwise, the scheduler is \emph{mixed}.
\end{definition}

\begin{remark}\label{rem:globalVsLocalActions}
 Note that the scheduler notion in \cref{def:scheduler} uses \emph{global} actions: 
it chooses 
%given a history $d_{1}d_{2}...d_{n}\in\dist(Q)^{+}$, 
an action $a$ is picked from the distribution $\sigma(d_{1}d_{2}...d_{n})\in \dist(\act)$ and \emph{this action $a$ is used at every state}  $q\in Q$. The more common notion of \emph{local} action---allowing different actions at different states---can be encoded as global actions by bloating the action set.
\end{remark}

A CM classifier (as presented in \cref{eq:CMClassifierAnnotated}) takes, as input, three-fold probability distributions, and its layers correspond to the three sources of probability in MDPs. We shall call such data a pre-configuration.

% Our construction considers three sources of probabilities distributions over the state space of an MDP (namely schedulers, configurations and transitions). Mathematically, we formalize it as a \emph{pre-configuration} defined as follows.

\begin{definition}[pre-configuration]\label{def:preconfig}
  Let ${\cal M}=(Q,\act,\delta)$ be an MDP.  A \emph{pre-configuration} of $\mathcal{M}$ is an element $t\in \dist(\dist(\dist(Q)))$, or $t\in \Dsched(\Dconf(\Dtrans(Q)))$ with annotations.
\end{definition}

The following function $\delta_{\sigma}$, as sketched in the beginning of the section, extracts a pre-configuration from an MDP $\mathcal{M}$ and a scheduler $\sigma$, exposing the three sources of probabilities.

% As hinted in the start of this section, the first step is to prepare a transition by transforming a configuration to a pre-configuration. This is done by the function $\delta_{\sigma}$ defined as follows.

\begin{restatable}[$\delta_\sigma$]{definition}{DeltaSigma}\label{def:deltaSigma}
  Let ${\cal M}=(Q,\act,\delta)$ be an MDP and $\sigma$ be a scheduler.
  We define a function $\delta_{\sigma}\colon\dist(Q)^{+}\to \dist(\dist(\dist(Q)))$ as follows: for any $d_{0}d_{1}\dots d_{k}\in\dist(Q)^{+}$,
  \begin{equation}\label{eq:preConfig}
    \delta_{\sigma}(d_{0}d_{1}\dots d_{k})=\sum_{a\in\act}\sigma(d_{0}d_{1}...d_{k})(a)\,\biggket{\sum_{q\in Q}d_{k}(q)\,\bigket{\,\delta(q,a)\,}}.
  \end{equation}
\end{restatable}
