% \begin{definition}[$\delta_{\sigma}$]\label{def:deltaSigma}
%   Let ${\cal M}=(Q,\act,\delta)$ be an MDP and $\sigma$ be a scheduler.
%   We define a function $\delta_{\sigma}\colon\dist(Q)^{+}\to \dist(\dist(\dist(Q)))$ as follows: for any $d_{0}d_{1}\dots d_{k}\in\dist(Q)^{+}$,
%   \begin{equation}\label{eq:preConfig}
%     \delta_{\sigma}(d_{0}d_{1}\dots d_{k})=\sum_{a\in\act}\sigma(d_{0}d_{1}...d_{k})(a)\,\biggket{\sum_{q\in Q}d_{k}(q)\,\bigket{\,\delta(q,a)\,}}.
%   \end{equation}
% \end{definition}
The annotations in both~\cref{eq:CMClassifierAnnotated} and \cref{def:preconfig} can now be explained using~\cref{eq:preConfig}.

\begin{compactitem}
  \item The innermost distribution $\delta(q,a)$ on the right-hand side of~\cref{eq:preConfig} comes from the transition function $\delta\colon Q\times\act\to \dist(Q)$ of an MDP; so we write $\delta(q,a)\in \Dtrans(Q)$.
  \item The distribution $\biggket{\sum_{q\in Q}d_{k}(q)\,\bigket{\,\delta(q,a)\,}}$, that is one-level higher, has probabilities $d_{k}(q)$ that come from a ``configuration'' $d_{k}$ (this terminology is justified by the memoryless case of \cref{def:ConfMC} later). Thus we say it belongs to $\Dconf(\Dtrans(Q))$.
  \item Finally, the whole right-hand side of each of~\cref{eq:preConfig} is a probability distribution over elements of $\Dconf(\Dtrans(Q))$, where the probabilities (such as $\sigma(d)(a)$) come from the scheduler $\sigma$. Therefore, the right-hand side is an element of $\Dsched(\Dconf(\Dtrans(Q)))$.
\end{compactitem}

%As hinted in~\cref{eq:CMClassifierAnnotated}, a pre-configuration over a state space $Q$ is meant to be an input to a CM classifier $\mathbb{X}_{Q}$. In general, we define the \emph{CM classifier} as follows.
% \noindent
% Now, for the second step, we define the chance-mass classifier as follows. 

\noindent
The following defines CM classifiers, whose intuitions have been discussed earlier in \cref{subsec:CMclassConfigMC}. 

\begin{definition}[chance-mass (CM) classifier]\label{def:CMClassifier}
  A \emph{chance-mass (CM) classifier} is a family $\mathbb{X}=(\mathbb{X}_{Q})_{Q}$ of functions indexed by set $Q$; its $Q$-component has type $\mathbb{X}_{Q}:\dist(\dist(\dist(Q)))\to\dist(\dist(Q))$. When the index $Q$ is obvious we drop it,  writing $\mathbb{X}\colon\dist(\dist(\dist(Q)))\to \dist(\dist(Q))$.
\end{definition}

\begin{remark}\label{rem:naturality}
  For our theoretical development,  in \cref{def:CMClassifier},  it is enough to fix an MDP ${\cal M}=(Q,\act,\delta)$ and only consider the $Q$-component $\mathbb{X}_{Q}\colon\dist(\dist(\dist(Q)))\to \dist(\dist(Q))$ of $\mathbb{X}$. We made the above general definition---it is independent of the choice of $Q$---to emphasize the \emph{uniformity} of $\mathbb{X}$. This uniformity should be formalized as the \emph{naturality in $Q$}, a central notion from category theory~\cite{MacLane71}. We will do so in our future work.
\end{remark}

%We let an MDP $\mathcal{M}$ and a scheduler $\sigma$ induce the \emph{configuration Markov chain (config MC)} $\mathcal{M}_{\mathbb{X}, \sigma}$ under a choice $\mathbb{X}$ of a CM classifier. The config MC is used for the precise definition of MDP semantics, e.g.\ for reachability probabilities.

%We prepare some constructs for the definition of config MC (\cref{def:ConfMC}). For any MDP ${\cal M}$ and scheduler $\sigma$, the following function $\delta_{\sigma}$ yields a pre-configuration; it induces a config MC (\cref{def:ConfMC}) when composed with a CM classifier $\mathbb{X}$.

%\noindent
We are ready to define a config MC $\mathcal{M}_{\mathbb{X}, \sigma}$, a semantic basis on which we formalize e.g.\ reachability problems. As announced, its transition function is a composition $\mathbb{X}\circ \delta_{\sigma}$ of 1) a CM classifier $\mathbb{X}$ that chooses the type of semantics (cf.\ \cref{table:fourVarExampleIntro}) and 2) the function $\delta_{\sigma}$ that exposes three sources of probability in an MDP and forms a pre-configuration.

% Now we have the two steps of transition defined and we are ready to present their composition. We let an MDP $\mathcal{M}$ and a scheduler $\sigma$ induce the \emph{configuration Markov chain (config MC)} $\mathcal{M}_{\mathbb{X}, \sigma}$ under a choice $\mathbb{X}$ of a CM classifier. The config MC is used for the precise definition of MDP semantics, e.g.\ for reachability probabilities. As announced, composing $\delta_{\sigma}$ with a CM classifier $\mathbb{X}$ and a scheduler $\sigma$ gives a config MC.

\begin{definition}[config MC ${\cal M}_{\mathbb{X},\sigma}$]\label{def:ConfMC}
%\todo{Changed the notion of configuration, check subsequent text: checking DONE}
  Let ${\cal M}=(Q,\act,
% (M_{a})_{a\in\act}
\delta
)$ be an MDP, $\mathbb{X}$ be a CM classifier and $\sigma$ be a scheduler. The \emph{configuration Markov chain (config MC)} ${\cal M}_{\mathbb{X},\sigma}=\bigl(\dist(Q)^{+},\delta_{\mathbb{X},\sigma}\bigr)$ is a Markov chain carried by the set $\dist(Q)^{+}$. 
% of \emph{configurations}. 
Its transition function $\delta_{\mathbb{X},\sigma}\colon \dist(Q)^{+}\to\dist(\dist(Q)^{+})$ is defined as follows: for $d_{0}d_{1}\dots d_{k}\in\dist(Q)^{+}$,
  \begin{displaymath}
    \delta_{\mathbb{X},\sigma}(d_{0}d_{1}\dots d_{k})=\sum_{d_{k+1}\in \dist(Q)} \bigg(\mathbb{X}\bigl(\delta_{\sigma}(d_{0}d_{1}\dots d_{k})\bigr)(d_{k+1})\bigg)\,\ket{d_{0}d_{1}...d_{k}d_{k+1}},
  \end{displaymath}
  that is, a config MC state $d_{0}d_{1}\dots d_{k}$ evolves into $d_{0}d_{1}\dots d_{k} d_{k+1}$ with the probability \linebreak $\left(\mathbb{X}\bigl(\delta_{\sigma}(d_{0}d_{1}\dots d_{k})\bigr)\right)(d_{k+1})$. Note that, in this memoryful setting, config MC states record the whole history as sequences and  get extended along transitions. 

  For a memoryless scheduler $\sigma\colon\dist(Q)\to\dist(\act)$, the config MC ${\cal M}_{\mathbb{X},\sigma}=\bigl(\dist(Q),\delta_{\mathbb{X},\sigma}\bigr)$ is carried by the set $\dist(Q)$ of configurations (\cref{def:scheduler}). The function
  \begin{math}
    \delta_{\mathbb{X},\sigma}\colon
    \dist(Q)\to\dist(\dist (Q))
  \end{math}
  is
  \begin{equation}\label{eq:configMCMemoryless}
    \delta_{\mathbb{X},\sigma}(d)=\sum_{d'\in \dist(Q)} \bigg(\mathbb{X}\bigl(\delta_{\sigma}(d)\bigr)(d')\bigg)\,\ket{d'},
  \end{equation}
  that is, a configuration $d\in \dist(Q)$ evolves into $d'\in \dist(Q)$ with the probability $\left(\mathbb{X}\bigl(\delta_{\sigma}(d)\bigr)\right)(d')$. Note that by the definition of $\dist$, the CM classifier $\mathbb{X}\bigl(\delta_{\sigma}(d_{0}d_{1}\dots d_{k})\bigr)$ and $\mathbb{X}\bigl(\delta_{\sigma}(d)\bigr)$ are finitely-supported, hence the use of summation notation here is well-defined.
\end{definition}

