\begin{definition}[%
    MC2CM $\lambda$,
    suppression $\mu$,
    Dirac $\eta$%
  ]\label{def:mu}
  Let $X$ be a set.
  \begin{compactitem}
    \item The \emph{MC2CM operator} $\lambda_{X}\colon \dist(\dist(X))\to\dist(\dist(X))$ on $X$ is defined as follows:
          \begin{equation}\label{eq:MC2CM}
            \lambda_{X}\biggl(\sum_{i\in I}a_{i}\,\biggket{\sum_{x\in X}b_{ix}\ket{x}}\biggr)=\sum_{f\in X^{I}}\Bigl(\prod_{i\in I}b_{i,f(i)}\Bigr)\,\biggket{\,\sum_{i\in I}a_{i}\,\bigket{f(i)}\,}.
          \end{equation}
    \item
          The \emph{suppression operator} $\mu_{X}\colon \dist(\dist(X))\to\dist(X)$ on $X$ is defined as follows:
          \begin{equation}
            \mu_{X}\biggl(\sum_{i\in I}a_{i}\,\biggket{\sum_{x\in X}b_{ix}\ket{x}}\biggr)
            =\sum_{x\in X} \Bigl(\sum_{i\in I}a_{i}b_{ix}\Bigr)\ket{x}.
          \end{equation}
    \item The \emph{Dirac operator} $\eta_{X}\colon X\to\dist(X)$ is defined by
          \begin{math}
            \eta_{X}(x)=1\,\ket{x}
          \end{math}, that is, $\eta_{X}(x)(x')=1$ if $x=x'$ and $0$ otherwise.
  \end{compactitem}
  Much like in \cref{def:CMClassifier}, we often drop the subscript $X$ and simply write $\lambda,\mu,\eta$.
\end{definition}
%In fact, the last definitions are uniform for any $X$; they are \emph{natural in $X$} when put in categorical terms. See~\cref{rem:naturality}.

