\begin{definition}[CM classifiers, concrete instances] 
\label{def:CMclassifiersInstances}
We define four CM classifiers 
\linebreak
$
\mathbb{X}^{\csct{}},
\mathbb{X}^{\msct{}},
\mathbb{X}^{\csmt{}},
\mathbb{X}^{\msmt{}}
\colon
 \Dsched(\Dconf(\Dtrans(Q)))\to\Dchan(\Dmass(Q))
$:
\begin{align*}
 &\mathbb{X}^{\csct{}}
 = \mu_{\dist(Q)}\circ\dist\lambda_{Q}
, \quad\text{that is concretely},
\\
&\quad
\mathbb{X}^{\csct{}}\left(\sum_{i\in I}a_{i}\lrket{\sum_{j\in J}b_{i,j}\biggket{\sum_{q\in Q}p_{i,j,q}\ket{q}}}\right)=\sum_{i\in I}\sum_{f\in Q^{J}}\left(a_{i}\prod_{j\in J}p_{i,j,f(j)}\right)\biggket{\sum_{j\in J}b_{i,j}\ket{f(j)}};
\\
&
\mathbb{X}^{\msct{}}=\dist\mu_{(Q)}\circ\lambda_{\dist(Q)}\circ\dist\lambda_{Q}
, \quad\text{that is concretely},
\\
&\quad\resizebox{.95\textwidth}{!}{$\displaystyle{\mathbb{X}^{\msct{}}\left(\sum_{i\in I}a_{i}\lrket{\sum_{j\in J}b_{i,j}\biggket{\sum_{q\in Q}p_{i,j,q}\ket{q}}}\right)=\sum_{f\in Q^{I\times J}}\prod_{(i,j)\in I\times J}p_{i,j,f(i,j)}\biggket{\sum_{(i,j)\in I\times J}a_{i}b_{i,j}\ket{f(i,j)}}}$};
\\
&\mathbb{X}^{\csmt{}}=\dist\mu_{(Q)}
, \quad\text{that is concretely},
\\
&\quad
\mathbb{X}^{\csmt{}}\left(\sum_{i\in I}a_{i}\lrket{\sum_{j\in J}b_{i,j}\biggket{\sum_{q\in Q}p_{i,j,q}\ket{q}}}\right)=\sum_{i\in I}a_{i}\biggket{\sum_{j\in J}\sum_{q\in Q}b_{i,j}p_{i,j,q}\ket{q}}; \text{ and}
\\
&
\mathbb{X}^{\msmt{}}=\eta_{\dist(Q)}\circ\dist\mu_{Q}\circ\mu_{\dist(Q)}
, \quad\text{that is concretely},
\\
&\quad
\mathbb{X}^{\msmt{}}\left(\sum_{i\in I}a_{i}\lrket{\sum_{j\in J}b_{i,j}\biggket{\sum_{q\in Q}p_{i,j,q}\ket{q}}}\right)=\biggket{\sum_{i\in I}\sum_{j\in J}\sum_{q\in Q}a_{i} b_{i,j} p_{i,j,q}\ket{q}}.
\end{align*}
\end{definition}

Here is the illustration of the definition of the $\csct{}$ case (the other cases are similar). As demonstrated in~\cref{table:symbX}, the CM classifier $\mathbb{X}^{\csct{}}$ first applies $\dist\lambda_{Q}$ to the pre-configuration to rearrange the order of the distribution operators and obtain an element in $\Dsched(\Dtrans(\Dconf(Q)))$. Since both the scheduler and the transition distributions are interpreted in the chance manner, we apply the suppression operator $\mu_{\dist(Q)}$ to suppress $\Dsched$ and $\Dtrans$ to $\Dchan$ and leave $\Dconf$ to $\Dmass$.



Those concrete CM classifiers in \cref{def:CMclassifiersInstances} instantiate the general definition of config MC (\cref{def:ConfMC}) as follows. 
To avoid complex super- and subscripts, a  config MC ${\cal M}_{\mathbb{X}^{\csct{}},\sigma}$ shall be denoted by 
${\cal M}^{\csct{}}_{\sigma}$, and similarly for other semantics. 
Here we focus on memoryless schedulers for readability (cf.\ \cref{eq:configMCMemoryless}); the general case is deferred to Appendix \ref{sec:omittedDef}.

\begin{definition}[config MC under concrete semantics, memoryless]
\label{def:ConfigMCsInstances}
  Let ${\cal M}=(Q,\act,\delta)$ be an MDP, and  $\sigma\colon \dist(Q)\to \dist(\act)$ be a (memoryless) scheduler.
  The four config MCs induced by ${\cal M}$ and $\sigma$, under  the four CM classifiers in \cref{def:CMclassifiersInstances}, are concretely described as follows. 
\begin{itemize}
 \item Those config MCs are denoted by
${\cal M}^{\csct{}}_{\sigma}, 
{\cal M}^{\msct{}}_{\sigma}, 
{\cal M}^{\csmt{}}_{\sigma}, 
{\cal M}^{\msmt{}}_{\sigma}$.
 \item They all 
  have $\dist(Q)$ as a state space.
 \item Their transition functions, all of type $\dist(Q)\to\dist(\dist(Q))$, are given as follows.
\begin{align}
 \delta_{\mathbb{X}^{\csct{}},\sigma}(d)(d')
&=
\sum_{a\in\act}\sum_{f\in Q^{Q} \text{ s.t. } \dist f(d)=d'}\sigma(d)(a)\cdot\bigg(\prod_{q\in Q}\delta(q,a)\bigl(f(q)\bigr)\bigg),
\nonumber
\\
    \delta_{\mathbb{X}^{\msct{}},\sigma}(d)(d')
&=
\sum_{f\in Q^{Q\times\act}\text{ s.t. } d'=\dist f(d\otimes\sigma(d))}\prod_{(q,a)\in Q\times\act}\delta(q,a)(f(q,a)),
\nonumber
\\
    \delta_{\mathbb{X}^{\csmt{}},\sigma}(d)(d')
&=
\sum_{a\in\act\text{ s.t. }d'=\mu_{Q}(\dist(\delta^{\wedge}(a))(d))}\sigma(d)(a),
\label{eq:configMCConcreteCSMT}
\\
    \delta_{\mathbb{X}^{\msmt{}},\sigma}(d)(d')
&=\begin{cases}
      1 & \quad \text{if }d'=\sum_{a\in\act}\sum_{q'\in Q}\sum_{q\in Q}\sigma(d)(a) d(q)\delta(q,a)(q')\ket{q'}, \\
      0 & \quad \text{otherwise.}
    \end{cases}
\nonumber
\end{align}
In the second line, $d\otimes \sigma(d)\in \dist(Q\times\act)$ denotes the product, which is a coupling of the configuration $d\in\dist(Q)$ and the distribution  $\sigma(d)\in \dist(\act)$ over actions, that is $(d\otimes \sigma(d))(q,a)=d(q)\cdot\sigma(d)(a)$.
\end{itemize}

\end{definition}


\begin{remark}\label{rem:CSCTConv}
 As we discussed in \cref{sec:intro}, the \csct{} semantics should coincide with the conventional semantics of MDPs, but \cref{def:ConfigMCsInstances}  may not look  that way.  We can show that 1)
 the transition function $\delta_{\mathbb{X}^{\csct{}},\sigma}$ \emph{preserves Dirac-ness} (i.e.\ if  $d$ is Dirac, then $\delta_{\mathbb{X}^{\csct{}},\sigma}(d)(d')>0$ implies $d'$ is Dirac as well), and 2) the definition in \cref{def:ConfigMCsInstances} indeed is the usual semantics when $d$ and $d'$ are Dirac (meaning that these  configurations are single states with mass 1). A proof is in Appendix~\ref{sec:proof}.
\end{remark}


