\begin{theorem}[$\gamma$-scaled submartingale witness]\label{thm:subm-witness}
  Assume that the input of \cref{prob:GeneralThreshold} is given, with $\mathbb{X}^{\msct{}}$ as the CM classifier.  Let $R$ be a $\gamma$-scaled submartingale $R$ for some $\gamma\in (0,1)$. Then
  \begin{math}
    R(d_{0})\geq\xi
  \end{math}
  implies there exists a memoryless scheduler $\sigma$ such that 
\begin{math}
\Pb(\reach_{\mathbb{X}^{\msct{}},\sigma}(d_{0},H))\geq\xi.
\end{math}
