\begin{auxproof}
  \begin{proof}
    For the first part, assume not, then there exists  $\vy_{k}'\neq \vy_{k}^{\ast}\in [0,1]^{n}$ such that $\vy_{k}'\preceq \vy^{\ast}_{k}$. Then it is not hard to check that $\vy_{k}'$ is also a feasible solution to the $k$-th minimization problem and $\mathbf{1}^{T}\vy_{k}'<\mathbf{1}^{T}\vy_{k}^{\ast}$. This contradicts with $\vy^{\ast}_{k}$ being the minimum solution. The second statement is easy: just pick $K$ to be the number of generators and $L=\abs{Q}^{K}$.
  \end{proof}
\end{auxproof}

\begin{algorithm}[H]\footnotesize
  \caption{Backward projection algorithm}\label{algo:anti}
  \DontPrintSemicolon
  \SetKwRepeat{Do}{do}{while}
  \KwIn{an MDP ${\cal M}=(Q,\act,\mat)$, an initial configuration $d_{0}\in\dist(Q)$, a target set antichain $\floor{H}\subset [0,1]^{\abs{Q}}$, parameters $K,L\in\mathbb{N}$}
  \KwOut{{\sf True} if $d_{0}$ is reachable to $H$}
  $S\leftarrow \{\}$\\
  $S'\leftarrow \floor{H}$\\
  \Do{$S\neq S'$}{
    $S\leftarrow S'$\\
    $S'\leftarrow \floor{H}$\\
    \For{$M\in\mat$}{
      \For{$\vx\in S$}{
        $\{\vy_{k}^{\ast}\mid k\in [K]\}\leftarrow$ Solve the problem in \cref{eqt:anti-min} against $M$,$\vx$ with parameters $K,L$\label{line:iter}\\
        $S'\leftarrow \floor{S'\cup\{\vy_{k}^{\ast}\mid k\in [K]\}}$\label{line:floor}
      }
    }
    \lIf{$d_{0}\in S'$}{\Return{{\sf True}}}
  }
  \lIf{$d_{0}\in S'$}{\Return{{\sf True}}}
\end{algorithm}

%Now we are ready to present the algorithm. It is in \cref{algo:anti}.
Finally, we formalize the algorithm and its correctness. The algorithm takes as input an MDP ${\cal M}=(Q,\act,\mat)$, an initial configuration $d_{0}\in\dist(Q)$, a target set $H$ provided as $\floor{H}$ and two parameters $K,L\in\mathbb{N}$, and returns {\sf True} if $d_{0}$ is reachable to $H$. It starts with a set $S=\floor{H}$ and iteratively updates $S$ by computing $\floor{B(S)}$ through solving the optimization problem described above. The algorithm only terminates when it witnesses a reachability or the set of configurations reachable to $H$ stabilizes, that is, $d_{0}\in S$ or $S=S'$. The full pseudocode is provided in~\cref{algo:anti}. %\cref{algo:anti} (in Appendix~\ref{sec:omittedDef}). 
The termination is necessarily not guaranteed since the problem is undecidable (\cref{thm:csmt-reach-undec}). But from \cref{lem:anti-approx} we can conclude that the algorithm always computes an under-approximation of the set of configurations reaching $H$, hence as a direct consequence of \cref{thm:ReachConfiglfp}, we have the following theorem.
