\section{Omitted Definitions}\label{sec:omittedDef}

\myparagraph{Formal definition of the threshold reachability problem}

First, we define the set of configuration paths induced by a config MC. Intuitively, it is the set of all possible paths that the config MC can take.

\begin{definition}[configuration path]\label{def:configPath}
  In the setting of \cref{def:ConfMC}, we define
  \begin{math}
    \cpath_{\mathbb{X},\sigma}=
    \bigl\{d_{0} d_{1}\dotsc d_{n}\in \dist(Q)^{+}
    \,\big|\,
    \bigl(d_{0},\, d_{0}d_{1},\, \dotsc,\, d_{0}d_{1}\dotsc d_{n}\bigr) \text{ is a (finite) path in $\mathcal{M}_{\mathbb{X},\sigma}$}
    \bigr\}
  \end{math}, where  \emph{path} of a Markov chain is defined as usual (requiring non-zero transition probabilities).
  Elements of
  \begin{math}
    \cpath_{\mathbb{X},\sigma}
  \end{math}
  are called \emph{configuration paths} of $\mathcal{M}$ under $\mathbb{X}, \sigma$. The set $\cpath^{\omega}_{\mathbb{X},\sigma}$ of \emph{infinite configuration paths} is defined similarly.

  For a memoryless scheduler $\sigma\colon\dist(Q)\to \dist(\act)$, the above definition simplifies to the sets of (finite and infinite) paths in the config MC $\mathcal{M}_{\mathbb{X},\sigma}$ (\cref{def:ConfMC}), that is, $\cpath_{\mathbb{X},\sigma}=\{d_{0}d_{1}...d_{n}\in\dist(Q)^{+}\mid (d_{0},d_{1},...,d_{n}) \text{ is a finite path in $\mathcal{M}_{\mathbb{X},\sigma}$}\}$ and similarly for the set of infinite paths.
\end{definition}

It follows from basic measure theory that 1) $\cpath^{\omega}_{\mathbb{X},\sigma}$ comes with a natural $\sigma$-algebra ${\cal F}_{\mathbb{X},\sigma}$ generated by cylindric sets, and 2) there is a unique probability measure $\Pb_{\mathbb{X},\sigma}$ on $(\cpath^{\omega}_{\mathbb{X},\sigma},{\cal F}_{\mathbb{X},\sigma})$ induced by the config MC $\mathcal{M}_{\mathbb{X},\sigma}$. We obtain these by applying  results for general MCs \cite{Baier2008,AshD99} to the config MC $\mathcal{M}_{\mathbb{X},\sigma}$ (\cref{def:ConfMC}).

The formal definition of the threshold reachability problem can thus be defined as follows.

\begin{problem}[threshold reachability problem]\label{prob:GeneralThresholdFormal}
  Assume the setting of \cref{def:ConfMC}. Let $d_{0}\in \dist(Q)$ and  $H\subseteq \dist(Q)$, called an \emph{initial configuration} and a \emph{target set}, respectively. We let $\reach_{\mathbb{X},\sigma}(d_{0},H)$ denote the set of paths that start from $d_{0}$ and eventually reach $H$, it is formally defined as follows:
    \begin{displaymath}
      \reach_{\mathbb{X},\sigma}(d_{0},H)
      \;=\;
      \{d_{0}d_{1}d_{2}\dotsc\in \cpath^{\omega}_{\mathbb{X},\sigma}\mid \text{$d_{i}\in H$ for some $i$}\},
    \end{displaymath}
  The \emph{threshold reachability problem} asks for a scheduler $\sigma$ such that
  \begin{math}
    \Pb_{\mathbb{X},\sigma}\bigl(\reach_{\mathbb{X},\sigma}(d_{0},H)\bigr)\geq \xi
  \end{math}.
  \end{problem}

\myparagraph{General definition of the config MC} 
The following is the general case (allowing memoryful schedulers) of the memoryless definition in \cref{sec:instances}.

\begin{definition}[config MC under \csct{} semantics, the general case]\label{def:ConfMCCSCTGeneral}
  Let ${\cal M}=(Q,\act,\delta)$ be an MDP, and  $\sigma\colon \dist(Q)^{+}\to \dist(\act)$ be a scheduler. The config MC induced by ${\cal M}, \mathbb{X}^{\csct{}}, \sigma$, denoted by
  \begin{math}
    {\cal M}^{\csct{}}_{\sigma}=(\dist(Q)^{+},\delta_{\mathbb{X}^{\csct{}},\sigma})
  \end{math}, is given as follows.

  The config MC's state space is the set $\dist(Q)^{+}$ of sequences of configurations of the MDP $\mathcal{M}$. Its transition function $\delta_{\mathbb{X}^{\csct{}},\sigma}\colon\dist(Q)^{+}\to\dist(\dist(Q)^{+})$ is defined as follows: let $p=d_{0}d_{1}...d_{n}$ be a finite sequence of configurations, and $d_{n+1}$ be the next configuration, then
  \begin{displaymath}
    \delta_{\mathbb{X}^{\csct{}},\sigma}(p)(p\cdot d_{n+1})=\sum_{a\in\act}\sum_{f\in Q^{Q} \text{ s.t. } \dist f(d_{n})=d_{n+1}}\sigma(p)(a)\cdot\bigg(\prod_{q\in Q}\delta(q,a)\bigl(f(q)\bigr)\bigg).
  \end{displaymath}
\end{definition}

\begin{definition}[config MC under \msct{} semantics, the general case]\label{def:ConfMCMSCTGeneral}
  Assume the setting that is the same as in~\cref{def:ConfMCCSCTGeneral} except for $\mathbb{X}^{\msct{}}$ being the CM classifier instead. Let ${\cal M}^{\msct{}}_{\sigma}=(\dist(Q)^{+},\delta_{\mathbb{X}^{\msct{}},\sigma})$ denotes the config MC induced by ${\cal M}, \mathbb{X}^{\msct{}}, \sigma$. Its transition function $\delta_{\mathbb{X}^{\msct{}},\sigma}\colon\dist(Q)^{+}\to\dist(\dist(Q)^{+})$ is concretely given as follows: let $p=d_{0}d_{1}...d_{n}$ be a finite sequence of configurations, and $d_{n+1}$ be the next configuration, then
  \begin{displaymath}
    \delta_{\mathbb{X}^{\msct{}},\sigma}(p)(p\cdot d_{n+1})=\sum_{a\in\act}\sum_{f\in Q^{Q\times\act}\text{ s.t. } d_{n+1}=\dist f(d_{n}\otimes\sigma(p))}\prod_{(q,a)\in Q\times\act}\delta(q,a)(f(q,a)).
  \end{displaymath}
\end{definition}

\begin{definition}[config MC under \csmt{} semantics, the general case]\label{def:ConfMCCSMTGeneral}
  Assume the setting that is the same as in~\cref{def:ConfMCCSCTGeneral} except for $\mathbb{X}^{\csmt{}}$ being the CM classifier instead. Let ${\cal M}^{\csmt{}}_{\sigma}=(\dist(Q)^{+},\delta_{\mathbb{X}^{\csmt{}},\sigma})$ denotes the config MC induced by ${\cal M}, \mathbb{X}^{\csmt{}}, \sigma$. Its transition function $\delta_{\mathbb{X}^{\csmt{}},\sigma}\colon\dist(Q)^{+}\to\dist(\dist(Q)^{+})$ is concretely given as follows: let $p=d_{0}d_{1}...d_{n}$ be a finite sequence of configurations, and $d_{n+1}$ be the next configuration, then
  \begin{displaymath}
    \delta_{\mathbb{X}^{\csmt{}},\sigma}(p)(p\cdot d_{n+1})=\sum_{a\in\act\text{ s.t. }d_{n+1}=\mu_{Q}(\dist(\delta^{\wedge}(a))(d))}\sigma(p)(a).
  \end{displaymath}
\end{definition}

\begin{definition}[config MC under \msmt{} semantics, the general case]\label{def:ConfMCMSMTGeneral}
  Assume the setting that is the same as in~\cref{def:ConfMCCSCTGeneral} except for $\mathbb{X}^{\msmt{}}$ being the CM classifier instead. Let ${\cal M}^{\msmt{}}_{\sigma}=(\dist(Q)^{+},\delta_{\mathbb{X}^{\msmt{}},\sigma})$ denotes the config MC induced by ${\cal M}, \mathbb{X}^{\msmt{}}, \sigma$. Its transition function $\delta_{\mathbb{X}^{\msmt{}},\sigma}\colon\dist(Q)^{+}\to\dist(\dist(Q)^{+})$ is concretely given as follows: let $p=d_{0}d_{1}...d_{n}$ be a finite sequence of configurations, and $d_{n+1}$ be the next configuration, then
  \begin{displaymath}
    \delta_{\mathbb{X}^{\msmt{}},\sigma}(p)(p \cdot d_{n+1})=\begin{cases}
      1 & \quad d_{n+1}=\sum_{a\in\act}\sum_{q'\in Q}\sum_{q\in Q}\sigma(p)(a) d_{n}(q)\delta(q,a)(q')\ket{q'} \\
      0 & \quad \text{otherwise}
    \end{cases}.
  \end{displaymath}
\end{definition}

