\myparagraph{Pseudocode for the antichain-based algorithm on the \csmt{} semantics}

\begin{algorithm}[H]\footnotesize
  \caption{Backward Projection Algorithm}\label{algo:anti}
  \DontPrintSemicolon
  \SetKwRepeat{Do}{do}{while}
  \KwIn{an MDP ${\cal M}=(Q,\act,\mat)$, an initial configuration $d_{0}\in\dist(Q)$, a target set antichain $\floor{H}\subset [0,1]^{\abs{Q}}$, parameters $K,L\in\mathbb{N}$}
  \KwOut{{\sf True} if $d_{0}$ is reachable to $H$}
  $S\leftarrow \{\}$\\
  $S'\leftarrow \floor{H}$\\
  \Do{$S\neq S'$}{
    $S\leftarrow S'$\\
    $S'\leftarrow \floor{H}$\\
    \For{$M\in\mat$}{
      \For{$\vx\in S$}{
        $\{\vy_{k}^{\ast}\mid k\in [K]\}\leftarrow$ Solve problem in \cref{eqt:anti-min} against $M$,$\vx$ with parameter $K,L$\label{line:iter}\\
        $S'\leftarrow \floor{S'\cup\{\vy_{k}^{\ast}\mid k\in [K]\}}$\label{line:floor}
      }
    }
    \lIf{$d_{0}\in S'$}{\Return{{\sf True}}}
  }
  \lIf{$d_{0}\in S'$}{\Return{{\sf True}}}
\end{algorithm}

