\section{Main Proof}
\label{MainProof}

A graph embedded in $\mathbb{R}^2$ with no edge crossings is a \defn{plane graph}. A plane graph is a \defn{triangulation} if each face is bounded by a cycle of three edges. For a plane graph $G$, let $F(G)$ denote the set of faces of $G$.  For a vertex $v$ of $G$, let $F(G,v)$ be the set of faces of $G$ incident to $v$. For $A\subseteq F(G)$, a \defn{face-weighting} is any function $w:A\rightarrow\mathbb{R}_{\geq 0}$. For $B\subseteq A$, let $w(B):=\sum_{f\in B}w(f)$.

\begin{lem}\label{tw_vs_weight}
    For any real numbers $N\ge W\ge 1$, for any plane graph $G$, for any set $X\subseteq F(G)$, and for any face-weighting $w:F(G)\setminus X\to\mathbb{R}_{\geq 0}$ such that $w(F(G)\setminus X) \le N$, and $F(G,v)\cap X\neq\emptyset$ or $w(F(G,v)) \ge W$ for each $v\in V(G)$,
    $$\tw(G)\le 12\sqrt{|X|+N/W}+7.$$
\end{lem}

