\section{Dynamics at the trapping radius}
\label{trap}



As will be clear later, there exists a trapping radius in the exterior region of the AdS$_5$ black hole with the metric function 
\begin{align}
 f=1-\frac{\mu}{r^2}+\lambda r^2,
 \label{fr}
\end{align}
where $\mu$ and $\lambda$ are positive constants. 


In order to obtain the dynamics of the string in the vicinity of the trapping radius, we write $r=r_0+x$, where $r_0$ is a constant and $x$ is a small radial displacement.


In equation \ref{phisepsim}, the term $r^4\sin^2\theta$ poses difficulty in separating the radial and angular coordinates. However, since we are interested in the behavior of the string in close vicinity of the trapping radius, we replace this term by $r_0^4\sin^2 \theta $, leading to 
\begin{align}
\left[\pi \alpha^{\prime}\hbar^2\left\{r^2  f(r)  \frac{\partial^2 }{\partial r^2} + \frac{\partial^2 }{\partial \theta^2}\right\}-   \frac{k^2 r_0^4}{4\pi \alpha^{\prime}}   \sin^2 \theta+\frac{\varepsilon^2 r^2  }{f(r)}-\frac{K^2}{\cos^2 \theta}\right]\mathcal{Z}(r,\theta)\approx 0
\label{nearHeqn}
\end{align}

\begin{figure}
\centering
 \includegraphics{negroot.eps}
   \caption{The function $\mathcal{F}(\rho,\sigma)$ for three values of $\rho$ violating the condition \ref{range}. 
For $\rho= 0.4, 0.5, 0.6$, the respective values of $\mathcal{F}(\rho,\sigma)$ are always negative for $\sigma>1.03822$.}
 \label{negroot}
\end{figure}



A separation of variables  can be implemented by writing   
\begin{equation}
 \mathcal{Z}(r,\theta)=\mathcal{R}(r)\Theta(\theta),
 \label{rthep1}
\end{equation}
leading to 
\begin{align}
\left[ \pi \alpha^{\prime}\hbar^2r^2  f(r) \frac{\partial^2 }{\partial r^2}+\frac{\varepsilon^2 r^2  }{f(r)}-\kappa\right]\mathcal{R}(r)=0
\label{rad}
\end{align}
 and 
\begin{align}
\left[\pi \alpha^{\prime}\hbar^2\frac{\partial^2 }{\partial \theta^2}-  \frac{k^2 r_0^4}{4\pi \alpha^{\prime}}   \sin^2\theta-\frac{K^2}{\cos^2 \theta}+\kappa\right]\Theta(\theta)=0,
\label{angu}
\end{align}
where $\kappa$ is the separation constant. 






Equation \ref{angu} requires special attention and we shall solve it after solving  the $x$-equation \ref{rad}  near the trapping radius. 
Expanding about the trapping radius by writing $r=r_0+x$, we can cast equation \ref{rad} in the form 
\begin{align}
 \left[-\pi \alpha^{\prime}\hbar^2 \frac{\partial^2 }{\partial x^2}+\alpha_1+\alpha_2 x+ \alpha_3 x^2\right]\mathcal{R}(x)=0, 
 \label{WF}
\end{align}
up to $\mathcal{O}(x^2)$,  where
\begin{align}
\alpha_1= \frac{\kappa}{r_0^2 \left(1-\frac{\mu}{r_0^2}+\lambda r_0^2\right)}-\frac{\varepsilon^2}{\left(1-\frac{\mu}{r_0^2}+\lambda r_0^2\right)^2}, 
\label{a1}
\end{align}
\begin{align}
  \alpha_2= \frac{4\varepsilon^2 \left(\mu+\lambda r_0^4\right) }{r_0^3\left(1-\frac{\mu}{r_0^2}+\lambda r_0^2\right)^{3}}-\frac{2 \kappa \left(1+2 \lambda r_0^2\right)}{r_0^3\left(1-\frac{\mu}{r_0^2}+\lambda r_0^2\right)^{2}},
  \label{a2}
\end{align}
and
\begin{align}
 \alpha_3=\frac{\kappa \left(6 \mu \lambda r_0^2+\mu+10 \lambda^2 r_0^6+9 \lambda r_0^4+3 r_0^2\right)}{r_0^6\left(1-\frac{\mu}{r_0^2}+\lambda r_0^2\right)^{3}}-\frac{2 \varepsilon^2 \left(3 \mu^2+16 \mu \lambda r_0^4+3 \mu r_0^2+5 \lambda^2 r_0^8-\lambda r_0^6\right)}{r_0^6\left(11-\frac{\mu}{r_0^2}+\lambda r_0^2\right)^{4}}.
 \label{a3}
\end{align}

Equation \ref{WF} can be rewritten as 
\begin{align}
  \left[-\pi \alpha^{\prime}\hbar^2 \frac{\partial^2 }{\partial x^2} + \alpha_3\left(x+\frac{1}{2}\frac{\alpha_2}{\alpha_3}\right)^2\right]\mathcal{R}(x)=\left(\frac{1}{4}\frac{\alpha_2^2}{\alpha_3}-\alpha_1\right)\mathcal{R}(x),
  \label{rx}
\end{align}
which takes the form of standard Schr\"odinger equation for a one dimensional harmonic oscillator, given by 
\begin{align}
  \left[-\frac{\hbar^2}{2m} \frac{\partial^2 }{\partial \xi^2}+\frac{1}{2} m\omega^2\xi^2\right]\mathcal{R}(\xi)=E\mathcal{R}(\xi),
  \label{sho}
\end{align}
where $m=\frac{1}{\sqrt{\pi \alpha^{\prime}}}$, $\omega^2=\alpha_3$, $\xi=x+\frac{1}{2}\frac{\alpha_2}{\alpha_3}$ and $E=\frac{1}{2}\frac{1}{\sqrt{\pi \alpha^{\prime}}}\left(\frac{1}{4}\frac{\alpha_2^2}{\alpha_3}-\alpha_1\right)$.

The eigenvalues and the normalized eigen functions in the Schrodinger equation  \ref{sho} are given by
\begin{align}
 E_n=\left(n+\frac{1}{2}\right)\hbar\omega
\end{align}
and 
\begin{align}
 \mathcal{R}_n(\xi)=\left(\frac{a}{\sqrt{\pi}2^n n!}\right)^{1/2} e^{-\frac{1}{2}a^2\xi^2} H_n(a \xi),
 \label{Hermite}
\end{align}
where $a=\left(\frac{m\omega}{\hbar}\right)^{1/2}$, and $H_n(a \xi)$ are the standard Hermite polynomials of order $n$, with the quantum number $n=0,1,2,\ldots$ \cite{LandauQM}.


The validity of \ref{sho} requires the conditions $\omega^2>0$ and $E>0$. Since they are defined by the parameters $\alpha_1$, $\alpha_2$ and $\alpha_3$, which are in turn defined by \ref{a1}, \ref{a2} and \ref{a3} that contain two independent separation constant $\kappa$ and $\varepsilon^2$, those conditions can always be satisfied. 


