\section{Further technical results}

\subsection{Proof of Proposition~\ref{proposition: exp(V) is Holder continuous}}\label{sec: proof of JN corollary}

For a normed vector space $(E,|\cdot|)$, a function $f \colon E \to \R$, and any $a, b, c, d \in E$, we write
\begin{equation}\label{eq: |f|_1,a,b,c,d}
\begin{split}
|f|_{1,\{a,b\}} &:= \sup_{\theta \in [0,1]} \big| f ( \theta a + (1 - \theta) b ) \big|,\\
|f|_{2,\{a,b,c,d\}} &:= \sup_{(\theta, \eta) \in [0,1]^2} \big| f \big( \eta ( \theta a + (1 - \theta) b ) + (1 - \eta) ( \theta c + (1 - \theta) d ) \big) \big|.
\end{split}
\end{equation}

\begin{lemma}\label{lemma: elementary estimate}
For some Banach space $(E,|\cdot|)$, let $g \in C^2(E;\R)$ and $a, b, c, d \in E$. (We consider standard Fr\'echet differentiability here.) Then
\begin{equation}\label{elementary estimate}
\begin{split}
&|g(a) - g(b) - g(c) + g(d)|\\
&\leq \big(|\D g|_{1,\{a,c\}} + |\D g|_{1,\{b,d\}} + |\D^2 g|_{2,\{a,b,c,d\}}\big) \big(|a-c| + |b-d|\big) \big( |c-d| \wedge 1 \big)\\
&\quad + |\D g|_{1,\{a,b\}} |a - b - c + d|.
\end{split}
\end{equation}
\end{lemma}

\begin{proof}
We first observe the straightforward bound
\begin{align*}
|g(a) - g(b) - g(c) + g(d)| &\leq |g(a) - g(c)| + |g(b) - g(d)|\\
&\leq |\D g|_{1,\{a,c\}} |a - c| + |\D g|_{1,\{b,d\}} |b - d|.
\end{align*}
We also have that
\begin{align*}
&g(a) - g(b) - g(c) + g(d)\\
&= \int_0^1 \D g \big( b + \theta (a-b) \big) (a-b) \dd \theta - \int_0^1 \D g \big( b + \theta (a-b) \big) (c-d) \dd \theta\\
&\quad + \int_0^1 \D g \big( b + \theta (a-b) \big) (c-d) \dd \theta - \int_0^1 \D g \big( d + \theta (c-d) \big) (c-d) \dd \theta\\
&= \int_0^1 \D g \big( b + \theta (a-b) ) (a - b - c + d) \dd \theta\\
&\quad + \int_0^1 \Big( \D g \big(b + \theta (a-b) \big) - \D g \big(d + \theta (c-d) \big) \Big) (c-d) \dd \theta,
\end{align*}
from which we infer that
\begin{align*}
&|g(a) - g(b) - g(c) + g(d)|\\
&\leq |\D g|_{1,\{a,b\}} |a - b - c + d| + |\D^2 g|_{2,\{a,b,c,d\}} \big(|a - c| + |b - d|\big) |c - d|.
\end{align*}
Combining the bounds above, we obtain \eqref{elementary estimate}.
\end{proof}

\begin{proof}[Proof of Proposition~\ref{proposition: exp(V) is Holder continuous}]
We note that, for any $\lambda > 0$ and any $m \in [1,\infty)$, we have
\begin{equation}\label{eq: sup V_u has exponential moments}
\Big\| \exp \Big( \lambda \sup_{u \in [0,T]} |V_u| \Big) \Big\|_{L^m} \leq \exp (\lambda \|V_0\|_{L^\infty}) \Big\| \E_0 \Big[ \exp \Big( m \lambda \sup_{u \in [0,T]} |\delta V_{0,u}| \Big) \Big] \Big\|_{L^\infty}^{\frac{1}{m}} < \infty,
\end{equation}
where, by Theorem~\ref{theorem: John-Nirenberg inequality}, the right-hand side may be bounded by a constant which depends only on $\lambda, m, p, \|V_0\|_{L^\infty}$ and $\|V\|_{\textup{BMO}^{p\textup{-var}},[0,T]}$.

By the elementary estimate $|\exp(x) - \exp(y)| \leq |x-y| (\exp(x) \vee \exp(y))$, and the version of H\"older's inequality in \eqref{eq: Holder's inequality for q,r,s norm}, for any $(s,t) \in \Delta_{[0,T]}$, we have, for any $q, r \in [1,\infty)$, that
\begin{equation*}
\|\delta \exp(V)_{s,t}\|_{q,r,s} \leq \Big\| \E_s \Big[ \exp \Big( q \sup_{u \in [s,T]} |V_u| \Big) |\delta V_{s,t}|^q \Big] \Big\|_{L^r}^{\frac{1}{q}} \leq \Big\| \exp \Big( 2q \sup_{u \in [s,T]} |V_u| \Big) \Big\|_{L^r}^{\frac{1}{2q}} \|\delta V_{s,t}\|_{2q,r,s}.
\end{equation*}
By \eqref{eq: sup V_u has exponential moments}, this implies that $\|\exp(V)\|_{p,q,r,[0,T]} \lesssim \|V\|_{p,2q,r,[0,T]}$, which is finite by Remark~\ref{remark: V in VpLqinfty for all q}.

We now let $q, \tilde{q}, r \in [1,\infty)$ such that $\tilde{q}r < q$. Adopting the notation introduced in \eqref{eq: |f|_1,a,b,c,d}, we let $\Lambda = |\exp|_{2, \{V_t, \tV_t, V_s, \tV_s\}} + |\exp|_{1, \{V_t, \tV_t\}} + |\exp|_{1, \{V_s, \tV_s\}} + |\exp|_{1, \{V_t, V_s\}}$.

Applying Lemma~\ref{lemma: elementary estimate}, for any $(s,t) \in \Delta_{[0,T]}$, we have that
\begin{align*}
&\big\|\delta \exp(V)_{s,t} - \delta \exp(\tV)_{s,t}\big\|_{\tilde{q},r,s}\\
&\leq \big\| \E_s \big[ \Lambda^{\tilde{q}} \big(|V_t - \tV_t| + |V_s - \tV_s|\big)^{\tilde{q}} |\delta \tV_{s,t}|^{\tilde{q}} \big] \big\|_{L^r}^{\frac{1}{\tilde{q}}} + \big\| \E_s \big[ \Lambda^{\tilde{q}} |\delta V_{s,t} - \delta \tV_{s,t}|^{\tilde{q}} \big] \big\|_{L^r}^{\frac{1}{\tilde{q}}}\\
&\lesssim \big\| \E_s \big[ \Lambda^{\tilde{q}} \big(|\delta V_{s,t} - \delta \tV_{s,t}|\big)^{\tilde{q}} |\delta \tV_{s,t}|^{\tilde{q}} \big] \big\|_{L^r}^{\frac{1}{\tilde{q}}} + \big\| \E_s \big[ \Lambda^{\tilde{q}} |V_s - \tV_s|^{\tilde{q}} |\delta \tV_{s,t}|^{\tilde{q}} \big] \big\|_{L^r}^{\frac{1}{\tilde{q}}}\\
&\quad + \big\| \E_s \big[ \Lambda^{\tilde{q}} |\delta V_{s,t} - \delta \tV_{s,t}|^{\tilde{q}} \big] \big\|_{L^r}^{\frac{1}{\tilde{q}}} =: I_1 + I_2 + I_3.
\end{align*}

By H\"older's inequality and \eqref{eq: sup V_u has exponential moments}, it is straightforward to see that $\|\Lambda\|_{L^m} < \infty$ for any $m \in [1,\infty)$, and it is also clear that $\|\delta \tV_{s,t}\|_{L^m} < \infty$ for any $m \in [1,\infty)$. We then have that
\begin{equation*}
I_1 \leq \big\| \E_s \big[ \Lambda^{\frac{\tilde{q}q}{q-\tilde{q}}} |\delta \tV_{s,t}|^{\frac{\tilde{q}q}{q-\tilde{q}}} \big] \big\|_{L^r}^{\frac{q-\tilde{q}}{\tilde{q}q}} \|\delta V_{s,t} - \delta \tV_{s,t}\|_{q,r,s} \lesssim \|\delta V_{s,t} - \delta \tV_{s,t}\|_{q,r,s},
\end{equation*}
and $I_3$ may be treated similarly. Finally, we have that
\begin{align*}
I_2 &\leq \|V_s - \tV_s\|_{L^q} \big\| \E_s \big[ \Lambda^{\frac{\tilde{q}q}{q-\tilde{q}r}} |\delta \tV_{s,t}|^{\frac{\tilde{q}q}{q-\tilde{q}r}} \big] \big\|_{L^r}^{\frac{q-\tilde{q}r}{\tilde{q}q}} \leq \|V_s - \tV_s\|_{L^q} \|\Lambda\|_{\frac{2\tilde{q}q}{q-\tilde{q}r},r,s} \|\delta \tV_{s,t}\|_{\frac{2\tilde{q}q}{q-\tilde{q}r},r,s}\\
&\lesssim \big(\|V_0 - \tV_0\|_{L^q} + \|V - \tV\|_{p,q,r,[0,T]}\big) \|\delta \tV_{s,t}\|_{\frac{2\tilde{q}q}{q-\tilde{q}r},r,s},
\end{align*}
where using H\"older's inequality in the first inequality required that $\frac{q}{\tilde{q}r} > 1$.

Combining the above, we obtain the estimate in \eqref{eq: exp(V) - exp(tV) estimate}.
\end{proof}

\subsection{Some results on integrals against random measures}

The following result is a generalized conditional BDG inequality.

\begin{lemma}\label{lemma: conditional extended BDG}
Let $q \in [2,\infty)$, and let $M = (M_t)_{t \in [0,T]}$ be an $L^q$-integrable c\`adl\`ag real-valued local martingale with respect to a filtration $(\cF_t)_{t \in [0,T]}$, and let $\cG$ be a sub-$\sigma$-algebra of $\cF_0$. There exists a constant $C_q$, which depends only on $q$, such that
\begin{equation}\label{eq: extended conditional BDG}
\E \Big[ \sup_{s \in [0,t]} |M_s|^q \,\Big|\, \cG\Big] \leq C_q \E \Big[ \langle M \rangle_t^{\frac{q}{2}} \vee A^{(\frac{q}{2})}_t \,\Big|\, \cG\Big]
\end{equation}
holds almost surely for every $t \in [0,T]$, where $\langle M \rangle$ denotes the predictable quadratic variation of $M$, and, in the notation of \cite{HernandezHernandezJackal2022}, we write
\begin{equation*}
A^{(\ell)} := \Pi^\ast_p \bigg( \sum_{s \leq \cdot} |\Delta M_s|^{2\ell} \bigg),
\end{equation*}
where $\Pi^\ast_p$ denotes the dual predictable projection.
\end{lemma}

\begin{proof}
This is a consequence of the extended BDG inequality in \cite{HernandezHernandezJackal2022}. More precisely, for any $G \in \cG$, the process $(\tM_t)_{t \in [0,T]} := (M_t \1_G)_{t \in [0,T]}$ is a local martingale, and $\langle \tM \rangle = \langle M \rangle \1_G$. Also, $\widetilde{A}^{(\frac{q}{2})} := \Pi^\ast_p(\sum_{s \leq \cdot} |\Delta \tM_s|^q) = \Pi^\ast_p(\sum_{s \leq \cdot} |\Delta M_s|^q \1_G) = A^{(\frac{q}{2})} \1_G$. Then, by the standard BDG inequality combined with \cite[Theorem~2.1]{HernandezHernandezJackal2022}, we have that
\begin{equation*}
\E \Big[ \Big( \sup_{s \in [0,t]} |M_s|^q \Big) \1_G \Big] = \E \Big[ \sup_{s \in [0,t]} |\tM_s|^q \Big] \leq C_q \E \Big[ \langle \tM \rangle_t^{\frac{q}{2}} \vee \widetilde{A}^{(\frac{q}{2})}_t \Big] = C_q \E \Big[ \Big( \langle M \rangle_t^{\frac{q}{2}} \vee A^{(\frac{q}{2})}_t \Big) \1_G \Big].
\end{equation*}
Since this holds for all $G \in \cG$, we infer the inequality in \eqref{eq: extended conditional BDG}.
\end{proof}

\begin{remark}
Let $N$ be an integer-valued random measure on $\Omega \times [0,T] \times \U$ with compensator $\nu$. Let $\zeta \in G_{\textup{loc}}(N)$ be a real-valued function such that $\E [\int_0^T \int_{\U} |\zeta(s,u)|^q \, \nu(\d s,\d u)] < \infty$ for some $q \in [2,\infty)$, and let $M = \int_0^\cdot \int_{\U} \zeta(s,u) \, \tN(\d s,\d u)$. Then, with $\beta$ and $D$ defined as in \eqref{eq: definition D_i and beta^i}, we have by, e.g., \cite[Ch.~II, 1.15]{JacodShiryaev2003}, that
\begin{equation*}
\sum_{s \leq \cdot} |\Delta M_s|^q = \sum_{s \leq \cdot} |\zeta(s,\beta_s)|^q \1_D(s) = \int_0^\cdot \int_{\U} |\zeta(s,u)|^q \, N(\d s,\d u),
\end{equation*}
and hence by, e.g., \cite[Theorem~13.2.21]{Cohen2015}, that its dual predictable projection is given by
\begin{equation}\label{eq: dual predictable projection for Poisson martingale integral}
\Pi^\ast_p \bigg( \sum_{s \leq \cdot} |\Delta M_s|^q \bigg) = \int_0^\cdot \int_{\U} |\zeta(s,u)|^q \, \nu(\d s,\d u).
\end{equation}
\end{remark}

\begin{lemma}\label{lemma: application of conditional BDG for jump measures}
Let $N$ be an integer-valued random measure on $\Omega \times [0,T] \times \U$, such that its compensator $\nu$ satisfies $\nu(\{t\} \times \U) = 0$ for every $t \in [0,T]$, and write $\tN = N - \nu$ for the corresponding compensated random measure. Then the following hold.
\begin{itemize}
\item[(i)] Let $q \in [2,\infty)$ and $r \in [1, \infty]$. There exists a constant $C$, which depends only on $q$, such that, for any $\zeta \in G_{\textup{loc}}(N)$ with $\E [\int_0^T \int_{\U} |\zeta(s,u)|^q \, \nu(\d s,\d u)] < \infty$ and any $(s,h) \in \Delta_{[0,T]}$,
\begin{equation}\label{eq: quadratic variation bound for compensated poisson martingale integrals using BDG}
\begin{split}
\bigg\| &\sup_{v \in [s,h]} \bigg| \int_s^v \int_{\U} \zeta(t,u) \, \tN(\d t,\d u) \bigg| \bigg\|_{q,r,s}\\
&\leq C \bigg\| \E_s \bigg[ \bigg( \int_s^h \int_{\U} |\zeta(t,u)|^2 \, \nu(\d t,\d u) \bigg)^{\hspace{-2pt}\frac{q}{2}} \vee \int_s^h \int_{\U} |\zeta(t,u)|^q \, \nu(\d t,\d u) \bigg] \bigg\|_{L^r}^{\frac{1}{q}}.
\end{split}
\end{equation}
\item[(ii)] Let $\nu(\d t,\d u) = K(t,\d u) \dd A_t$ as in \eqref{eq: decomposition of nu}, and suppose that $A \in V^{\frac{p}{2}} L^{\frac{q}{2},r} \cap V^{\frac{p}{q}} L^{1,r}$ for some $2 \leq q \leq p < 3$ and $r \in [1,\infty]$, and let $\zeta \in G_{\textup{loc}}(N)$ such that
\[\bigg\| \sup_{t \in [0,T]} \int_{\U} \big( |\zeta(t,u)|^2 \vee |\zeta(t,u)|^q \big) \, K(t,\d u) \bigg\|_{L^\infty} \leq L\]
for some finite constant $L > 0$. Then there exists a constant $C$, which depends only on $q$ and $L$, such that
\begin{equation*}
\bigg\| \int_0^\cdot \int_{\U} \zeta(t,u) \, \tN(\d t,\d u) \bigg\|_{p,q,r,[0,T]} \leq C \Big( \|A\|_{\frac{p}{2},\frac{q}{2},r,[0,T]}^{\frac{1}{2}} + \|A\|_{\frac{p}{q},1,r,[0,T]}^\frac{1}{q} \Big).
\end{equation*}
\end{itemize}
\end{lemma}

\begin{proof}
By considering the integral $\int_0^\cdot \int_{\U} \zeta(t,u) \, \tN(\d t,\d u)$ componentwise, we may assume without loss of generality that $\zeta$ is real-valued.

\emph{(i):}
By the conditional BDG inequality in Lemma~\ref{lemma: conditional extended BDG}, together with \eqref{eq: dual predictable projection for Poisson martingale integral}, we have that
\begin{align*}
&\bigg\| \E_s \bigg[ \sup_{v \in [s,h]} \bigg| \int_s^v \int_{\U} \zeta(t,u) \, \tN(\d t,\d u) \bigg|^q \bigg] \bigg\|_{L^r}^{\frac{1}{q}}\\
&\lesssim \bigg\| \E_s \bigg[ \bigg\langle \int_s^\cdot \int_{\U} \zeta(t,u) \, \tN(\d t,\d u) \bigg\rangle_{\hspace{-2pt}h}^{\hspace{-2pt}\frac{q}{2}} \vee \int_s^h \int_{\U} |\zeta(t,u)|^q \, \nu(\d t,\d u) \bigg] \bigg\|_{L^r}^{\frac{1}{q}},
\end{align*}
and the estimate in \eqref{eq: quadratic variation bound for compensated poisson martingale integrals using BDG} then follows by \cite[Ch.~II, Theorem~1.33]{JacodShiryaev2003}.

\emph{(ii):}
Using the bound in \eqref{eq: quadratic variation bound for compensated poisson martingale integrals using BDG}, for any $(s,v) \in \Delta_{[0,T]}$, we have that
\begin{align*}
&\bigg\| \int_s^v \int_{\U} \zeta(t,u) \, \tN(\d t,\d u) \bigg\|_{q,r,s}\\
&\lesssim \bigg\| \E_s \bigg[ \bigg( \int_s^v \int_{\U} |\zeta(t,u)|^2 \, K(t,\d u) \dd A_t \bigg)^{\hspace{-2pt}\frac{q}{2}} \vee \int_s^v \int_{\U} |\zeta(t,u)|^q \, K(t,\d u) \dd A_t \bigg] \bigg\|_{L^r}^{\frac{1}{q}}\\
&\leq L \Big( \|\delta A_{s,v}\|_{\frac{q}{2},r,s}^{\frac{1}{2}} + \|\delta A_{s,v}\|_{1,r,s}^{\frac{1}{q}} \Big) \leq L \Big( \|A\|_{\frac{p}{2},\frac{q}{2},r,[s,v]}^{\frac{1}{2}} + \|A\|_{\frac{p}{q},1,r,[s,v]}^{\frac{1}{q}} \Big)
\end{align*}
and, since $q \leq p$, the desired estimate then follows by superadditivity.
\end{proof}

\subsection{Some results on rough paths}\label{appendix: rough paths}

\begin{proof}[Proof of Proposition \ref{proposition: consistency rough and stochastic integrals for semimartingales}]
Let $t \in [0,T]$. By, e.g., \cite[Ch.~II, Theorem~21]{Protter2005}, there exists a sequence of partitions $(\cP^k)_{k \in \N}$ of the interval $[0,t]$ with vanishing mesh size, such that the limit
\begin{equation}\label{eq: lim Yu delta Xuv int Ys- dXs}
\lim_{k \to \infty} \sum_{[u,v] \in \cP^k} Y_u \delta X_{u,v} = \int_0^t Y_{s-} \dd X_s
\end{equation}
holds $(\P \otimes \bar{\P})$-almost surely.

By \cite[Lemma~4.35]{ChevyrevFriz2019}, we have that $\sum_{[u,v] \in \cP^k} Y'_{u-} \X_{u,v} \to 0$ as $k \to \infty$ as a limit in probability with respect to $\P \otimes \bar{\P}$, and by switching to a subsequence if necessary, we may assume that the limit
\begin{equation}\label{eq: lim sum Y'u- Xuv = 0}
\lim_{k \to \infty} \sum_{[u,v] \in \cP^k} Y'_{u-} \X_{u,v} = 0
\end{equation}
holds $(\P \otimes \bar{\P})$-almost surely.

We have by assumption that $(Y(\omega, \cdot),Y'(\omega, \cdot)) \in \cV_{X(\omega)}^{p,q,r,\bar{\Omega}}$ for $\P$-almost every $\omega \in \Omega$. For any such $\omega \in \Omega$, letting $\Xi_{s,t} = \Delta Y'_s(\omega, \cdot) \X_{s,t}(\omega)$, we have that
\begin{equation*}
\|\Xi_{s,t}\|_{L^q(\bar{\Omega})} \leq \delta(s)^{\frac{1}{p}} w(s,t)^{\frac{2}{p}},
\end{equation*}
where $\delta(s) := \|\Delta Y'_s(\omega, \cdot)\|_{L^q(\bar{\Omega})}^p$ and $w(s,t) := \|\X(\omega)\|_{\frac{p}{2},[s,t]}^{\frac{p}{2}}$. It then follows from \cite[Theorem~2.11]{FrizZhang2018} that $\sum_{[u,v] \in \cP^k} \Delta Y'_u(\omega, \cdot) \X_{u,v}(\omega) \to 0$ as $k \to \infty$ in probability with respect to $\bar{\P}$. Since this convergence holds for $\P$-almost every $\omega \in \Omega$, it follows that $\sum_{[u,v] \in \cP^k} \Delta Y'_u \X_{u,v} \to 0$ as $k \to \infty$ in probability with respect to $\P \otimes \bar{\P}$. By switching to a further subsequence if necessary, we may then assume that the limit
\begin{equation}\label{eq: lim Delta Y'_u Xuv = 0}
\lim_{k \to \infty} \sum_{[u,v] \in \cP^k} \Delta Y'_u \X_{u,v} = 0
\end{equation}
holds $\P \otimes \bar{\P}$-almost surely, and since $Y'_u = Y'_{u-} + \Delta Y'_u$, combining the limits in \eqref{eq: lim sum Y'u- Xuv = 0} and \eqref{eq: lim Delta Y'_u Xuv = 0}, we have that
\begin{equation}\label{eq: lim sum Y'u Xuv = 0}
\lim_{k \to \infty} \sum_{[u,v] \in \cP^k} Y'_u \X_{u,v} = 0
\end{equation}
also holds $\P \otimes \bar{\P}$-almost surely.

Combining \eqref{eq: lim Yu delta Xuv int Ys- dXs} and \eqref{eq: lim sum Y'u Xuv = 0}, we have in particular, by Fubini's theorem (e.g., \cite[Theorem~3.4.1]{Bogachev2007}), that for $\P$-almost every $\omega \in \Omega$, the limit
\begin{equation*}
\lim_{k \to \infty} \sum_{[u,v] \in \cP^k} Y_u(\omega, \cdot) \delta X_{u,v}(\omega) + Y'_u(\omega, \cdot) \X_{u,v}(\omega) = \bigg( \int_0^t Y_{s-} \dd X_s \bigg) (\omega, \cdot)
\end{equation*}
holds $\bar{\P}$-almost surely. However, by the definition of the rough stochastic integral (see Lemma~\ref{lemma: rough stochastic integral}), we also have that, for $\P$-almost every $\omega \in \Omega$,
\begin{equation*}
\lim_{k \to \infty} \sum_{[u,v] \in \cP^k} Y_u(\omega, \cdot) \delta X_{u,v}(\omega) + Y'_u(\omega, \cdot) \X_{u,v}(\omega) = \int_0^t Y_s(\omega, \cdot) \dd \bX_s(\omega)
\end{equation*}
exists as a limit in probability with respect to $\bar{\P}$. By the $\bar{\P}$-almost sure uniqueness of limits, for $\P$-almost every $\omega \in \Omega$, we have that
\begin{equation*}
\bigg( \int_0^t Y_{u-} \dd X_u \bigg)(\omega, \cdot) = \int_0^t Y_u(\omega, \cdot) \dd \bX_u(\omega),
\end{equation*}
$\bar{\P}$-almost surely. Since this holds for every $t \in [0,T]$, and both It\^o and rough stochastic integrals have almost surely c\`adl\`ag sample paths, we deduce the result.
\end{proof}

\begin{lemma}\label{lemma: |bX|_p,[0,T] leq N_alpha + jumps}
Let $p \in [2,3)$ and let $\bX \in \sV^p$ be a rough path. For any $\alpha > 0$, we have that
\begin{equation}\label{eq: bound on rough path norm in terms of N_alpha and jumps}
\|\bX\|_{p,[0,T]} \leq C \Big( N_{\alpha,[0,T]}\big(\|\bX\|_{p,[\cdot,\cdot)}^p\big) + 1 \Big)^{\hspace{-1pt}3} \Big( 1 + \sup_{t \in (0,T]} |\Delta \bX_t| \Big)^{\hspace{-1pt}2},
\end{equation}
where the constant $C$ depends only on $p$ and $\alpha$.
\end{lemma}

\begin{proof}
Let us write $N = N_{\alpha,[0,T]}(\|\bX\|_{p,[\cdot,\cdot)}^p)$ and $\{t_i\}_{i=0}^{N+1} = \{t_i(\alpha)\}_{i=0}^{N+1}$ for the partition defined in \eqref{eq: definition tau_i(alpha)}, with $t_{N+1} = T$. Let $\cP$ be an arbitrary partition of the interval $[0,T]$, and let $\bar{\cP} = \cP \cup \{t_i\}_{i=0}^{N+1}$. Similarly to the proof of \cite[Lemma~4]{FrizRiedel2013}, we bound
\begin{align*}
\sum_{[u,v] \in \cP} |\delta X_{u,v}|^p &\leq (N+1)^{p-1} \sum_{[s,t] \in \bar{\cP}} |\delta X_{s,t}|^p \leq (N+1)^{p-1} \sum_{i=0}^N \|X\|_{p,[t_i,t_{i+1}]}^p\\
&\leq (N+1)^{p-1} \sum_{i=0}^{N-1} \big( \|X\|_{p,[t_i,t_{i+1})} + |\Delta X_{t_{i+1}}| \big)^p \lesssim (N+1)^p \Big(\alpha + \sup_{t \in (0,T]} |\Delta X_t|^p \Big),
\end{align*}
where we used the fact that $\|X\|_{p,[t_i,t_{i+1}]} \leq \|X\|_{p,[t_i,t_{i+1})} + |\Delta X_{t_{i+1}}|$ (see \cite[Lemma~2.6]{AllanLiuProemel2021}), which implies that
\begin{equation*}
\|X\|_{p,[0,T]} \lesssim \Big( N_{\alpha,[0,T]}\big(\|\bX\|_{p,[\cdot,\cdot)}^p\big) + 1 \Big) \Big( 1 + \sup_{t \in (0,T]} |\Delta \bX_t| \Big).
\end{equation*}
A similar argument can then be used to bound $\|\X\|_{\frac{p}{2},[0,T]}$. This is more tedious, since $\X$ is not additive, and using Chen's relation introduces additional terms. In particular, we use the inequality $\|\X\|_{\frac{p}{2},[s,t]} \lesssim \|\X\|_{\frac{p}{2},[s,t)} + |\Delta \X_t| + \|X\|_{p,[s,t)}^2 + |\Delta X_t|^2$, which follows from a straightforward adaptation of the proof of \cite[Lemma~2.6]{AllanLiuProemel2021}. After some calculation, which we omit for brevity, we arrive at the estimate in \eqref{eq: bound on rough path norm in terms of N_alpha and jumps}.
\end{proof}



