\subsection{Clique and independent numbers of $D_n$}

\begin{prop}
    Suppose that $F(n)=(a_1, a_2, \ldots, a_d).$ Let $X$ be a maximal clique in $D_n$. Then
    \[ |X| = 1+ \sum_{i=1}^d a_i = 1+\Omega(n). \] 
    \end{prop}

