\end{eqnarray*}}

Here the family of seminorms $(P_{\alpha,\beta})_{\alpha,\beta\in\N_0}$ and the operators $X$ and $D$ are as defined in the proof of Lemma \ref{Schwartz-Lemma} (see \eqref{seminormP} and \eqref{X-D}). Therefore, we conclude that $f+\lambda g \in \mathcal{D}_{k,n}(\R)$,~which completes the proof of statement \textcolor{blue}{{\bf (i)}}.


For the proof of the statement {\bf (ii)} of Theorem \ref{Dkn-thm}, let $(f_m)_{m\in \mathbb{N}_0}$ be the sequence of functions defined in Lemma~\ref{Schwartz-Lemma}. Since both operators $\displaystyle x\frac{d}{dx}$ and  $\left|~\cdot~\right|^{2-\frac{2}{n}}\Delta_k$ map {\it functions with bounded support} to {\it functions with bounded support}, if $f\in \mathcal{D}_{k,n}(\R)$ satisfies the support condition $\operatorname{supp}(f)\subseteq [-R,R]$ for some $R>0$, then
	\begin{eqnarray*}
		\operatorname{supp}\left(\left(x\frac{d}{dx}\right)^j f\right)\subseteq [-R,R], & \mbox{holds for every} & j\in \N_0.
	\end{eqnarray*}

	An inductive application of the statement \textbf{(b)} in Lemma~\ref{Schwartz-Lemma} then shows that
	\begin{eqnarray*}
		\operatorname{supp}\left(\left(n\left|~\cdot~\right|^{2-\frac{2}{n}}\Delta_k\right)^\beta f_m\right)\subseteq [-R,R], & \mbox{for every} & \beta,m\in \N_0.
	\end{eqnarray*}

	So for all $\alpha,\beta,m\in \N_0$ and $x\in \R$ we get
	$$ \left|~\left(~n\left|~x~\right|^{\frac{2}{n}}~\right)^{\alpha} \left(~n\left|~x~\right|^{2-\frac{2}{n}}\Delta_{k}~\right)^\beta f_m(x)~\right|\leq n^\alpha R^{\frac{2\alpha}{n}} \left| \left(~n\left|~x~\right|^{2-\frac{2}{n}}\Delta_{k}~\right)^\beta f_m(x)~\right|.$$ 

	Hence, we deduce that \begin{eqnarray*}
		P_{\alpha,\beta}(f_m)\leq n^\alpha R^{\frac{2\alpha}{n}}  P_{0,\beta}(f_m), &\mbox{for each}&\alpha,\beta,m\in \N_0,
	\end{eqnarray*}
	where $\left(P_{\alpha,\beta}\right)_{\alpha,\beta\in \mathbb{N}_0}$ is the family of seminorms defined by \eqref{seminormP} in Lemma~\ref{Schwartz-Lemma}.

	Finally, by appealing to statement {\bf (a)} of the Lemma~\ref{Schwartz-Lemma}, we conclude the proof of the statement {\bf (b)}.
\end{proof}





\section{Density in $L^p(d\mu_{k, n})$}\label{Lp-section}

\subsection{Preliminary results}\label{key-subsection}

To establish afterwards the proof of Theorem \ref{DensityThm}, it is essential to employ an approximate identity alongside a convolution structure generated by a contractive translation operator. Such a contraction is attainable when $\displaystyle a=\frac{2}{n}$, as indicated by relations \eqref{normtrans} and \eqref{convolutionIntegral}.

We recall that a family $(\varphi_r)_{r>0}$ is called an approximate identity if and only if it satisfies:
\begin{itemize}
	\item[(a)] $\varphi_r\in L^1(d\mu_{k,n})$ for all $r>0$;
	\item[(b)] $\displaystyle \int_{\mathbb{R}}\varphi_r(x)\,d\mu_{k,n}(x)=1$ for every $r>0$;
	\item[(c)] For any $\delta>0$, 
	\[
	\lim_{r\to0}\int_{|x|\geq\delta}|\varphi_r(x)|\,d\mu_{k,n}(x)=0.
	\]
\end{itemize}

One method to construct an approximate identity is similar to the construction considered by the second author in collaboration with Ben Sa\"id in \cite{BeNe2}. Namely, by choosing a non-negative function $\varphi\in L^1(d\mu_{k,n})$ satisfying
\[
\int_{\mathbb{R}}\varphi(x)\,d\mu_{k,n}(x)=1.
\]
the sequence of functions $(\varphi_r)_{r>0}$ is defined, for each $r>0$, by the formula
\begin{eqnarray}
	\label{rDilation}
	\varphi_r(x)=r^{-\left(2k+\frac{2}{n}-1\right)}\varphi\left(\frac{x}{r}\right), & x\in \R.
\end{eqnarray}


For our purposes, the following result is also required for the proof of Theorem \ref{DensityThm}:
\begin{thm}[Theorem 3.1 of \cite{BeNe2}]\label{BeNe2-Thm}
	Suppose that $(\varphi_r)_{r>0}$ is an approximation identity as in \ref{rDilation}.
	\begin{itemize}
		\item[\bf (1)] If $f\in L^p(d\mu_{k, n})$, with $1\leq p<\infty$, then $f\star_{k ,n}\varphi_{r}\in L^p(d\mu_{k, n})$ and $f\star_{k ,n}\varphi_{r}\rightarrow f$ in the $L^p-$norm as $r\rightarrow 0$.
		\item[\bf (2)] If $f\in C_0(\R)$, then $f\star_{k ,n}\varphi_{r}\in L^\infty(d\mu_{k, n})$ and $f\star_{k ,n}\varphi_{r}\rightarrow f$ uniformly as $r\rightarrow 0$.
	\end{itemize}
\end{thm}

Other key results for the subsequent proof of the Theorem \ref{DensityThm} in Subsection \ref{ProofTheorem2} are the following propositions, involving the spaces $L^p(d\mu_{k, n})$ and $\mathcal{D}_{k,n}(\R)$, respectively:
\begin{proposition}\label{LpProposition}
	Let \( 1 \leq p < \infty \). For any function \( f \in L^p(d\mu_{k,n}) \), define the sequence of functions \((g_m)_{m\in\mathbb{N}_0}\), such that $g_m\in L^p(d\mu_{k,n})$, by
	\begin{equation}\label{gm}
		g_m(x) = \sum_{\ell=0}^m \binom{m}{\ell}\Bigl(2k+\frac{2}{n}\Bigr)^{m-\ell} \left(x\frac{d}{dx}\right)^{\ell} f(x), \quad x \in \mathbb{R}.
	\end{equation}
	Then, the following inequality holds:
	\begin{equation}\label{fLp}
		\|f\|_{L^p(d\mu_{k,n})} \leq \|g_m\|_{L^p(d\mu_{k,n})}.
	\end{equation}
\end{proposition}



\begin{proof}
	Let us denote by \(\mathcal{T}_{k,n}\) the integral operator defined by


	\[
	(\mathcal{T}_{k,n} f)(x) = \int_{0}^{1} f(tx)\, t^{2k+\frac{2}{n}-1}\, dt, \quad x \in \mathbb{R}.
	\]


	For \(t > 0\), the chain rule gives


	\[
	\frac{d}{dt}\Bigl(t^{2k+\frac{2}{n}} f(tx)\Bigr) = \Bigl(2k+\frac{2}{n}\Bigr) t^{2k+\frac{2}{n}-1} f(tx) + t^{2k+\frac{2}{n}-1}\Bigl(tx \frac{d}{d(tx)}f\Bigr)(tx), \quad x \in \mathbb{R}.
	\]


	Integrating the previous expression yields
	\[
	f(x) = \int_0^1 \frac{d}{dt}\Bigl(t^{2k+\frac{2}{n}} f(tx)\Bigr)\, dt, \quad x \in \mathbb{R},
	\]
	which shows that \(\mathcal{T}_{k,n}\) is the inverse of the differential operator
	\[
	x\,\frac{d}{dx} + \Bigl(2k+\frac{2}{n}\Bigr)I.
	\]

	Next, let us consider the sequence of functions \(\left(g_m\right)_{m\in\mathbb{N}_0}\) defined by \eqref{gm}.
	A direct computation shows that

	\[
	g_m(x) = (\mathcal{T}_{k,n}g_{m+1})(x), \quad x \in \mathbb{R}, \quad m \in \mathbb{N}_0.
	\]
	Furthermore, applying Minkowski's integral inequality, we obtain
	\[
	\|g_m\|_{L^p(d\mu_{k,n})}^p \leq \int_{0}^{1} \left(\int_{\mathbb{R}} \bigl|g_{m+1}(tx)\bigr|^p\, d\mu_{k,n}(x)\right) t^{2k+\frac{2}{n}-1}\, dt, \quad m \in \mathbb{N}_0.
	\]


	Since the measure \(d\mu_{k,n}\) is homogeneous of order \(2k+\frac{2}{n}-1\), i.e.,


	\[
	d\mu_{k,n}(tx) = t^{2k+\frac{2}{n}-1}\, d\mu_{k,n}(x), \quad \forall\, x \in \mathbb{R},\, t > 0,
	\]


	the above inequality simplifies to


	\[
	\|g_m\|_{L^p(d\mu_{k,n})}^p \leq \|g_{m+1}\|_{L^p(d\mu_{k,n})}^p, \quad m \in \mathbb{N}_0.
	\]


	An inductive argument then yields
	\begin{eqnarray*}
		\|f\|_{L^p(d\mu_{k,n})}^p \leq \|g_m\|_{L^p(d\mu_{k,n})}^p, \quad \forall\, m \in \mathbb{N}_0,
	\end{eqnarray*}
	which is equivalent to \eqref{fLp}.
\end{proof}



{\begin{proposition}\label{Lem}
		Let $\varphi\in \mathcal{D}_{k,n}(\R)$ and $f\in C^\infty(\R)$. 
		We assume that $\operatorname{supp}(\varphi)\subseteq [-R_1,R_1]$ and $\operatorname{supp}(f)\subseteq [-R_2,R_2]$. 
		Then, have the following:
		\begin{itemize}
			\item[{\bf (a)}] $\operatorname{supp}(f\star_{k,n}\varphi)\subseteq [-R,R]$, with $R=\left((R_1)^\frac{1}{n}+(R_2)^\frac{1}{n}\right)^n$.
			\item[{\bf (b)}] $f\star_{k,n}\varphi$ belongs to $\mathcal{D}_{k,n}(\R)$.
		\end{itemize}
\end{proposition}}



\begin{proof}	
	First, by \eqref{Kkernel}, the condition $\operatorname{supp}(f) \subseteq [-R_2,R_2]$ implies that $$
	\operatorname{supp}(\tau_{k,n}^yf)\subseteq \left[-\left(|y|^\frac{1}{n}+(R_2)^\frac{1}{n}\right)^n,\left(|y|^\frac{1}{n}+(R_2)^\frac{1}{n}\right)^n\right],$$
	where $\tau_{k,n}^y$ is the generalized translation operator defined in \eqref{translation}. Thus, the statement \textbf{(a)} follows directly from the definition \eqref{convolutionIntegral} of the convolution $\star_{k,n}$.

	To prove the statement {\bf (b)}, note that $f\star_{k,n}\varphi \in \mathcal{D}_{k,n}(\R)$ if and only if
	$$
	\sup_{x\in \R\setminus\{0\}}	\left|\left(~n\left|~x~\right|^{2-\frac{2}{n}}\Delta_k~\right)^\alpha \left(x\frac{d}{dx}\right)^\ell\left(f\star_{k,n} \varphi\right)(x)\right|<\infty. 
	$$

	By the $\kn$-generalized convolution formula \eqref{convolutionIntegral}, we have
	{$$
		\left(~n\left|~x~\right|^{2-\frac{2}{n}}\Delta_k~\right)^\alpha \left(x\frac{d}{dx}\right)^\ell \left(f\star_{k,n} \varphi\right)(x)=$$ $$\int_{\mathbb{R}}(\mathcal{F}_{k,n} f)(y)~(\mathcal{F}_{k,n}\varphi)(y)~ \left(~n\left|~x~\right|^{2-\frac{2}{n}}\Delta_k~\right)^\alpha \left(x\frac{d}{dx}\right)^\ell B_{k,n}\left(~(-1)^nx,y~\right)d\mu_{k,n}(y), \quad x\in \mathbb{R}.$$}


	Then, by Lemma \ref{lem} it suffices to show that, for every $x\in [-R,R]$,~the auxiliary function
	\begin{eqnarray}
		\label{Gkn}
		G_{k,n,\eta}(x):=\int_{\mathbb{R}}(\mathcal{F}_{k,n} f)(y)~(\mathcal{F}_{k,n}\varphi)(y)~\left(|x|^{\frac{2}{n}}\right)^r\left(|y|^{\frac{2}{n}}\right)^q\j_{\eta}(n|xy|^{\frac{1}{n}})d\mu_{k,n}(y)
	\end{eqnarray}
	satisfies $\| G_{k,n,\eta}\|_{L^\infty(d\mu_{k,n})}<\infty$.

	First, for  $x\in[-R,R]$, $r,q\in\N_0$ and $\eta>-\frac{1}{2}$, one easily checks that $$\left(|x|^{\frac{2}{n}}\right)^r\left(|y|^{\frac{2}{n}}\right)^q\left|\j_{\eta}(n|xy|^{\frac{1}{n}})\right|\leq R^{\frac{2r}{n}}|y|^{\frac{2q}{n}}.$$

	 Thus,
	\begin{equation}\label{ConvIneq}\left|\mathcal{F}_{k,n} f(y)~\mathcal{F}_{k,n}\varphi(y)~|x|^{\frac{2}{n}r}|y|^{\frac{2}{n}q}\j_{\eta}(n|xy|^{\frac{1}{n}})\right|\leq {R^{\frac{2r}{n}}} \left|\mathcal{F}_{k,n} f(y)\right|~|y|^{\frac{2q}{n}}\left|\mathcal{F}_{k,n}\varphi(y)\right|.
	\end{equation}


{Since \(f\in L^1(d\mu_{k,n})\) implies that \(\mathcal{F}_{k,n}f\in L^\infty(d\mu_{k,n})\), and \(\varphi\in \mathcal{D}_{k,n}(\R)\subseteq\mathcal{S}_{k,n}(\R)\)  ensures that  \(\mathcal{F}_{k,n}\varphi\in \mathcal{S}_{k,n}(\R)\) (by Theorem \ref{Fkn-Schwartz-Theorem}),  it follows that the function $y\mapsto |y|^{\frac{2}{n}q}\mathcal{F}_{k,n}\varphi(y)$ belongs to $L^1(d\mu_{k,n})$.} 
	Then, from \eqref{ConvIneq} we immediately get
	\begin{eqnarray*}
		\| G_{k,n,\eta}\|_{L^\infty(d\mu_{k,n})}\leq \textcolor{blue}{R^{\frac{2r}{n}}} \| \mathcal{F}_{k,n}f\|_{L^\infty(d\mu_{k, n})}~\left\| ~|\cdot|^{\frac{2q}{n}}\mathcal{F}_{k,n}\varphi~\right\|_{L^1(d\mu_{k,n})}<\infty.
	\end{eqnarray*}

	This completes the proof of the statement {\bf (b)}.
\end{proof}




