\subsection{Signal Model}
The microphone signals of the primary device can be defined as
\begin{equation}
\label{equ:mic_sig_TD}
y_{0,m}\left[n\,T_{0}\right] = \sum_{q=1}^{2} h_{0,q,m}[n\,T_{0}] * x_{q}\left[n\,T_{0}\right] + v_{0,m}\left[n\,T_{0}\right],
\end{equation}
where $n$ is the sample index, $T_0 = \frac{1}{f_0}$ is the sampling period of the primary device, $m \in \{1,2,\ldots,M\}$ is the microphone index, $q$ is the index of the auxiliary device, $x_q\left[n\,T_{0}\right]$ denotes the playback signal sent to the $q^\text{th}$ loudspeaker, $v_{0,m}\left[n\,T_{0}\right]$ is the contribution of sensor noise, $h_{0,q,m}[n\,T_{0}]$ is the \ac{AIR} between the loudspeaker of the $q^{th}$ auxiliary device and the microphone of the primary device. Since the loudspeaker of $q^{th}$ auxiliary device converts the digital signal $x_q\left[n\,T_s\right]$ that is transmitted from the primary device into its analog counterpart at a sampling rate of $f_q$ and the microphone of the primary device converts the analog signal back to a digital signal at a sampling rate of $f_0$, we can define the relation between $f_s$ and $f_0$ in terms of \ac{SRO} between the devices $\epsilon_{q}$ and $\epsilon_{0}$ as
\begin{equation}
\label{equ:relation_frequencies_SRO}
f_0 = (1+\epsilon_{q})\,(1+\epsilon_{0})\,f_s,
\end{equation}
where $|\epsilon_{q}| \ll 1$ and $|\epsilon_{0}| \ll 1$ are usually expressed in~\ac{ppm}. Since the terms $\epsilon_{q}$ and $\epsilon_{0}$ are very small, the term $\epsilon_{q}*\epsilon_{0}$ can be ignored. This further simplifies \eqref{equ:relation_frequencies_SRO} as
\begin{equation}
\label{equ:relation_frequencies_SRO_1}
f_0 = (1+\epsilon_{q}+\epsilon_{0})\,f_s = (1+\bar{\epsilon}_{q})\,f_s.
\end{equation}

Substituting \eqref{equ:relation_frequencies_SRO_1} in \eqref{equ:mic_sig_TD}, applying Taylor series approximation to the term $x_{q}\left[\frac{n}{(1+\bar{\epsilon}_{q})\,f_s}\right]$~\cite{SMG_BSRO_2012},~\eqref{equ:mic_sig_TD} can be approximated in the time-frequency domain with sufficiently long window size $N_\text{w}$ and hop size $N_\text{h}$ as
\begin{multline}
\label{equ:mic_sig_FD}
Y_{0,m}\left[ k, l \right] = \sum_{q=1}^{2} H_{0,q,m}\left[ k, l \right] ~\Lambda_{q}\left[ k, l \right] ~X_{q}\left[ k, l \right]   \\
 + V_{0,m}\left[ k, l \right],
\end{multline}
where $\Lambda_{q}\left[ k, l \right]  = \text{exp}\left(\frac{-j2\pi k}{N_\text{w}}\left(\frac{l\,N_\text{h}\,\bar{\epsilon}_{q}}{f_{s}}\right)\right)$, $X_{q}\left[ k, l \right]$, $H_{0,q,m}\left[ k, l \right]$ and $V_{0,m}\left[ k, l \right]$ with frequency index~$k$ and frame index~$l$ are the frequency-domain representation of $x_{q}\left[n\,T_{s}\right]$, $h_{0,q,m}[n\,T_0]$ and $v_{0,m}\left[n\,T_{0}\right]$, respectively. Similarly to \eqref{equ:listener_sig_FD_SRO}, \eqref{equ:mic_sig_FD} also holds only if the condition $\frac{l\,N_\text{h}\,\bar{\epsilon}_{q}}{f_{s}} \ll N_\text{w}$ is satisfied~\cite{wang_CMSRO_WASN_2016}. Since the primary device estimates the term $\bar{\epsilon}_{q}$, in the current work, we assume that $\epsilon_0$ is known a priori to estimate $\epsilon_q$ from $\bar{\epsilon}_{q}$. 

%\vspace{-1mm}
\subsection{Playback Signal-Assisted Spatial Filtering} %Estimation}
In vector notation, \eqref{equ:mic_sig_FD} can be written as
\begin{equation}
\label{equ:mic_sig_FD_vecNotation}
\mathbf{y} = \mathbf{H}\,\mathbf{\Lambda}\,\mathbf{x} + \mathbf{v},
\end{equation}
where the microphone signal $\mathbf{y}$, playback signal $\mathbf{x}$, \ac{ATF} $\mathbf{H}$, \ac{SRO} contribution $\mathbf{\Lambda}$ and sensor noise $\mathbf{v}$ are defined as
\begin{equation}
\label{equ:mic_sig_vec_notation}
\mathbf{y} = [Y_{0,0}\left[ k, l \right],Y_{0,1}\left[ k, l \right] \cdots Y_{0,M-1}\left[ k, l \right]]^T \in R^{M \times 1},
\end{equation}
\begin{equation}
\label{equ:playback_sig_notation}
\mathbf{x} = [X_{1}\left[ k, l \right],X_{2}\left[ k, l \right]]^T \in R^{2 \times 1},
\end{equation}
\begin{equation}
\label{equ:ATF_vec_notation}
\mathbf{H} = [\mathbf{h}_{0,1},\mathbf{h}_{0,2}] \in R^{M \times 2},
\end{equation}
\begin{equation}
\label{equ:SRO_contribution_vec_notation}
\mathbf{\Lambda} = \text{diag}[\Lambda_{1}\left[ k, l \right],\Lambda_{2}\left[ k, l \right]] \in R^{2 \times 2},
\end{equation}
\begin{equation}
\label{equ:sensor_noise}
\mathbf{v} = [V_{0,0}\left[ k, l \right],V_{0,1}\left[ k, l \right] \cdots V_{0,M-1}\left[ k, l \right]]^T \in R^{M \times 1},
\end{equation}
where $\mathbf{h}_{0,q} = [H_{0,q,0}\left[ k, l \right],H_{0,q,1}\left[ k, l \right] \cdots H_{0,q,M-1}\left[ k, l \right]]^T$. 
Since we aim to robustly estimate $\bar{\epsilon}_{1}$ and $\bar{\epsilon}_{2}$, we need to extract individual terms $\mathbf{h}_{0,1}\,\Lambda_{1}\left[ k, l \right]\,X_{1}\left[ k, l \right]$ and $\mathbf{h}_{0,2}\,\Lambda_{2}\left[ k, l \right]\,X_{2}\left[ k, l \right]$ from the microphone signal $\mathbf{y}$. In this study, we employ a well-known \ac{LCMV} beamformer\,\cite{VanVeen_1988} to extract individual contributions from the microphone signal. The $q^{\text{th}}$ output of the beamformer $\widehat{Z}_q\left[ k, l \right]$ can be described as
\begin{equation}
\label{equ:beamformer_ouput}
\widehat{Z}_q\left[ k, l \right] = \mathbf{w}^{H}_{q}\left[ k, l \right]\,\mathbf{y},
\end{equation}
where $\mathbf{w}_{q}\left[ k, l \right]$ contains the beamformer weights computed by treating the $q^\text{th}$ loudspeaker as the "source of interest" and the another loudspeaker as the interferer and superscript $(\cdot)^H$ denotes the Hermitian. Ideally, $\widehat{Z}_q\left[ k, l \right] \approx \mathbf{h}_{0,q}\,\Lambda_{q}\left[ k, l \right]\,X_{q}\left[ k, l \right] + \mathbf{v}$. The \ac{LCMV} beamformer $\mathbf{w}_{q}\left[ k, l \right]$ is computed by solving the optimization problem\,\cite{Frost1972}
\begin{multline}
\label{equ:lcmv_optim_problem}
\mathbf{w}_{q}\left( k, l \right) = \arg \min_{\mathbf{w}_{q}} \mathbf{w}_{q}^{H}\,\mathbf{\Phi}_{v}\,\mathbf{w_{q}} \\
\text{subject to}~\mathbf{w}_{q}^{H}\,\mathbf{A}\left[ k, l \right] = \mathbf{g}_q,
\end{multline}
where the gain $\mathbf{g}_q$ is the $q^\text{th}$ column of identity matrix $\mathbf{I} \in \mathbb{R}^{2 \times 2}$, $\mathbf{A}\left[ k, l \right] = [\mathbf{a}_{0}, \mathbf{a}_{1} \cdots \mathbf{a}_{Q}] \in R^{M \times 2}$ is the \ac{RTF} matrix, $\mathbf{a}_{q} = \frac{\mathbf{h}_{0,q}}{H_{0,q,0}}$ is the \ac{RTF} vector under the assumption that $0^\text{th}$ microphone is the reference microphone.
The solution to the above optimization problem is given by
\begin{equation}
\label{equ:lcmv_bf}
\mathbf{w}_{q}\left[ k, l \right] = \mathbf{\Phi}_{v}^{-1}\,\mathbf{A}\left[ k, l \right]\,\left[ \mathbf{A}^{H}\left[ k, l \right]\,\mathbf{\Phi}_{v}^{-1}\,\mathbf{A}\left[ k, l \right]\right]^{-1} \,
\mathbf{g}_{q}, 
\end{equation}
where $\mathbf{\Phi}_{v}$ is the noise \ac{PSD} matrix. The inverse term in \eqref{equ:lcmv_bf} exists only if it satisfies the following criteria\,\cite{VanVeen_1988, VanTrees2002, chakrabarty2016numerical}: i) $\mathbf{\Phi}_{v}$ is full-rank, ii) $\mathbf{A}\left[ k, l \right]$ has linearly independent columns. We set $\mathbf{\Phi}_{v} = \mathbf{I}$ in our implementation, which satisfies the first criterion. However, since we cannot guarantee that the second criterion is fulfilled, we use a simple regularization method called diagonal loading where a small term $\alpha\,\mathbf{I}$ is added to the inverse term\,\cite{bishop2006pattern, chakrabarty2016numerical} to ensure numerical stability. With the above, the solution to the \ac{LCMV} beamformer is given by
\begin{equation}
\label{equ:lcmv_bf_v1}
\mathbf{w}_{q}\left[ k, l \right] = \mathbf{A}\left[ k, l \right]\,\left[ \mathbf{A}^{H}\left[ k, l \right]\,\mathbf{A}\left[ k, l \right] + \alpha\,\mathbf{I}\right]^{-1}\,\mathbf{g}_{q}, 
\end{equation}
where $\alpha$ is a small constant. 

Accurate estimation of the \ac{RTF} matrix $\mathbf{A}\left[ k, l \right]$ is essential for the computation of the beamformer weights defined in \eqref{equ:lcmv_bf_v1}. There exist many methods to estimate \ac{RTF}, among them, minimum distortion-based estimator\,\cite{Chen2008} and subspace-based estimators\,\cite{Markovich2009} can be considered as state-of-the-art estimators. These estimators work well for one source; however, in case of multiple sources, these estimators require periods where only one source is active. The authors of\,\cite{Taseska_2015} proposed a time-varying \ac{RTF} estimator per time-frequency bin corresponding to the dominant source at that bin. Since the \ac{RTF} estimation is not the main focus of the paper, in the current study, we use an oracle \ac{RTF}, which is computed as
\begin{equation}
    \label{equ:oracle_RTF}
    \mathbf{a}_q\left[ k, l \right] = \frac{\mathbf{\bar{\mathbf{\Phi}}}_q}{\mathbf{e}^T\mathbf{\bar{\mathbf{\Phi}}}_q}, 
\end{equation}
where $\mathbf{e}=[1,0,\cdots0]^T$ is the selection vector, $\mathbf{\bar{\mathbf{\Phi}}}$ is the PSD matrix defined as
\begin{equation}
    \label{equ:cross_covariance_marix}
    \mathbf{\bar{\mathbf{\Phi}}}_q = \mathbf{E}\{\mathbf{\bar{z}}_q\,X^{*}_q\}, 
\end{equation}
where $(\cdot)^*$ denotes the complex conjugate, $\mathbf{\bar{z}}_q$ is the microphone signal containing only the playback signal $X_q$.   

\subsection{SRO Estimation}

\begin{figure*}[t]
  \centering
  \subfigure[ITD]{
    \includegraphics[width=0.48\linewidth]{./figures/ITD_comparison_plot_stereo_phantom_source.eps}
  }
  \hfill
  \subfigure[IC]{
