  }
  \caption{Difference plots of \ac{ITD} and \ac{IC} w.r.t. no-SRO for the conditions (\,top: no compensation, middle: oracle compensation, bottom: oracle-\ac{RTF}-based compensation\,) at three different \ac{SRO} configuration (\,left: [10,\,-10]\,\ac{ppm},\,mid: [10,\,-50]\,\ac{ppm},\,right: [10,\,-100]\,\ac{ppm}\,).}
  \label{fig:objective_metrics}
\end{figure*}

To estimate the~\ac{SRO}, we use the~\ac{DWACD} algorithm proposed in~\cite{gburrek_synchronization_2022}. Given the input signal $\widehat{Z}_q\,\left[k,l\right]$ and the reference signal $X_q\,\left[k,l\right]$, the \ac{SRO} estimation relies on first computing the complex coherence function $\Gamma\left[k,l\right]$, which is given by
%~($\Phi_{\tilde{E}~X^{2}}$) ($\Phi_{X^{2}~X^{2}}$ and $\Phi_{\tilde{E}\tilde{E}}$). 
\begin{equation}
\label{coherence_func_ACD}
\Gamma\left[k,l\right] = \frac{\Phi_{\widehat{Z}_q\,X_q}\left[k,l\right]}{\sqrt{\Phi_{\widehat{Z}_q\,\widehat{Z}_q}\left[k,l\right]\Phi_{X_q\,X_q}\left[k,l\right]}}, 
\end{equation}
where $\Phi_{\widehat{Z}_q\,X_q}$, $\Phi_{\widehat{Z}_q\,\widehat{Z}_q}$ and $\Phi_{X_q\,X_q}$ are the cross and auto \acp{PSD}, respectively. The phase function $\widetilde{P}\left[k,l\right]$ is computed by the complex conjugated product of two consecutive complex coherence functions with a temporal distance of $L$. It is given by 
\begin{equation}
\label{avg_coherence_func_wACD}
\widetilde{P}\left[k,l\right] = \Gamma\left[k,l+L\right]~\Gamma^*\left[k,l\right].
\end{equation}
The temporally averaged phase function $P\left[k,l\right]$ and the \ac{GCC} $p(\beta,l)$ are given by
\begin{equation}
\label{avg_coherence_func_dwACD}
P\left[k,l\right] = \alpha~P\left[k,l-1\right] + (1-\alpha)~\widetilde{P}\left[k,l\right],
\end{equation}
\begin{equation}
\label{equ:gcc}
p\left[\beta,l\right] = \textrm{IDFT}\{P\left[k,l\right]\},
\end{equation}
where $\alpha$ is the smoothing factor, $\beta$ is the time-lag, and $\textrm{IDFT}$ is the inverse DFT. 
%
The estimated~\ac{SRO} $\widehat{\bar{\epsilon}}_{q}$ is obtained by first finding the integer time-lag $\beta_\text{max}$ that maximizes the~\ac{GCC} 
\begin{equation}
\label{SRO_estimate_dwACD_1}
\widehat{\bar{\epsilon}}_{q}\left[l\right] = -\frac{1}{L\,N_{\text{h}}}\beta_\text{max} = -\frac{1}{L\,N_{\text{h}}}\,\arg \max_{\beta}|p\left[\beta,l\right]|.
\end{equation} 
Then, an \ac{SRO} estimate is obtained by determining the non-integer time-lag by performing a golden search in the interval given by $[\beta_\text{max}-0.5,\beta_\text{max}+0.5]$. 
%
The complex coherence function $\Gamma\left[k,l\right]$ is estimated only when voice activity is detected in both signals $\widehat{Z}_q\left[k,l\right]$ and $X_q\left[k,l\right]$. In this study, we used the energy-based voice activity detector to detect voice activity. To avoid temporal fluctuations in the estimated \ac{SRO}, we apply temporal smoothing on the estimated \ac{SRO}.  

