Of course applying the involution to the vertical squares in Lemma \ref{la:LSSS} yields a pair of horizontal squares.  Similarly, the next two results have duals, which we will not state explicitly.

\begin{lemma}\label{la:SSpSS}
Let $\smat efgh$ be a singular square that is LR-singularised by the idempotent $pq$, where $(p,q)\in\F$.  Then the squares 
\[
\smat e{ep}g{gp} \ANd \smat f{ep}h{gp}
\]
are both LR-singularised by $p$.  
\end{lemma}


\begin{proof}
Since $pq$ is a left identity for each of $e$, $f$, $g$ and $h$, it follows that $p$ is a left identity for the same elements. Hence $\smat e{ep}g{gp}$ and $\smat f{fp}h{hp}$ are singularised by $p$. 
Since $epq=f$ and  $p\mr\F q$ it follows that
$fp=(epq)p=ep$; analogously, $hp=gp$, completing the proof.
\end{proof}





\begin{lemma}\label{la:SSLS}
Let $\smat efgh = \smat{sv}{sw}{uv}{uw}$ be a singular square that is LR-singularised by the projection~$p$, and where $(s,v),(s,w),(u,v),(u,w)\in\F$.  Then $(s,v;s,w)$ and $(u,v;u,w)$ are $p$-linked diamonds of projections (i.e.~$(s,v,w)$ and $(u,v,w)$ are $p$-linked triangles), yielding the $p$-linked squares of idempotents
\[
\smat sf{e^*}{vw} = \smat s{sw}{vs}{vw} \ANd \smat uh{g^*}{vw} = \smat u{uw}{vu}{vw}.
\]
\end{lemma}



\begin{proof}
We prove the statement for $(s,v;s,w)$; $(u,v;u,w)$ is analogous.
Since, by assumption, $(s,v),(s,w)\in\F$, and $(s,s)\in\F$ trivially,
we just need to verify that $(v,w)\in\F$, $psp=s$ and $pvp=w$.
Keeping in mind \ref{it:RS5}, we have $s=ee^*=ff^*$, $v=e^*e$ and $w=f^*f$.
Now we have:
\[
psp =pee^*p=(pe)(pe)^*=ee^*=s \AND
pvp=pe^*ep=(ep)^*(ep)=f^*f=w.
\]
With the help of the the second equality above, and remembering that the product of two projections is an idempotent, we also have $wvw = pvp\sgap v\sgap pvp=pvp=w$, and 
\begin{align*}
vwv &= v\sgap pvp\sgap v=vpv=e^*eppe^*e=e^* (ep)(ep)^*e=e^*ff^*e=e^*ee^*e=e^*e=v,
\end{align*}
completing the proof.
\end{proof}




We now have:


\begin{prop}
\label{pr:coreq}
The presentations given in Corollaries \ref{co:lkid} and \ref{cor:pgmaxq} are equivalent.
\end{prop}



\begin{proof}
($\Leftarrow$)
We show that  relations \mbox{\eqref{eq:pq19}--\eqref{eq:pq21}} imply~\eqref{eq:rwp43}.
Suppose $\smat efgh$ is a linked square of idempotents in $E_D$, so that ${\smat efgh = \smat{sv}{sw}{uv}{uw}}$ for a corresponding linked diamond of projections $(s,u;v,w)$; cf.~Remark~\ref{rem:plinkedsquare}.  Using the singular squares $\smat efv{vw}$ and $\smat gh{wv}w$ from Lemma \ref{la:LSSS}, we calculate
\[
a_e^{-1}a_f %= a_{sv}^{-1}a_{sw} 
\stackrel{\text{\tiny\eqref{eq:pq21}}}{=} a_v^{-1}a_{vw} 
\stackrel{\text{\tiny\eqref{eq:pq19}}}{=} a_{vw} 
\stackrel{\text{\tiny\eqref{eq:pq22}}}{=} a_{wv}^{-1} 
\stackrel{\text{\tiny\eqref{eq:pq19}}}{=} a_{wv}^{-1} a_w
\stackrel{\text{\tiny\eqref{eq:pq21}}}{=} %a_{uv}^{-1} a_{uw} = 
a_g^{-1}a_h,
\]
which is exactly relation \eqref{eq:rwp43} for our original square $\smat efgh$.

($\Rightarrow$)
Now we show that  relations \eqref{eq:rwp40}--\eqref{eq:rwp43} imply the singular square relations
arising from $\smat efgh = \smat{sv}{sw}{uv}{uw}$.
First we do this in the case when the square is LR-singularised by a projection $p$.  By Lemma \ref{la:SSLS} we have two $p$-linked squares of idempotents
$\smat sf{e^*}{vw}$ and $ \smat uh{g^*}{vw}$.
Using these, we calculate
\[
a_f
\stackrel{\text{\tiny\eqref{eq:rwp40}}}{=} a_s^{-1}a_f
\stackrel{\text{\tiny\eqref{eq:rwp43}}}{=} a_{e^*}^{-1}a_{vw}
\stackrel{\text{\tiny\eqref{eq:rwp42}}}{=} a_ea_{vw}
\ANd
a_h
\stackrel{\text{\tiny\eqref{eq:rwp40}}}{=} a_u^{-1}a_h
\stackrel{\text{\tiny\eqref{eq:rwp43}}}{=} a_{g^*}^{-1}a_{vw}
\stackrel{\text{\tiny\eqref{eq:rwp42}}}{=} a_ga_{vw}.
\]
These in turn yield $a_e^{-1}a_f = a_{vw}$ and $a_g^{-1}a_h = a_{vw}$, which combine to give $a_e^{-1}a_f = a_g^{-1}a_h$, i.e.~the relation~\eqref{eq:pq21} for the square $\smat efgh$.

Now consider a square $\smat efgh$ that is LR-singularised by an arbitrary idempotent $pq$, where $(p,q)\in\F$. By Lemma \ref{la:SSpSS}, the squares $\smat e{ep}g{gp}$ and $\smat {ep}f{gp}h$ are LR-singularised by the projection~$p$. By the previous paragraph, \eqref{eq:rwp40}--\eqref{eq:rwp43} imply
\[
a_e^{-1}a_{ep} = a_g^{-1}a_{gp} \ANd a_{ep}^{-1}a_f = a_{gp}^{-1}a_h,
\]
which, in turn, imply
$a_e^{-1}a_f = a_e^{-1}a_{ep} \sgap a_{ep}^{-1}a_f = a_g^{-1}a_{gp} \sgap a_{gp}^{-1}a_h = a_g^{-1}a_h$, i.e.~relation~\eqref{eq:pq21} for the LR square $\smat efgh$.

The proof for UD squares is dual, and the proposition follows.
\end{proof}



\begin{rem}\label{rem:LSSS}
It is worth drawing out the fact (which is apparent in the proof of Proposition~\ref{pr:coreq}) that in the presentation from Corollary \ref{cor:pgmaxq}, we only need to include singular square relations~\eqref{eq:pq21} for squares singularised by projections.
