Our first goal is to show that our groups $\GI$ and $\GP$ are generated by letters $a_e$ corresponding to idempotents $e\in E(n,r)$ with small $\NTu$ and $\NTd$ parameters; see Lemma \ref{la:geneli}.  The key idea behind this is the following:

\begin{defn}\label{defn:NT}
We say that a singular square $\smat{e_1}{e_2}{e_3}{e}\in\Sq(n,r)$ is \emph{NT-reducing} with \emph{base} $e$ if
\[
\NTu(e_2)<\NTu(e) \quad \text{and} \quad \NTd(e_3)<\NTd(e).
\]
\end{defn}

Combined with \eqref{eq:NT}, the above inequalities in fact yield
\[
\NTu(e_1)=\NTu(e_2)<\NTu(e_3)=\NTu(e) \quad\textup{and}\quad
\NTd(e_1)=\NTd(e_3)<\NTd(e_2)=\NTd(e),
\]
which in turn yields
\begin{equation}\label{eq:NTei}
\NT(e_i)< \NT(e)\quad \text{for } i=1,2,3.
\end{equation}
Consequently, every NT-reducing square is non-degenerate.  



\begin{rem}\label{rem:NTred}
One can visualise an NT-reducing square $\smat{e_1}{e_2}{e_3}e$ using the stratification of the $\D$-class $D(n,r)$, as explained in Remark \ref{rem:eggbox1}.  In the notation of that remark, we have
\[
e \in E^k_l \ANd e_1 \in E^{k'}_{l'} \qquad\text{for some $0\leq k'<k\leq n-r$ and $0\leq l'<l\leq n-r$,}
\]
and then we also have $e_2\in E^{k'}_l$ and $e_3\in E^k_{l'}$.  In particular, $e_1$, $e_2$ and $e_3$ are closer than $e$ to the top-left corner of the $\D$-class~$D(n,r)$.  This is all shown in Figure \ref{fig:eggbox1} (right).
\end{rem}







For an equivalence relation $\sigma$ on a set $X$, with equivalence classes $A_1,\ldots,A_k$,
let $\id_\sigma$ denote the full-(co)domain projection  $\begin{partn}{3} A_1 &\cdots & A_k\\ \hhline{~|~|~} A_1& \cdots 
&A_k\end{partn}$ in $\P_X$.
For any $a\in\P_n$, define the projections ${\ED(a):= \id_{\ker(a)}}$ and $\ER(a):= \id_{\coker(a)}$.
Observe that
$\ED(a)a=a=a\ER(a)$.
In fact, the $\ED$ and $\ER$ operations give $\P_n$ the structure of an \emph{Ehresmann semigroup}; see \cite{EG21}.

\begin{lemma}
\label{la:ehrsq}
Let $e,f\in E(n,r)$ be such that $e\mr\L f$ and $\ker(e)\subseteq \ker(f)$.
Then 
\[
\begin{pmatrix} e_1 & e_2\\ e_3& e\end{pmatrix}:=
\begin{pmatrix} f\ED(e) & f \\ e\ED(e)&e\end{pmatrix}
\] 
is a singular square. Furthermore, if $\ker(e)\neq \ker(f)$ and $\ker(e)\nsubseteq\coker(e)$ then
the square is NT-reducing with base $e$.
\end{lemma}

\begin{proof}
We have already noted that $\ED(e) e=e$; also, $\ED(e)f=f$, as $\ker(e)\subseteq \ker(f)$.
It therefore follows that $\smat{e_1}{e_2}{e_3}{e}$ is indeed an RL-square singularised by $\ED(e)$. This square is illustrated in Figure \ref{fig:ehr}.

When $\ker(e)\neq \ker(e_2)$, we have $\ker(e)\subsetneq\ker(e_2)$, so there are more $\ker(e)$-classes than $\ker(e_2)$-classes.  Since $\rank(e) = \rank(e_2)$, we then deduce $\NTu(e)>\NTu(e_2)$ from \eqref{eq:Vert}.


If $\ker(e)\nsubseteq\coker(e)$, then
\[
\coker(e_3)=\coker(eD(e))=\coker(e)\vee \ker(e)\supsetneq \coker(e),
\]
so it again follows from \eqref{eq:Vert} that $\NTd(e)>\NTd(e_3)$.
\end{proof}


The previous lemma has a dual, but we do not need to state it explicitly.

\begin{rem}
As a special instance of the square from Lemma \ref{la:ehrsq}, we can take $f = R(e)e$.  It follows from $eR(e)=e$ that $e\mr\L f$, and we have $\ker(f) = \ker(R(e)e) = \coker(e)\vee\ker(e) \supseteq \ker(e)$.  So we indeed have the square
\[
\lmat {R(e)eD(e)}{R(e)e}{eD(e)}{e},
\]
which is in fact RL- and DU-singularised by $D(e)$ and $R(e)$, respectively.  (This square is present in any Ehresmann semigroup.)
%
If $\ker(e)\not\sub\coker(e)$ and ${\coker(e)\not\sub\ker(e)}$ both hold, then the square is NT-reducing.
\end{rem}


