\subsection[Generators with label $1$]{Generators with label \boldmath{$1$}}
\label{ss:lab1}


We now prove a sequence of results involving the labels introduced in Subsection \ref{ss:labs}.  We start with Lemma \ref{la:Tlab1}, which observes that all elements of the spanning tree $T(s)$ in \eqref{eq:Ts} have label $1$, and then build to Lemma~\ref{la:Upres}, which says that we can add the relations $a_e=1$ to the presentation $\presn(T(s))$ for \emph{many} more idempotents $e$ with label~$\lam(e)=1$.


\begin{lemma}
\label{la:Tlab1}
All the idempotents in the spanning tree $T(s)$ have label $1$.
\end{lemma}

\begin{proof}
Consider an arbitrary $e\in T(s)$. We split the proof into several cases, depending on the form of $e$,
as indicated in \eqref{eq:Ts}.
\medskip

\noindent
\textit{Case 1: $e=e_{V, \mapC(V)}\in \Tlex$, where $V=\{V_1,\ldots,V_r\}$ is a partition of $[n]$ with $r$ blocks.} Letting $v_k=\min(V_k)$ for $k\in [r]$, we have 
$e
=\begin{partn}{3} V_1 & \cdots & V_r \\ \hhline{~|~|~} v_1 & \cdots & v_r\end{partn}$
(omitting the trivial blocks)
so that
$\lamp(e)=\trans{v_1&\cdots&v_r}{v_1&\cdots & v_r}$, and  hence
$\lam(e)=\trans{1&\cdots&r}{1&\cdots & r}$.
\medskip


\noindent
\textit{Case 2: $e=e_{\mapV(C), C} \in \Tlex$, where $C=\{c_1<\cdots<c_r\}\subseteq [n]$.}
In this case we have
\[
e=\begin{partn}{5} [1,c_1] & (c_1,c_2] & \cdots & (c_{r-2},c_{r-1}] & (c_{r-1},n] \\ \hhline{~|~|~|~|~} c_1 & c_2&\cdots &c_{r-1} &c_r\end{partn},
\]
so that
$\lamp(e)=\trans{1&c_1+1&\cdots&c_{r-2}+1&c_{r-1}+1}{c_1&c_2&\cdots&c_{r-1} & c_r}$, and  hence
$\lam(e)=\trans{1&\cdots&r}{1&\cdots & r}$.
\medskip


\noindent
\textit{Case 3: $e=e_p$, where $p\in P_k$ for some $1\leq k\leq n-r-1$.} With notation as in \eqref{eq:ep}, let $a_k:=\min(A_k)$ for $1\leq k\leq r$, and note that $\min(A_1\cup B_1\cup\cdots\cup B_k)=1$.  It follows that $\lamp(e)=\trans{1&a_2&\cdots&a_{r}}{a_1&a_2&\cdots& a_r}$, and hence $\lam(e)=\trans{1&\cdots&r}{1&\cdots & r}$.
\medskip


\noindent
\textit{Case 4: $e\in \Tfc$.}
This case follows from Cases 1--3, using Lemma \ref{la:lamprops}\ref{it:lp2}.
\medskip

\noindent
\textit{Case 5: $e=s$.}
This follows from Lemma \ref{la:lamprops}\ref{it:lp1}.
\end{proof}

In what follows we will in fact want to work with a set of relations that is larger than~$\rels_1(T(s))$,
and we now work towards enabling that. We begin by identifying certain sets of idempotents:
\begin{nitemize}
\item
$\labU_\fd=\labU_\fd (n,r):= \bigl\{e\in E(n,r)\colon \lambda(e)=1 \text{ and }
\NTu(e)=0<\NTd(e)\bigr\}$ -- the set of full-domain, non-projection idempotents with label $1$;
\item
$\labU_\fc=\labU_\fc (n,r):= \bigl\{e\in E(n,r)\colon \lambda(e)=1 \text{ and }
\NTd(e)=0<\NTu(e)\bigr\}$ -- the set of full-codomain, non-projection idempotents with label $1$;
\item
$\labU=\labU(n,r):=\labU_\fd(n,r)\cup\labU_\fc(n,r)$.
\end{nitemize}
Lemma \ref{la:Tlexpres} says that the maximal subgroup $\GI$ under consideration is defined by the presentation $\presn(T(s))$.
Shortly we are going to see that the presentation $\presn(T(s))$ is equivalent to $\presn(\labU\cup\{s\})$, so that $\GI$ also has presentation $\presn(\labU\cup\{s\})$.
In fact, much of what we will prove does not use the defining relation $a_s=1$, and 
we will prefer to work with the slightly smaller presentation $\presn(\labU)$.  This is to facilitate the inductive proofs of Lemmas \ref{la:P1nr} and \ref{la:P0nr} below; see Remark \ref{rem:presnUlab}.
The group defined by $\presn(\labU)$ is typically not isomorphic to $\GI$, but only a homomorphic preimage of it.  






\newpage


\begin{lemma}
\label{la:eqlabel}
Let $e,f\in E(n,r)$ be any non-projection idempotents with full domain.
\begin{thmenumerate}
\item
\label{it:eql1}
If $\lam(e)=\lam(f)$ then $a_e=a_f$ is a consequence of $\presn(\Tfd)$.
\item
\label{it:eql2}
If $\lambda(e)=1$ then $a_e=1$ is a consequence of $\presn(\Tfd)$.
\end{thmenumerate}
\end{lemma}

\begin{proof}
\ref{it:eql1} 
By Lemma \ref{la:fdtoTn}, there exist idempotent transformations $e',f'\in E^\T(n,r)$ such that $\lam(e')=\lam(e)$ and $\lam(f')=\lam(f)$,
and such that the relations $a_e=a_{e'}$ and $a_f=a_{f'}$ are consequences of $\presn(\Tfd)$.
The relation $a_{e'}=a_{f'}$ is a consequence of $\presn(\Tfd)$ by Lemma \ref{la:GRtransl}\ref{it:GRt2}.

\ref{it:eql2} 
This follows from \ref{it:eql1}, keeping in mind Lemma \ref{la:Tlab1}.
\end{proof}


Lemma \ref{la:eqlabel} has an obvious dual, which we state without proof:


\begin{lemma}
\label{la:eqlabeldual}
Let $e,f\in E(n,r)$ be any non-projection idempotents with full codomain.
\begin{thmenumerate}
\item
\label{it:eql1*}
If $\lam(e)=\lam(f)$ then $a_e=a_f$ is a consequence of $\presn(\Tfc)$.
\item
\label{it:eql2*}
If $\lambda(e)=1$ then $a_e=1$ is a consequence of $\presn(\Tfc)$. \qed
\end{thmenumerate}
\end{lemma}

We can now achieve our above-mentioned goal:

\begin{lemma}
\label{la:Upres}
For any $1\leq r\leq n-2$, and any $s\in P_0(n,r)$, the group $\GI$ is defined by the presentation
\[
\presn(\labU\cup\{s\})=\bigl\langle A(n,r)\mid \rels_1(\labU\cup\{s\}),\ \rels_\subSq(n,r)\bigr\rangle.
\]
In other words $\GI\cong \sfG(\labU\cup\{s\})$.
\end{lemma}

\begin{proof}
By Lemma \ref{la:Tlexpres}, the group $\GI$ is defined by the presentation $\presn(T(s))$.
By Lemmas~\ref{la:eqlabel}\ref{it:eql2} and~\ref{la:eqlabeldual}\ref{it:eql2*}, all the relations~$\rels_1(\labU) = \rels_1(\labU_\fd \cup \labU_\fc)$ can be added to $\presn(T(s))$.
Since ${T(s)\subseteq \labU\cup \{s\}}$ by Lemma \ref{la:Tlab1}, it follows that the resulting presentation
is precisely ${\presn(\labU\cup \{s\})}$.
\end{proof}

\begin{rem}
In the group $\sfG(\labU\cup\{s\})$, we of course have $a_s=1$, for the fixed projection~${s\in P_0}$.  For the other projections $p\in P_0\setminus\{s\}$, it is not clear at this stage that we necessarily have $a_p=1$ in $\sfG(\labU\cup\{s\})$, but this is indeed the case.  It takes a lot more work to prove this, but we eventually will in Lemma \ref{la:P0nr1}.
\end{rem}


\subsection[Generators corresponding to projections from $P_1(n,r)$]{Generators corresponding to projections from \boldmath{$P_1(n,r)$}}
\label{ss:eP1}

Our next task is to show that all the generators corresponding to projections from $P_1(n,r)$ are equal to each other as a consequence of our defining relations.  This is achieved in Lemma \ref{la:P1nr} below.  The proof of this lemma is inductive, based on the case $r=n-2$, which is dealt with in Lemma \ref{la:P1rr2}.  By the nature of the induction (see Remark \ref{rem:presnUlab}), we are forced to omit the relation $a_s=1$ (for the fixed projection $s\in P_0$), and work with the group~$\sfG(\labU)$, where $\labU = \labU(n,r)$ was constructed in the previous subsection.  In order that we can conveniently vary our parameters, we denote this group by $\Ghat(n,r) = \sfG(\labU) = \sfG(\labU(n,r))$.   It is worth noting that~$O$ contains $T_\fd\cup T_\fc$; indeed, the elements of the latter set are non-projections by definition, and they have label $1$ by Lemma \ref{la:Tlab1}.


