\begin{lemma}
\label{la:P1pq1}
Suppose $1\leq r= n-2$, let $i,j,k\in [n]$ be distinct, let $Y:=[n]\setminus \{i,j,k\}$, and let
\[
p:=\begin{partn}{2} i &j,k\\ \hhline{~|-}  i & j,k\end{partn}\oplus \id_Y \ANd
q:=\begin{partn}{2} i,j&k\\ \hhline{~|-}  i,j & k\end{partn}\oplus \id_Y.
\]
If $i\leq j+1$ then $a_p=a_q$  in $\Ghat(n,r)$.
\end{lemma}

\begin{proof}
Consider the following further idempotents:
\begin{align*}
e& := \begin{partn}{3} i & j&k \\ \hhline{~|-|-} i & \multicolumn{2}{c}{j,k}\end{partn}\oplus \id_Y, &
e_1&:=\begin{partn}{3} i&j&k\\ \hhline{~|-|-} i,j&\multicolumn{2}{c}{k}\end{partn}\oplus \id_Y, &
f&= \begin{partn}{2} i,k&j\\ \hhline{~|-} i&j,k\end{partn}\oplus \id_Y,&
f_1&= \begin{partn}{2} i,k&j\\ \hhline{~|-} i,j&k\end{partn}\oplus \id_Y,
\\
g& := \begin{partn}{2} i,j,k  & \\ \hhline{~|-} i & j,k\end{partn}\oplus \id_Y, &
g_1&:=\begin{partn}{2} i,j,k&\\ \hhline{~|-} i,j&k\end{partn}\oplus \id_Y, &
h&= \begin{partn}{3} i&j&k\\ \hhline{~|-|-} i,j,k&\multicolumn{2}{c}{}\end{partn}\oplus \id_Y,&
h_1&= \begin{partn}{2} i&j,k\\ \hhline{~|-} i,j,k&\end{partn}\oplus \id_Y.
\end{align*}
It is routine to verify that:
\begin{alignat}{5}
\label{eq:P1pq11}
&\smat{e}{e_1}{f}{f_1} &\ &\text{is LR-singularised by}
&\ &u=\begin{partn}{3} i&j&k\\ \hhline{~|-|~} i,j& &k\end{partn}\oplus\id_Y, &\ \text{ yielding}
&\quad&a_e^{-1}a_{e_1}=a_f^{-1}a_{f_1};
\\
\label{eq:P1pq12}
&\smat{f}{f_1}{g}{g_1} &&\text{is LR-singularised by}
&&v=\begin{partn}{3} i,k&j&\\ \hhline{~|~|-} i&j& k\end{partn}\oplus\id_Y,&\text{ yielding}
&&a_f^{-1}a_{f_1}=a_g^{-1}a_{g_1};
\\
\label{eq:P1pq13}
&\smat{e}{h}{p}{h_1} && \text{is UD-singularised by}
&&w= \begin{partn}{2} i&j,k\\ \hhline{~|~} i& j,k\end{partn}\oplus\id_Y,&\text{ yielding}
&&a_e^{-1}a_h=a_p^{-1}a_{h_1}.
\end{alignat}
These squares are illustrated in Figure \ref{fig:P1pq1}.  Using Lemma \ref{la:consec} and $i\leq j+1$, we see that the full-domain idempotents $g$ and $g_1$ have equal labels, and hence we have
\begin{equation}
\label{eq:P1pq14}
a_g=a_{g_1}
\end{equation}
by Lemma \ref{la:eqlabel}. Analogously, Lemma \ref{la:eqlabeldual} gives
\begin{equation}
\label{eq:P1pq15}
a_h=a_{h_1}.
\end{equation}
Finally, by Lemma \ref{la:P1ep1} we have
\begin{equation}
\label{eq:P1pq16}
a_{e_1}=a_q.
\end{equation}
Putting all this together we obtain
\[
a_p   \stackrel{\text{\tiny\eqref{eq:P1pq13}}}{=}    a_{h_1}a_h^{-1}a_e 
\stackrel{\text{\tiny\eqref{eq:P1pq15}}}{=}a_e 
\stackrel{\text{\tiny\eqref{eq:P1pq11}}}{=} a_{e_1}a_{f_1}^{-1}a_f
\stackrel{\text{\tiny\eqref{eq:P1pq16}}}{=}a_q a_{f_1}^{-1}a_f
\stackrel{\text{\tiny\eqref{eq:P1pq12}}}{=}a_q a_{g_1}^{-1}a_g  
\stackrel{\text{\tiny\eqref{eq:P1pq14}}}{=}a_q,
\]
as required.
\end{proof}


