Our next lemma establishes equalities between generators corresponding to natural families of projections.
%
Still supposing $r=n-2$, for any $i,j\in [n]$ with $i<j$ denote by $\sfp(i,j)$ the unique projection in $P_1 = P_1(n,n-2)$ with the upper block $\{i,j\}$.





\begin{lemma}
\label{la:P1pq23}
Suppose $1\leq r= n-2$, and let $i,j\in [n]$ with $i<j$. 
\begin{thmenumerate}
\item
\label{it:pq231}
If $i+1<j$ then $a_{\sfp(i,j)}=a_{\sfp(i+1,j)}$  in $\Ghat(n,r)$.
\item
\label{it:pq232}
If $j<n$ then $a_{\sfp(i,j)}=a_{\sfp(i,j+1)}$  in $\Ghat(n,r)$.
\end{thmenumerate}
\end{lemma}

\begin{proof}
\ref{it:pq231}
Let $q:=\begin{partn}{2} i,i+1 & j \\ \hhline{~|-} i,i+1 & j\end{partn}\oplus \id_Y$, with $Y:=[n]\setminus\{i,i+1,j\}$.
Applying Lemma \ref{la:P1pq1}, with the role of the triple $(i,j,k)$ played by $(i+1,i,j)$, yields the relation $a_{\sfp(i,j)}=a_q$.
Likewise, the same lemma, but with the role of $(i,j,k)$ played by $(i,i+1,j)$, yields
$a_{\sfp(i+1,j)}=a_q$. Combining these two relations yields $a_{\sfp(i,j)}=a_{\sfp(i+1,j)}$.

\ref{it:pq232}
Analogous reasoning to part \ref{it:pq231}, with $q:= \begin{partn}{2} j,j+1 & i\\ \hhline{~|-} j,j+1 & i\end{partn}\oplus \id_Y$ for $Y:= [n]\setminus \{ i,j,j+1\}$, yields $a_{\sfp(i,j)}=a_q=a_{\sfp(i,j+1)}$.
\end{proof}



We can now complete our objective for $r=n-2$:

\begin{lemma}
\label{la:P1rr2}
 Suppose $1\leq r= n-2$. 
For arbitrary $p,q\in P_1(n,r)$,
we have $a_p=a_q$  in~$\Ghat(n,r)$. 
\end{lemma}

\begin{proof}
Any projection in $P_1$ satisfies precisely one of the following:
 either (1) all its transversals have size $2$; or else (2) there exists a single transversal of size $4$. 
 By Lemma \ref{la:P1pq1} every generator corresponding to a projection satisfying (2) is equal to a generator corresponding to a projection satisfying (1). So we may assume without loss of generality that both $p$ and $q$ satisfy (1).
 We can therefore write $p=\sfp(i,j)$ for some $i<j$.  
 By Lemma \ref{la:P1pq23} we have
 \[
a_p=a_{\sfp(i,j)}=a_{\sfp(i,j+1)}=\cdots=a_{\sfp(i,n)}=a_{\sfp(i+1,n)}=\cdots=a_{\sfp(n-1,n)}.
 \]
 Analogously, $a_q=a_{\sfp(n-1,n)}$, and hence $a_p=a_q$, as required.
\end{proof}




Now that we have dealt with $r=n-2$, we move on to the general case:


\begin{lemma}
\label{la:P1nr}
 Suppose $1\leq r\leq n-2$. 
For arbitrary $p,q\in P_1(n,r)$,
we have $a_p=a_q$ in~$\Ghat(n,r)$.  
\end{lemma}


\begin{proof}
We fix $r\geq1$, and prove the lemma by induction on $n\geq r+2$.  When $n=r+2$, the result is true by Lemma \ref{la:P1rr2}, so for the rest of the proof we assume that $n\geq r+3$.

For $i,j\in [n]$ with $i\neq j$ denote by $\P_n^{i,j}$ the set of all partitions $a\in\P_n$ such that $(i,j)\in \ker (a)$
and $(i,j)\in\coker(a)$.
This is a subsemigroup of $\P_n$ isomorphic to $\P_{n-1}$.

Recall that the group $\Ghat(n,r)$ is defined by the generators $A(n,r)$ and the defining relations 
$\rels_1(\labU(n,r))$ and $\rels_\subSq(n,r)$.
Furthermore, recall that $\labU(n,r)$ consists of all non-projection idempotents in $D(n,r)$ with full domain or full codomain, and with label $1$. In particular, $\labU(n,r)$ contains all the idempotents belonging to $\P_n^{i,j}$ with the above properties.
Likewise, $\rels_\subSq(n,r)$ contains all the relations arising from singular squares that lie entirely in $\P_n^{i,j}$.
In this way, we see that the presentation $\langle A(n,r)\mid \rels_1(\labU(n,r)),\ \rels_\subSq(n,r)\rangle$ contains as a sub-presentation a natural copy of the presentation
$\langle A(n-1,r)\mid \rels_1(\labU(n-1,r)),\ \rels_\subSq(n-1,r)\rangle$ corresponding to~$\P_n^{i,j}$.
Thus, if the projections $p$ and $q$ belong to some common $\P_n^{i,j}$ we conclude that $a_p=a_q$ in~$\Ghat(n,r)$ by induction.

Now consider arbitrary $p,q\in P_1$, and fix $(i,j)\in\ker(p)$ and $(k,l)\in\ker(q)$ with $i\neq j$ and~$k\neq l$.
Note that all elements of $P_1$ have non-trivial kernel, and also that we do not require $\{i,j\}$ and $\{k,l\}$ to be disjoint.
Since $r\leq n-3$ there exists $u\in P_1$ such that $(i,j),(k,l)\in \ker(u)$.
But then $p,u\in \P_n^{i,j}$ and $u,q\in\P_n^{k,l}$. Using the observation from the previous paragraph we have
$a_p=a_u=a_q$, completing the proof.
\end{proof}




\begin{rem}\label{rem:presnUlab}
The fact that we were working with the groups $\Ghat(n,r)$, which do not depend on the choice of projection $s\in P_0$, is crucial for the validity of the inductive argument in our proof of Lemma \ref{la:P1nr}. Indeed, if we worked with the set $O\cup\{s\}$, we would not be able to perform the inductive step, since $s$ certainly would not be contained in all $\P_n^{i,j}$.  The same is true of the proof of Lemma \ref{la:P0nr} below.
\end{rem}



\subsection[Generators corresponding to projections from $P_0(n,r)$]{Generators corresponding to projections from \boldmath{$P_0(n,r)$}}
\label{ss:eP0}


We now want to do the same for generators corresponding to projections from $P_0(n,r)$, i.e.~show they are all equal to each other as a consequence of the defining relations. We will again need to work within the group $\Ghat = \Ghat(n,r) = \sfG(\labU)$; however, once the relation $a_s=1$ is brought back in (for a fixed projection $s\in P_0(n,r)$), the conclusion will be that all these generators are in fact equal to $1$.  As before, we begin with the case $r=n-2$.
%
If $n=3$ (and $r=1=n-2$) then $|P_0|=1$, and Lemmas \ref{la:P0pq1}, \ref{la:P0pq23} and \ref{la:P0rr2} are vacuously true in this case.

\begin{lemma}
\label{la:P0pq1}
Suppose $1\leq r= n-2$, let $i,j,k,l\in [n]$ be distinct, let $Y:=[n]\setminus \{i,j,k,l\}$, and let
\[
p:=\begin{partn}{2} i,j,k&l\\ \hhline{~|~}  i,j,k & l\end{partn}\oplus \id_Y \ANd
q:=\begin{partn}{2} i,j &k,l\\ \hhline{~|~}  i,j & k,l\end{partn}\oplus \id_Y.
\]
If $i,l\leq k+1$ then $a_p=a_q$  in $\Ghat(n,r)$.
\end{lemma}

\begin{proof}
Consider the following further idempotents:
\begin{align*}
e& := \begin{partn}{4} i & j&k&l \\ \hhline{~|-|-|~} i,k & \multicolumn{2}{c|}{j} & l\end{partn}\oplus \id_Y, &
f&:=\begin{partn}{4} i&j&k&l\\ \hhline{~|-|-|~} i & \multicolumn{2}{c|}{j} & k,l \end{partn}\oplus \id_Y, &
g_1& := \begin{partn}{3} i,j&k&l   \\ \hhline{~|-|~} i,j,k& &l\end{partn}\oplus \id_Y, &
h_1&= \begin{partn}{3} i,j&k&l\\ \hhline{~|-|~} i,j&&k,l\end{partn}\oplus \id_Y,&
\\
g&= \begin{partn}{3} i,j&k&l\\ \hhline{~|-|~} i,k&j&l\end{partn}\oplus \id_Y,&
h& := \begin{partn}{3} i,j&k&l   \\ \hhline{~|-|~} i & j&k,l\end{partn}\oplus \id_Y, &
g_2&:=\begin{partn}{3} i,j,k&&l\\ \hhline{~|-|~} i,k&j&l\end{partn}\oplus \id_Y, &
h_2&= \begin{partn}{3} i,j&&k,l\\ \hhline{~|-|~} i&j&k,l\end{partn}\oplus \id_Y.
\end{align*}
Then:
\begin{alignat}{5}
\label{eq:P0pq11}
&\smat{e}{f}{g}{h} &\ &\text{is LR-singularised by}
&\ &u=\begin{partn}{4} i&j&k&l\\ \hhline{~|~|-|~} i&j&& k,l\end{partn}\oplus\id_Y,&\ \text{ yielding}
&\quad&a_e^{-1}a_{f}=a_g^{-1}a_{h};
\\
\label{eq:P0pq12}
&\smat{g}{g_1}{g_2}{p} &&\text{is LR-singularised by}
&&v=\begin{partn}{3} i,j&k&l\\ \hhline{~|~|~} i,j&k& l\end{partn}\oplus\id_Y,&\text{ yielding}
&&a_g^{-1}a_{g_1}=a_{g_2}^{-1}a_{p};
\\
\label{eq:P0pq13}
&\smat{h}{h_1}{h_2}{q} &&\text{is LR-singularised by}
&&w=\begin{partn}{3} i,j&k&l\\ \hhline{~|~|~} i,j&k& l\end{partn}\oplus\id_Y,&\text{ yielding}
&&a_h^{-1}a_{h_1}=a_{h_2}^{-1}a_{q}.
\end{alignat}
These squares are illustrated in Figure \ref{fig:P0pq1}.
By Lemma \ref{la:P1ep1}, we have $a_e=a_{e'}$, where
$e'=\begin{partn}{3} i,k&j&l\\ \hhline{~|-|~} i,k&j&l\end{partn}\oplus\id_Y$,
and also 
$a_f=a_{f'}$, where
$f'=\begin{partn}{3} i&j&k,l\\ \hhline{~|-|~} i&j&k,l\end{partn}\oplus\id_Y$.
Note that $e',f'\in P_1$, so that $a_{e'}=a_{f'}$ by Lemma \ref{la:P1nr}.
Hence $a_e=a_f$, and combining with \eqref{eq:P0pq11} yields $a_g=a_h$.

Combining this last conclusion with \eqref{eq:P0pq12} and \eqref{eq:P0pq13} yields
\[
a_{g_1}a_p^{-1}a_{g_2}=a_g=a_h=a_{h_1}a_q^{-1} a_{h_2}.
\]
The desired relation $a_p=a_q$ will follow if we manage to show that
$a_{g_1}=a_{h_1}$ and $a_{g_2}=a_{h_2}$.
In fact, by Lemmas  \ref{la:eqlabeldual} and \ref{la:eqlabel}, it suffices to show that $\lambda(g_i)=\lambda(h_i)$ for $i=1,2$.


Again writing $x\wedge y$ for $\min(x,y)$, we have
\begin{alignat*}{2}
\lamp (g_1)&= \trans{i\wedge j & l}{i\wedge j\wedge k&l}\oplus\id_Y,&\quad
\lamp(g_2) & = \trans{i\wedge j\wedge k & l}{i\wedge k&l}\oplus\id_Y,
\\
\lamp(h_1) &=  \trans{i\wedge j & l}{i\wedge j &k\wedge l}\oplus\id_Y,&
\lamp(h_2) & = \trans{i\wedge j & k\wedge l}{i&k\wedge l}\oplus\id_Y.
\end{alignat*}
Since $i\leq k+1$, the values $i\wedge j\wedge k$ and $i\wedge j$ are either equal or consecutive.
Likewise, $l$ and $k\wedge l$ are either equal or consecutive.
Furthermore, not both pairs can be consecutive, as this would imply that
$i=k+1=l$.
It again follows from Lemma \ref{la:consec} that $\lam(g_1)=\lam(h_1)$.
We obtain $\lam(g_2)=\lam(h_2)$ analogously, and this completes the proof of the lemma.
\end{proof}



