Still supposing $r=n-2$, for any $i,j,k\in [n]$ with $i<j<k$ denote by $\sfp(i,j,k)$ the unique projection in $P_0$ with transversal $\{i,j,k,i',j',k'\}$.  







\begin{lemma}
\label{la:P0pq23}
Suppose $1\leq r= n-2$, and let $i,j,k\in [n]$ with $i<j<k$. 
\begin{thmenumerate}
\item
\label{it:pq0231}
If $i+1<j$ then $a_{\sfp(i,j,k)}=a_{\sfp(i+1,j,k)}$  in $\Ghat(n,r)$.
\item
\label{it:pq0232}
If $j+1<k$ then $a_{\sfp(i,j,k)}=a_{\sfp(i,j+1,k)}$  in $\Ghat(n,r)$.
\item
\label{it:pq0233}
If $k <n$ then $a_{\sfp(i,j,k)}=a_{\sfp(i,j,k+1)}$  in $\Ghat(n,r)$.
\end{thmenumerate}
\end{lemma}

\begin{proof}
The proof is analogous to the proof of Lemma \ref{la:P1pq23}, but using Lemma \ref{la:P0pq1} instead of Lemma \ref{la:P1pq1}.
Thus for \ref{it:pq0231} we let 
$q:=\begin{partn}{2} i,k & i+1,j\\ \hhline{~|~} i,k & i+1,j    \end{partn}\oplus\id_Y$,
where $Y:=[n]\setminus\{i,i+1,j,k\}$,
and then apply Lemma \ref{la:P0pq1} twice to obtain $a_{\sfp(i,j,k)}=a_q=a_{\sfp(i+1,j,k)}$.
The intermediate partitions to use in proving \ref{it:pq0232} and \ref{it:pq0233}
are
$\begin{partn}{2} i,k & j,j+1\\ \hhline{~|~} i,k & j,j+1    \end{partn}\oplus\id_Y$ and
$\begin{partn}{2} i,j & k,k+1\\ \hhline{~|~} i,j & k,k+1    \end{partn}\oplus\id_Y$
(for appropriate $Y$), respectively.
\end{proof}








\begin{lemma}\label{la:P0rr2}
Suppose $1\leq r= n-2$.  For arbitrary $p,q\in P_0(n,r)$, we have $a_p=a_q$ in~$\Ghat(n,r)$. 
\end{lemma}

\begin{proof}
The proof is analogous to the proof of Lemma \ref{la:P1rr2}.
Lemma \ref{la:P0pq1} enables us to assume without loss of generality that $p$ and $q$ have a transversal of size $6$.
We can therefore write $p=\sfp(i,j,k)$ for some $i<j<k$.  
By Lemma \ref{la:P0pq23} we have
\begin{align*}
a_p=a_{\sfp(i,j,k)}=a_{\sfp(i,j,k+1)}=\cdots=a_{\sfp(i,j,n)}=a_{\sfp(i,j+1,n)}=\cdots&=a_{\sfp(i,n-1,n)}\\
&=a_{\sfp(i+1,n-1,n)}=\cdots=a_{\sfp(n-2,n-1,n)}.
\end{align*}
Analogously, $a_q=a_{\sfp(n-2,n-1,n)}$, and hence $a_p=a_q$.
\end{proof}




\begin{lemma}\label{la:P0nr}
Suppose $1\leq r\leq n-2$.  For arbitrary $p,q\in P_0(n,r)$, we have $a_p=a_q$  in~$\Ghat(n,r)$.  
\end{lemma}


\begin{proof}
This is exactly the same as the proof of Lemma \ref{la:P1nr}, except that Lemma \ref{la:P0rr2} is used in place of Lemma \ref{la:P1rr2} when dealing with the case $r= n-2$.
\end{proof}

Thus, as soon as we add to $\Ghat(n,r) = \sfG(\labU)$ a relation equating any generator corresponding to a projection from $P_0$ to $1$, all such generators are equal to $1$:

\begin{lemma}\label{la:P0nr1}
Suppose $1\leq r\leq n-2$, and let $s\in P_0(n,r)$ be arbitrary.  Then for every $p\in P_0(n,r)$ we have $a_p=1$  in~$\sfG(O\cup\{s\})$.  \qed
\end{lemma}






\subsection{Coxeter idempotents}
\label{ss:glt}



As our next step, we now move on to the generators~$a_e$ corresponding to full-domain/codomain Coxeter idempotents $e\in E(n,r)$, i.e.~those for which $\lam(e) = (i,i+1)$ is a Coxeter transposition.  The significance of these elements is that:
\bit
\item any generator of $\GI$ corresponding to a full-domain non-projection idempotent is a product of generators corresponding to full-domain Coxeter idempotents (see Lemmas \ref{la:GRtransl} and \ref{la:fdtoTn}), and
\item the generators corresponding to full-domain Coxeter idempotents satisfy the defining (Coxeter) relations of $\S_r$ (see \cite[Lemmas 8.1--8.3]{GR12IJM}).
\eit
Together with the dual statements concerning full-\emph{co}domain Coxeter idempotents (and additional arguments provided later in this section), it will follow that the full-domain and full-codomain idempotents lead to two copies of $\S_r$ in our group $\GI$.  The next lemma is pivotal, and will be used to show that in fact these copies of $\S_r$ coincide.  We also bring the relation $a_s=1$ back in, where $s$ is our fixed projection from~$P_0(n,r)$.


\begin{lemma}
\label{la:lab12}
Suppose $1\leq r\leq n-2$, and let $s\in P_0(n,r)$ be arbitrary.
Let $e,f\in E(n,r)$ be such that $e$ is full-domain, $f$ is full-codomain, and $\lambda(e)=\lambda(f)=(i ,  i+1)$ for some $1\leq i\leq r-1$.  Then $a_e=a_f$  in $\sfG(\labU\cup\{s\})$.
\end{lemma}

\begin{proof}
The result is vacuous for $r= 1$, so we assume that $r\geq2$, which also implies $n\geq4$.
During the proof, for a partition $g \in \P_{[i,i+3]}$, we write $g^+\in\P_n$ for the following:
\bit
\item If $r\geq3$, then $g^+ = g \oplus \id_\sigma$, where $\sigma$ is the equivalence on $[n]\setminus [i,i+3]$ with classes
\[
\{1\},\ldots,\{i-1\}, \{i+4\},\ldots,\{r+1\},[r+2,n].
\]
\item If $r=2$ (and so $i=1$), then $g^+$ is obtained by adding $i+4,\ldots,n$ to the block of $g$ containing $i+3$, and adding $(i+4)',\ldots,n'$ to the block of $g$ containing $(i+3)'$.
\eit
With this notation in place, it follows from Lemmas \ref{la:eqlabel} and \ref{la:eqlabeldual} that we can prove the current lemma for the specific choices
\[
e= \begin{partn}{3} i,i+2,i+3 && i+1 \\ \hhline{~|-|~} i+2,i+3 & i & i+1\end{partn}^{\!\!+} \ANd
f= \begin{partn}{3} i,i+2 & i+3 & i+1  \\ \hhline{-|~|~} & i,i+2,i+3 &i+1 \end{partn}^{\!\!+}.
\]
We proceed via a series of claims as follows.  Each involves certain idempotents $g_i$, whose meanings are fixed throughout.  The elements constructed during the proofs are temporary, however, and we will re-use their names ($h_i$ and $u$).  Also, $t$ will denote some arbitrary but fixed projection from $P_1=P_1(n,r)$.
The singular squares we use in the proofs of the claims are shown in Figure~\ref{fig:lab12}.  Some of these are instances of the square from Lemma \ref{la:ehrsq} (or its dual), but for convenience we will provide a singularising element in each case.

