\begin{claim}
\label{cl:lab121}
For 
$g_1:=\begin{partn}{4} \multicolumn{2}{c|}{i,i+2} & i+1 & i+3  \\ \hhline{-|-|~|~} i & i+2 & i+1 & i+3 \end{partn}^{\!\!+}$
we have $a_{g_1}=a_t$.
\end{claim}

\begin{proof}
Consider the square $\smat{g_1}{h_1}{h_2}{h_3}$, where
\[
h_1:=\begin{partn}{3} i,i+2&i+1&i+3 \\ \hhline{-|~|~} i,i+2&i+1&i+3\end{partn}^{\!\!+},\quad
h_2:=\begin{partn}{4} i,i+1,i+2&\multicolumn{2}{c|}{}&i+3 \\ \hhline{~|-|-|~} i+1&i&i+2&i+3 \end{partn}^{\!\!+}\ANd
h_3:=\begin{partn}{3} i,i+1,i+2&&i+3 \\ \hhline{~|-|~} i+1  &i,i+2& i+3\end{partn}^{\!\!+}.
\]
It is easy to verify that it is LR-singularised by
$u=\begin{partn}{3} i,i+2&i+1&i+3\\ \hhline{~|~|~} i,i+2&i+1&i+3\end{partn}^{\!\!+}$.
As $h_1\in P_1$ we have $a_{h_1}=a_t$ by Lemma \ref{la:P1nr}.
The idempotents $h_2$ and $h_3$ have full domain and label $1$, and hence $a_{h_2}=a_{h_3}=1$ by Lemma \ref{la:eqlabel}.
The square relation $a_{g_1}^{-1}a_{h_1}=a_{h_2}^{-1}a_{h_3}$ now implies
$a_{g_1}=a_{h_1}=a_t$, as required.
\end{proof}


\begin{claim}
\label{cl:lab122}
For 
$g_2:=\begin{partn}{4} i&i+1&i+2&i+3 \\ \hhline{-|~|-|~} i & i+1 & &i+2, i+3\end{partn}^{\!\!+}$
we have $a_{g_2}=a_t$.
\end{claim}

\begin{proof}
The square $\smat{g_2}{h_1}{h_2}{h_3}$, where
\[
h_1:=\begin{partn}{4} i&i+1&i+2&i+3 \\ \hhline{-|~|-|~} &i+1&&i,i+2,i+3\end{partn}^{\!\!+},\quad
h_2:=\begin{partn}{3} i&i+1&i+2,i+3\\ \hhline{-|~|~}  i&i+1&i+2,i+3 \end{partn}^{\!\!+}\ANd
h_3:=\begin{partn}{3} i&i+1&i+2,i+3 \\ \hhline{~|~|-}  & i+1 &i,i+2,i+3\end{partn}^{\!\!+}.
\]
is LR-singularised by
$u=\begin{partn}{4} i&i+1&i+2&i+3\\ \hhline{-|~|~|~} &i+1&i,i+2&i+3 \end{partn}^{\!\!+}$.
We have $a_{h_2}=a_t$ by Lemma \ref{la:P1nr} since $h_2\in P_1$.
The idempotents $h_1$ and $h_3$ are full-codomain, and both have label $(i ,  i+1)$; hence $a_{h_1}=a_{h_3}$ by Lemma \ref{la:eqlabeldual}.
The square relation now implies
$a_{g_2}=a_{h_2}=a_t$, as required.
\end{proof}


\begin{claim}
\label{cl:lab123}
For 
$g_3:=\begin{partn}{4} i,i+1&\multicolumn{2}{c|}{i+2}&i+3 \\ \hhline{~|-|-|~} i +1& i & i+2& i+3\end{partn}^{\!\!+}$
we have $a_{g_3}=a_t$.
\end{claim}

\begin{proof}
The proof is analogous to the previous two claims.
The square  is $\smat{g_3}{h_1}{h_2}{h_3}$, where
\[
h_1:=\begin{partn}{3} i,i+1&i+2&i+3 \\ \hhline{~|-|~} i,i+1&i+2&i+3\end{partn}^{\!\!+},\quad
h_2:=\begin{partn}{4} i,i+1,i+2&\multicolumn{2}{c|}{}&i+3\\ \hhline{~|-|-|~}  i+1&i&i+2&i+3 \end{partn}^{\!\!+}\ANd
h_3:=\begin{partn}{3} i,i+1,i+2&&i+3 \\ \hhline{~|-|~}  i,i+1&i+2&i+3\end{partn}^{\!\!+}.
\]
The UD-singularising idempotent is
$u=\begin{partn}{4} i&i+1,i+2&&i+3\\ \hhline{~|~|-|~} i&i+1&i+2&i+3 \end{partn}^{\!\!+}$.
This time $h_1$ belongs to $P_1$, while~$h_2$ and $h_3$ have full domain and label $1$.
\end{proof}




\begin{claim}
\label{cl:lab124}
For 
$g_4:=\begin{partn}{3} i,i+1&i+2&i+3 \\ \hhline{~|-|~}  i+1 &i& i+2, i+3\end{partn}^{\!\!+}$
we have $a_{g_4}=1$.
\end{claim}

\begin{proof}
This time the square is  $\smat{g_4}{h_1}{h_2}{h_3}$, where
\[
h_1:=\begin{partn}{3} i,i+1&i+2&i+3 \\ \hhline{~|-|~} i,i+1&&i+2,i+3\end{partn}^{\!\!+},\quad
h_2:=\begin{partn}{3} i,i+1&&i+2,i+3\\ \hhline{~|-|~}  i+1&i&i+2,i+3 \end{partn}^{\!\!+}\ANd
h_3:=\begin{partn}{2} i,i+1&i+2,i+3 \\ \hhline{~|~}  i,i+1&i+2,i+3\end{partn}^{\!\!+},
\]
and the LR-singularising idempotent is
$u=\begin{partn}{3} i,i+1&i+2&i+3\\ \hhline{~|~|~} i,i+1&i+2&i+3 \end{partn}^{\!\!+}$.
The idempotents $h_1$ and $h_2$ have full domain or codomain, and label $1$, so $a_{h_1}=a_{h_2}=1$.
The idempotent $h_3$ is a projection from $P_0$, so $a_{h_3}=1$ by Lemma \ref{la:P0nr1}.
Thus, the square relation gives $a_{g_4}=1$.
\end{proof}



\begin{claim}
\label{cl:lab125}
For 
$g_5:=\begin{partn}{4} i&i+1&i+2&i+3 \\ \hhline{-|~|-|~} i&i+1&i+2&i+3\end{partn}^{\!\!+}$
we have $a_{g_5}=a_t^2$.
\end{claim}

\begin{proof}
This time we have the square $\smat{g_5}{g_2}{g_3}{g_4}$,
where $g_2$, $g_3$ and $g_4$ were defined in Claims \ref{cl:lab122}--\ref{cl:lab124}.
The square is LR-singularised by 
$u=\begin{partn}{4} i&i+1&i+2&i+3\\ \hhline{~|~|-|~} i&i+1&&i+2,i+3 \end{partn}^{\!\!+}$.
Substituting the relations obtained in Claims \ref{cl:lab122}--\ref{cl:lab124}
into the square relation
$a_{g_5}^{-1}a_{g_2}=a_{g_3}^{-1}a_{g_4}$ yields $a_{g_5}=a_t^2$.
\end{proof}



\begin{claim}
\label{cl:lab126}
For 
$g_6:=\begin{partn}{3} i,i+2&i+1&i+3 \\ \hhline{-|~|~} i&i+1&i+2,i+3\end{partn}^{\!\!+}$
we have $a_{g_6}=1$.
\end{claim}

\begin{proof}
This time we have the square $\smat{g_6}{g_1}{g_2}{g_5}$,
where $g_1$, $g_2$ and $g_5$ were defined in Claims \ref{cl:lab121}, \ref{cl:lab122} and~\ref{cl:lab125}.
The square is UD-singularised by 
$u=\begin{partn}{4} i&i+1&i+2&i+3\\ \hhline{-|~|~|~} i&i+1&i+2&i+3\end{partn}^{\!\!+}$.
Substituting Claims \ref{cl:lab121}, \ref{cl:lab122} and \ref{cl:lab125}
into the square relation
$a_{g_6}^{-1}a_{g_1}=a_{g_2}^{-1}a_{g_5}$ yields $a_{g_6}=1$.
\end{proof}


\begin{claim}
\label{cl:lab127}
We have $a_e^{-1}=a_f$.
\end{claim}

\begin{proof}
This time we have the square $\smat e{h_1}{g_6}f$,
where
$h_1:=\begin{partn}{2} i,i+2,i+3&i+1 \\ \hhline{~|~} i,i+2,i+3&i+1\end{partn}^{\!\!+}$.
The square is LR-singularised by $u = \begin{partn}{3} i,i+2&i+1&i+3\\ \hhline{~|~|~} i,i+2&i+1&i+3\end{partn}^{\!\!+}$.
Since  $h_1\in P_0$ we have $a_{h_1}=1$ by Lemma \ref{la:P0nr1}, and
also $a_{g_6}=1$ by Claim~\ref{cl:lab126}.
The desired relation follows from the square relation $a_e^{-1}a_{h_1} = a_{g_6}^{-1}a_f$.
\end{proof}

To complete the proof of the lemma,
 let $e'\in E(n,r)$ be any idempotent full transformation with label $(i ,  i+1)$.
By Lemma \ref{la:eqlabel}\ref{it:eql1} we have $a_e=a_{e'}$. On the other hand, by Lemma \ref{la:GRtransl}\ref{it:GRt3} we have $a_{e'}^2=1$, and so $a_e^2=1$. Combining this with Claim \ref{cl:lab127} we deduce $a_e=a_e^{-1}=a_f$, as required.
\end{proof}
\setcounter{claim}{0}





\subsection{Commuting relations}
\label{ss:comm}

We now start moving towards identifying the group $\Z\times\S_r$.
It will turn out that the generators $a_e$ corresponding to full-domain or full-codomain idempotents $e$ will generate the symmetric group~$\S_r$, whereas those corresponding to $e\in P_1(n,r)$ -- which are mutually equal by Lemma~\ref{la:P1nr} -- will generate $\Z$. The key point in concluding that we indeed have a direct product is to establish commutation relations between the two families of generators.
%





\begin{lemma}
\label{la:peep}
Suppose $1\leq r\leq n-2$, and let $s\in P_0(n,r)$ be arbitrary.  Let $e\in E(n,r)$ be any idempotent with full domain and label $(i, i+1)$ for some $1\leq i\leq r-1$, and let $t\in P_1(n,r)$. Then $a_ea_t=a_ta_e$  in $\sfG(\labU\cup\{s\})$.
\end{lemma}


\begin{proof}
Again the result is vacuous for $r=1$, so we assume that $r\geq2$.  We also use the $g^+$ notation from the proof of Lemma \ref{la:lab12} for idempotents $g$ of $\P_{[i,i+3]}$.
%
By Lemma \ref{la:eqlabel} it is sufficient to show that $a_ea_t=a_ta_f$ holds for 
\[
e:= \begin{partn}{3}  i,i+3&&i+1,i+2\\ \hhline{~|-|~} i+3&i&i+1,i+2\end{partn}^{\!\!+} \ANd
f:= \begin{partn}{4} i,i+2,i+3&&i+1&\\ \hhline{~|-|~|-} i+3&i&i+1&i+2\end{partn}^{\!\!+}.
\]
Define some further idempotents:
\begin{alignat*}{4}
e_1&:= \begin{partn}{3} i,i+3&i+2&i+1 \\ \hhline{~|-|~} i+3&i&i+1,i+2\end{partn}^{\!\!+},\quad&
f_1&:= \begin{partn}{4} i,i+3&&i+1&i+2\\ \hhline{~|-|~|-} i+3&i&i+1&i+2\end{partn}^{\!\!+},\quad&
g_1&:= \begin{partn}{4} i&i+1&i+2&i+3\\ \hhline{-|~|-|~} i&i+1,i+2&&i+3\end{partn}^{\!\!+},
\\
e_2&:= \begin{partn}{3} i,i+3&i+1&i+2\\ \hhline{~|~|-} i,i+3&i+1,i+2&\end{partn}^{\!\!+},\quad&
f_2&:= \begin{partn}{3} i,i+3&i+1&i+2\\ \hhline{~|~|-} i,i+3&i+1&i+2\end{partn}^{\!\!+},\quad&
g_2&:= \begin{partn}{4} i&i+1&i+2&i+3\\ \hhline{-|~|-|~} i&i+1&i+2&i+3\end{partn}^{\!\!+}.
\\
e_3&:= \begin{partn}{2} i,i+3 & i+1,i+2\\ \hhline{~|~} i,i+3 & i+1,i+2\end{partn}^{\!\!+},\quad&
f_3&:= \begin{partn}{3} i,i+2,i+3&i+1&\\ \hhline{~|~|-} i,i+3&i+1&i+2\end{partn}^{\!\!+},\quad
&
\end{alignat*}
These idempotents participate in several singular squares, which will be exhibited below, and are illustrated in Figure \ref{fig:peep1}.

The square $\smat{e_1}{e_2}{e}{e_3}$ is UD-singularised by
$u = \begin{partn}{3} i&i+1,i+2&i+3\\ \hhline{~|~|~} i&i+1,i+2&i+3\end{partn}^{\!\!+}$.
In it, $e_3$ is a projection from~$P_0$, so $a_{e_3}=1$ by Lemma \ref{la:P0nr1};
and $e_2$ has full codomain and label $1$, so $a_{e_2}=1$ by Lemma \ref{la:eqlabeldual}.
Therefore, the square relation $a_{e_1}^{-1}a_{e_2}=a_e^{-1}a_{e_3}$ implies
\begin{equation}
\label{eq:peep1}
a_e=a_{e_1}.
\end{equation}

The square $\smat{f_1}{f_2}{f}{f_3}$ is UD-singularised
by 
$v=\begin{partn}{4} i&i+1&i+2,i+3&\\ \hhline{~|~|~|-} i&i+1&i+3&i+2\end{partn}^{\!\!+}$.
Note that $f_2\in P_1$, so by Lemma \ref{la:P1nr} we have $a_{f_2}=a_t$;
and $f_3$ has full domain and label $1$, so $a_{f_3}=1$ by Lemma~\ref{la:eqlabel}.
Combining this with the square relation $a_{f_1}^{-1}a_{f_2}=a_f^{-1}a_{f_3}$ yields 
\begin{equation}
\label{eq:peep2}
a_ta_f=a_{f_1}.
\end{equation}

Now consider $\smat{e_1}{f_1}{g_1}{g_2}$, which is LR-singularised by
$w=\begin{partn}{4} i&i+1&i+2&i+3\\ \hhline{~|~|-|~} i&i+1&i+2&i+3\end{partn}^{\!\!+}$.
In Claim \ref{cl:lab125} from the proof of Lemma \ref{la:lab12} we showed that $a_{g_2}=a_t^2$.
Also, we have $a_{g_1}=a_t$, which is shown analogously to Claim \ref{cl:lab123} in the proof of Lemma \ref{la:lab12}.  Consequently, $a_{g_1}^{-1}a_{g_2} = a_t$.
Combining this with the square relation $a_{e_1}^{-1}a_{f_1}=a_{g_1}^{-1}a_{g_2}$,
and with \eqref{eq:peep1} and \eqref{eq:peep2}, we have
\[
a_ea_t=a_ea_{g_1}^{-1}a_{g_2}=a_ea_{e_1}^{-1}a_{f_1}=a_ta_f,
\]
completing the proof.
\end{proof}

