\begin{cor}
\label{cor:peep1}
Let $e\in E(n,r)$ be any non-projection idempotent with full domain, and let $t\in P_1$.  Then $a_ta_e=a_ea_t$ in $\sfG(\labU\cup\{s\})$.
\end{cor}

\begin{proof}
By Lemma \ref{la:fdtoTn}, we may assume without loss of generality that $e\in\T_n$.
Since $\labU\cup\{s\}$ contains $\Tlex$, 
it follows from Lemma \ref{la:GRtransl}\ref{it:GRt4} that $a_e=a_{e_1}\cdots a_{e_k}$, with each $e_i$ a Coxeter idempotent.
The result now follows from Lemma~\ref{la:peep}. 
\end{proof}



\subsection[The twisted partition monoid $\Ptw_n$]{The twisted partition monoid \boldmath{$\Ptw_n$}}
\label{ss:tw}




As we will soon see, the results obtained so far will allow us to conclude that our group $\GI$ is a homomorphic image of $\Z\times\S_r$.  We now provide a means to show that, conversely, $\GI$ is also a homomorphic \emph{preimage} of $\Z\times\S_r$.



Consider partitions $a,b\in\P_n$, and the product graph $\Ga(a,b)$.  A component of this graph is called \emph{floating} if it is contained entirely within $[n]''$, the middle row of vertices.   We let $\Phi(a,b)$ denote the number of such floating components.  For example, with $a,b\in\P_6$ from Figure \ref{fig:P6}, we have $\Phi(a,b) = 1$, with the unique floating component of $\Ga(a,b)$ being $\{1'',2'',6''\}$.

The ($\Z$-)\emph{twisted partition monoid} $\Ptw_n$ has underlying set $\Z\times\P_n$, and product
\[
(i,a)(j,b) = (i+j+\Phi(a,b),ab) \qquad\text{for $i,j\in\Z$ and $a,b\in\P_n$.}
\]
The monoid $\Ptw_n$ is a special case of a \emph{tight twisted product}, as studied in \cite{EGMR2}.  The analogous twisted product with underlying set $\mathbb N\times\P_n$ is more commonly studied; see \cite{ER22a,ER22b,FL11,LF2006,BDP2002,KV2023,ACHLV2015}.  The following is a list of facts about $\Ptw_n$, which are consequences of the stated results from \cite{EGMR2}: 
\bit
\item $\Ptw_n$ is regular \cite[Theorem 7.4]{EGMR2}.
\item The $\D$-classes of $\Ptw_n$ are the sets $\Z \times D(n,r)$, for $0\leq r\leq n$, and every maximal subgroup contained in $\Z\times D(n,r)$ is isomorphic to the direct product $\Z\times\S_r$
\cite[Corollary 5.2 and Theorem 6.2]{EGMR2}.
\item Writing $\ol e = (-\Phi(e,e),e)$ for $e\in\sfE(\P_n)$, we have $\sfE(\Ptw_n) = \set{\ol e}{e\in \sfE(\P_n)}$ \cite[Proposition~6.4 and Remark~6.5]{EGMR2}.
\item The map $e\mt\ol e$ determines an isomorphism of biordered sets $\sfE(\P_n) \to \sfE(\Ptw_n)$
\cite[Corollary~6.15 and Remark 6.16]{EGMR2}.
\item The idempotent-generated submonoid $\langle\sfE(\Ptw_n)\rangle$ consists of the identity element $(0,1)$, and all $\D$-classes $\Z\times D(n,r)$ for $0\leq r\leq n-1$
\cite[Theorem 8.7]{EGMR2}.
\eit
Consequently, we have a surmorphism $\IG(\sfE(\P_n)) \cong \IG(\sfE(\Ptw_n)) \to \langle\sfE(\Ptw_n)\rangle$ given by ${x_e\mt\ol e}$ for $e\in\sfE(\P_n)$.
%
Moreover, for any fixed $e_0\in \sfE(\P_n)$ of rank $0\leq r\leq n-1$, this surmorphism restricts to a surmorphism from $\GI$, the maximal subgroup of $\IG(\sfE(\P_n))$ containing $x_{e_0}$, to the maximal subgroup of $\Ptw_n$ containing $\ol e_0$, which is isomorphic to $\Z\times\S_r$.  We record this final conclusion here for future reference, and we note that this includes the case $r=0$.




\begin{prop}\label{prop:preimage}
For any $0\leq r\leq n-1$, the group $\GI$ is a homomorphic preimage of~${\Z\times\S_r}$.
\qed
\end{prop}




\subsection{Completing the proof}
\label{ss:theend}

Recall from Lemma \ref{la:Upres} that our maximal subgroup $\GI \cong \sfG(\labU\cup\{s\})$ is defined by the presentation
\[
\presn(\labU\cup\{s\})=\bigl\langle A(n,r)\mid \rels_1(\labU\cup \{s\}),\ \rels_{\subSq}(n,r)\bigr\rangle,
\]
where $s$ is a fixed projection from $P_0(n,r)$.

Fix any $t\in P_1$, and define
\[
E':=E(n,r)\cap\T_n = \{ e\in E(n,r)\colon \NTu(e)=0,\ \NTd(e)=n-r\}.
\]
Let~$\rels_{\subSq}' (n,r)$ be the set of square relations in
$\rels_{\subSq}(n,r)$ that
involve only idempotents from~$E'$, and let $\rels_{\subSq}'' (n,r):=\rels_{\subSq}(n,r)\setminus
\rels_{\subSq}'(n,r)$.
Adding the commuting relations established in Corollary~\ref{cor:peep1} for $e\in E'$ to the presentation $\presn(\labU\cup\{s\})$ yields the equivalent presentation:
\begin{equation}\label{eq:bigpres}
\bigl\langle A(n,r)\mid  \rels_1(\labU\cup \{s\}),\ \rels_{\subSq}'(n,r),\ 
\rels_{\subSq}'' (n,r),\ a_ea_t=a_ta_e\ (e\in E' )\bigr\rangle.
\end{equation}

Now let $A'(n,r):=\big\{ a_e\colon e\in E' \cup\{t\}\big\}$.  By Lemma \ref{la:geneli}, we have $\GI = \la A_F\ra$, where $F=F(n,r)$ is defined in \eqref{eq:Fnr}, and we again decompose $F = P_0\cup P_1\cup F_1\cup F_2$, where~$F_1$ and~$F_2$ are as in~\eqref{eq:F1F2}.  By Lemmas \ref{la:P1nr} and \ref{la:P0nr1}, we have $\GI = \la A_{F_1\cup F_2\cup\{t\}}\ra$.  Next, by Lemma~\ref{la:fdtoTn} and its dual, we obtain $\GI = \la A_{E'\cup E''\cup\{t\}}\ra$, where $E'':=\set{e^*}{e\in E'}$.  Combining the dual of Lemma \ref{la:GRtransl}\ref{it:GRt4} with Lemma \ref{la:lab12}, each letter from $A_{E''}$ is a product of letters from~$A_{E'}$.  So we conclude that $\GI = \la A_{E'\cup\{t\}}\ra = \la A'(n,r)\ra$.  
%
Thus, we can eliminate all the generators from $A(n,r)\setminus A'(n,r)$ in the presentation \eqref{eq:bigpres}.
Notice that the relations $\rels_{\subSq}'(n,r)$ are unaffected by this elimination, since they involve only generators from $A_{E'}\sub A'(n,r)$.


Recall that $\labU$ contains the tree $\Tlex$, and so
$\rels_1(\labU\cup \{s\})$ contains $\rels_1(\Tlex)$.
Hence we now see that $\GI$ is defined by the presentation
\[
\langle A'(n,r) \mid \rels_1(\Tlex),\ \rels_{\subSq}'(n,r),\ a_ea_t=a_ta_e\ (e\in E' ),\ \rels'''\rangle
\]
for some set of relations $\rels'''$.
By Proposition \ref{pr:treeTn}, the presentation
\[
\langle A'(n,r)\setminus\{t\} \mid \rels_1(\Tlex),\ \rels_{\subSq}'(n,r)\rangle
\]
defines the symmetric group $\S_r$.
Therefore $\GI$ is a homomorphic image of $\Z\times\S_r$.
%
But by Proposition \ref{prop:preimage}, $\Z\times\S_r$ is also a homomorphic image of $\GI$.  Since $\Z$ is abelian and Hopfian, and~$\S_r$ is finite, it follows by \cite[Corollary, p233]{Hi69} that $\Z\times\S_r$ is Hopfian.  Therefore $\GI\cong \Z\times\S_r$, as required.




\section{Maximal subgroups in \boldmath{$\IG(\sfE(\P_n))$}, the case of rank \boldmath{$0$}}
\label{sec:r0}

Having completed the proof of Theorem \ref{thm:mainIGPn} for $1\leq r\leq n-2$, we now deal with the final case, where $r=0$.  Here we cannot `reduce to $\T_n$', as $D(n,0)$ consists entirely of partitions of rank~$0$, and hence contains no transformations at all.

\begin{prop}
\label{pr:r0}
Let $n\geq 2$, and let $e_0$ be an idempotent of rank $0$ in $\P_n$.
Then the maximal subgroup of $\IG(\sfE(\P_n))$ containing $x_{e_0}$ is isomorphic to $\Z$.
\end{prop}

\begin{proof}
The proof is in many ways similar to, yet much easier than,  the proof for the $r\geq 1$ case, but with a couple of variations. We cover it rapidly,  but deal with the differences in full detail.

Note that \emph{all} the elements of $D(n,0)$ are idempotents, so we can pick a very straightforward spanning tree for $\GH(D(n,0))$:
\[
T=T(n,0):=\big\{ e\in E(n,0)\colon \ker(e)=\nabla_{[n]}\text{ or } \coker(e)=\nabla_{[n]}\big\}.
\]
We remark that every element of $E(n,0)$ must have at least one upper block and at least one lower block. Those that attain at least one of those lower bounds are precisely the elements of~$T$.

By Theorem \ref{thm:spantreepres}, the maximal subgroup $\GI$ is isomorphic to $\sfG(T)$,
i.e.~it is defined by the presentation 
\[
\presn(T)= \big\langle A(n,0)\colon \rels_1(T),\ \rels_\subSq(n,0)\big\rangle.
\]


We can eliminate the majority of the generators in $A(n,r)$ by using Lemma \ref{la:ehrsq}, and the following analogue of Lemma \ref{la:type7} concerning NT-reducing squares (cf.~Definition \ref{defn:NT}).


\begin{claim}
\label{cl:r01}
If $p=\begin{partn}{3} A&B&C\\ \hhline{-|-|-} A&B&C\end{partn}\oplus q\in P(n,0)$, then $\smat{e_1}{e_2}{e_3}{p}$ is an NT-reducing square with base $p$, where
\[
e_1:=\begin{partn}{2} A\cup C&B\\ \hhline{-|-} A\cup B&C\end{partn}\oplus q,\quad
e_2:=\begin{partn}{3} \multicolumn{2}{c|}{A\cup C}&B\\ \hhline{-|-|-} A&B&C\end{partn}\oplus q \ANd
e_3:=\begin{partn}{3} A&B&C\\ \hhline{-|-|-} \multicolumn{2}{c|}{A\cup B}&C\end{partn}\oplus q.
\] 
\end{claim}

\begin{proof}
An RL-singularising element is $u=\begin{partn}{3} A& B&C \\ \hhline{~|-|~} A\cup B&&C\end{partn}\oplus q$; see Figure \ref{fig:r01}.
\end{proof}


