We now define $F = F(n,0) = T\cup P_2$, but we note that this is different from the set denoted~$F$ in Section \ref{sec:maxIGPn}.

\begin{claim}\label{cl:1.5}
Every element of $E(n,0) \setminus F(n,0)$ is the base of an NT-reducing singular square.
\end{claim}

\begin{proof}
Let $e\in E(n,0) \setminus F(n,0)$.  If $e$ is a projection, then Claim \ref{cl:r01} applies.  So now suppose~$e$ is not a projection, and assume without loss of generality that $\ker(e) \not\sub \coker(e)$.  Since $e$ does not belong to $T$, it has at least two upper blocks, say $A$ and $B$.  Now let $f\in E(n,0)$ be obtained from $e$ by merging these into the single block $A\cup B$.  Then $e\mr\L f$ (cf.~Lemma \ref{la:Green_Pn}) and $\ker(e) \subsetneq\ker(f)$.  Thus, Lemma \ref{la:ehrsq} applies.
\end{proof}



An inductive argument as in Lemma \ref{la:geneli} now gives $\GI = \la A_F\ra$.  Recalling that $a_e=1$ for $e\in T$, it follows that all the generators from $A(n,0)$ can be eliminated except those in $A_{P_2} = \{a_e\colon e\in P_2\}$.



\begin{claim}
\label{cl:r0pqP2}
If $p,q\in P_2(n,0)$ then $a_p=a_q$  in $\sfG(T)$.
\end{claim}

\begin{proof}
Analogously to Lemma \ref{la:P1nr}, we prove this by induction on $n\geq2(=r+2)$.
The first case is $n=2$, when $|P_2|=1$, and there is nothing to prove.
However, unlike the proof of Lemma~\ref{la:P1nr}, here we must also check the case $n=3$, which we do below. The singular squares used in the proof are illustrated in Figure \ref{fig:r01a}.  Although each square is singular by Lemma \ref{la:ehrsq} or Claim~\ref{cl:r01}, we still picture a singularising element for convenience.

For distinct $i,j\in [3]$, define
$\sfp(i,j):=\begin{partn}{2} i,j&k\\ \hhline{-|-} i,j&k\end{partn}$,
where $\{i,j,k\}=[3]$.
Then $\sfp(i,j)=\sfp(j,i)$ and $P_2=\{\sfp(1,2),\sfp(1,3),\sfp(2,3)\}$.

By Lemma \ref{la:ehrsq} we have a singular square $\smat{f_1}{f_2}{\sfp(i,j)}{e_1}$, where
\[
f_1:=\begin{partn}{2} \multicolumn{2}{c}{i,j,k}\\ \hhline{-|-} i,j&k\end{partn},\quad
f_2:=\begin{partn}{3} \multicolumn{3}{c}{i,j,k}\\ \hhline{-|-|-} i&j&k\end{partn} \ANd
e_1:=\begin{partn}{3} \multicolumn{2}{c|}{i,j} & k\\ \hhline{-|-|-} i&j&k\end{partn}.
\]
Furthermore $f_1,f_2\in T$, so $a_{f_1}=a_{f_2}=1$. The square relation now yields
\begin{equation}
\label{eq:r01}
a_{\sfp(i,j)}=a_{e_1}\quad \text{ for } e_1= \begin{partn}{3} \multicolumn{2}{c|}{i,j} & k\\ \hhline{-|-|-} i&j&k\end{partn}.
\end{equation}
A dual argument shows that
\begin{equation}
\label{eq:r02}
a_{\sfp(j,k)}=a_{e_2}\quad \text{ for } e_2=\begin{partn}{3} i&j&k\\ \hhline{-|-|-} i& \multicolumn{2}{c}{j,k}\end{partn}.
\end{equation}
Lemma \ref{la:ehrsq} again gives us a singular square $\smat{g_1}{g_2}{g_3}{e_3}$, where
\[
g_1:=\begin{partn}{1} i,j,k\\ \hhline{-} i,j,k\end{partn},\quad
g_2:=\begin{partn}{2} \multicolumn{2}{c}{i,j,k}\\ \hhline{-|-} i&j,k\end{partn},\quad
g_3:=\begin{partn}{2} i,j&k\\ \hhline{-|-} \multicolumn{2}{c}{i,j,k}\end{partn}\ANd
e_3:=\begin{partn}{2} i,j&k\\ \hhline{-|-} i&j,k\end{partn}.
\]
Since $g_1,g_2,g_3\in T$, we have $a_{g_1}=a_{g_2}=a_{g_3}=1$, and the square relation yields
\begin{equation}
\label{eq:r03}
a_{e_3}=1\quad \text{ for } e_3=\begin{partn}{2} i,j&k\\ \hhline{-|-} i&j,k\end{partn}.
\end{equation}
Finally, let $z:=\begin{partn}{3} i&j&k\\ \hhline{-|-|-} i&j&k\end{partn}
=\begin{partn}{3} 1&2&3\\ \hhline{-|-|-} 1&2&3\end{partn}$.
The square $\smat{e_3}{e_1}{e_2}{z}$ is singular by Claim \ref{cl:r01}.
Substituting \eqref{eq:r01}--\eqref{eq:r03} into the resulting square relation $a_{e_3}^{-1}a_{e_1} = a_{e_2}^{-1}a_z$ yields
\[
a_{\sfp(j,k)}a_{\sfp(i,j)}=a_z \quad \text{ for } \{i,j,k\}=\{1,2,3\}.
\]
Using this twice we have
\[
a_{\sfp(j,k)}a_{\sfp(i,j)}=a_z=a_{\sfp(k,j)}a_{\sfp(i,k)}=a_{\sfp(j,k)}a_{\sfp(i,k)},
\]
from which it follows that $a_{\sfp(i,j)}=a_{\sfp(i,k)}$ if $\{i,j,k\}=\{1,2,3\}$.
And now
\[
a_{\sfp(1,2)}=a_{\sfp(1,3)}=a_{\sfp(3,1)}=a_{\sfp(3,2)}=a_{\sfp(2,3)}.
\]
This completes the proof of Claim \ref{cl:r0pqP2} when $n=3$.

For $n\geq 4$ the inductive step now proceeds as in the proof of Lemma \ref{la:P1nr}.
Let $p,q\in P_2$ be arbitrary.
Recall the copies $\P_n^{i,j}$ of $\P_{n-1}$ in $\P_n$, for arbitrary distinct $i,j\in [n]$.
Note that our spanning tree $T(n,0)$ contains a natural copy of the tree $T(n-1,0)$ corresponding to each~$\P_n^{i,j}$. 
Thus, if $p$ and $q$ belong to the same $\P_n^{i,j}$ we obtain $a_p=a_q$ by induction.
Otherwise, we let $(i,j)\in\ker(p)$ and $(k,l)\in \ker(q)$ be arbitrary with $i\neq j$ and $k\neq l$.
Since $n\geq 4$, there exists~${u\in P_2}$ such that $(i,j),(k,l)\in\ker(u)$.
But then $a_p=a_u=a_q$, and Claim \ref{cl:r0pqP2} is proved.
\end{proof}



