As was already mentioned,  the notion of \pnormality{} for pointed categories, while interesting in its own right, can be generalised to the broader setting of (non-pointed) categories equipped with a class of trivial objects. The next sections are devoted to this generalisation, beginning with the necessary preliminaries.
\section{Categories with a distinguished class of trivial objects}
\label{sec-triv-obj}
This section contains the necessary background on kernels and cokernels defined relative to a class of trivial objects. We omit most of the proofs as they concern well-known results. A more in-depth discussion of this topic can be found for example in \cite{GRANDIS13,GRANDIS92,MARKI13}.

Throughout this section, we fix a category $\cat C$ and a class $\tobj$ of objects in $\cat C$, which we identify with the full subcategory of $\cat C$ spanned by those objects.
\begin{definition}
\label{Z-def}
     We say that a morphism in $\cat C$ is \emph{\nptrivial{}} if it factors through an object in $\cat Z$.  Given any map $f\colon A\to B$ in $\cat C$, a \emph{\npkernel{}} of $f$ is given by an object $K$ and a map $k\colon K\to A$ such that $\comp kf$ is \nptrivial{} and for any other map $x\colon X\to A$ such that $\comp xf $ is \nptrivial{}, there exists a unique $x'\colon X\to K$ such that $\comp{x'}k=x$.
    By a slight abuse of notation, we may refer to the kernel $(K, k)$ simply as $K$ or $k$, when the distinction is clear from context.
    Of course, \emph{\npcokernel{}s} are defined dually.
    A \emph{\npexact{} sequence} is given by a pair of composable maps 
\(
\begin{tikzcd}[cramped, sep=1.5em]
A\arrow[r, "f"]&B\arrow[r,"g"]&C
\end{tikzcd}
\)
    such that $(A,f)$ is the \npkernel{} of $g$ and $(C,g)$ is the \npcokernel{} of $f$.
\end{definition}
\begin{remark}
\label{coker-of-ker}
 Given a \npkernel{} $(A,f)$, if $f\colon A\to B$ admits a \npcokernel{} $(C,g)$, then $(A,f)$ is the \npkernel{} of $g$.
\end{remark}
\begin{proposition}
\label{triv-cancel}
    Let $f$ be the underlying map of a \npkernel{}. Then $f$ is a monomorphism. Furthermore, if $g$ is a map such that $\comp gf$ is defined and \nptrivial{}, then $g$ itself is \nptrivial{}.
\end{proposition}
\begin{proof}
The first property is well known.
For the second property, suppose $f$ is the \npkernel{} of a map $u$. Since $\comp gf$ is \nptrivial{}, we can write $\comp gf=\comp st$ for some maps $s$ and $t$ such that $\cod s=\dom t$ is in $\tobj$. Observe that $\comp tu$ is \nptrivial{}, and hence $t$ factors uniquely as $t=\comp vf$ for some map $v$. It follows that $\mcomp{s,v,f}=\comp st=\comp gf$. As $f$ is a monomorphism, we obtain $g=\comp sv$, which shows that $g$ is \nptrivial{}.
\end{proof}
\begin{notation}
    We call \emph{\npnormmono{}s} the   monomorphisms in $\cat C$ underlying \npkernel{}s. We denote by $\NMono$ the class of \npnormmono{}s in $\cat C$, and we graphically represent them using the same special arrow `$\nmonoto$' we used for (ordinary) normal monomorphisms.
    Similarly, we call \emph{\npnormepi{}s} the   epimorphisms underlying \npcokernel{}s. We denote by $\NEpi$ the class of \npnormepi{}s, and we use again  the special arrow `$\nepito$' to graphically represent them.
\end{notation}
\begin{proposition}
\label{stable-nm}
    Let $f\colon X\to Y$ be a morphism in $\cat C$ and let  $k\colon K\to X$ be its \npkernel{}. Given any morphism $x\colon X'\to X$, if the pullback of $k$ along $x$ exists, then it is the \npkernel{} of the composite $\comp xf$. In particular, \npnormmono{}s are stable under pullbacks.
\end{proposition}
\begin{remark}
\label{closed-under-retracts}
    The class of \nptrivial{} morphisms in $\cat C$ constitutes an \emph{ideal} of maps (\cite{EHRESMAN,GRANDIS92,MARKI13}). Replacing $\tobj$ with its closure under retracts (i.e.\ replacing $\tobj$ with the class $\tobj'$ of objects $X$ such that there exists a split monomorphism with domain $X$ and codomain in $\tobj$) does not change the corresponding ideal of trivial maps, nor the associated notions of kernel, cokernel and exactness. On the other hand, working with a class $\cat Z$ closed under retracts allows for cleaner statements of certain results. Accordingly, we may make the following assumption without loss of generality.
\end{remark}
From now on, and throughout this section, we assume that $\tobj$ is closed under retracts in $\cat C$.
\begin{proposition}
\label{monocoref}
     Given an object $B$ in $\cat C$ and a monomorphism $\cuni B\colon \corefl B\monoto B$, then $(\corefl B,\cuni B)$ is a coreflection of $B$ in $\tobj$ if and only if it is a \npkernel{} of $\id B$. 
    In this case, given maps 
    \(
    \begin{tikzcd}[cramped, sep=1.5em]
    K\arrow[r, "k"]&A\arrow[r,"f"]&B,
    \end{tikzcd}
    \)
    then $(K,k)$ is the \npkernel{} of $f$ if and only if there exists a (unique) map $h\colon K\to \corefl B$ such that the following square is a pullback.
    \begin{equation*}
    \begin{tikzcd}
    K\arrow[r, "h"]\arrow[d, "k"'] & \corefl B\arrow[d, "\cuni B"]
    \\
    A\arrow[r, "f"'] &B
    \end{tikzcd}
    \end{equation*}
    Finally, $\tobj$ is a mono-coreflective subcategory of $\cat C$ if and only if every identity morphism in $\cat C$ admits a \npkernel{}.
\end{proposition}

(In this paper, reflective and coreflective subcategories are always assumed to be closed under isomorphisms -- and therefore under retracts.)
\begin{proposition}
\label{eq-tker}
Given a \npnormmono{} $f\colon A\to B$ in $\cat C$, then the following are equivalent.
\begin{enumerate*}[(i)]
    \item The map $f$ is \nptrivial{};
    \item $A$ is in $\cat Z$;
    \item $(A,f)$ is the \npkernel{} of an isomorphism;
    \item $(A,f)$ is a coreflection of $B$ in $\cat Z$.
\end{enumerate*}
\end{proposition}
\begin{notation}
We denote by $\TKer$ the class of maps whose \npkernel{} exists and is \nptrivial{} (according to any of the equivalent statements in \cref{eq-tker}), and we graphically represent a map with a \nptrivial{} \npkernel{} by using again the special arrow `\tkerto'.
\end{notation}
\begin{proposition}
\label{charact-tker}
     Suppose $f$ is a map in $\cat C$ admitting a \npkernel{}. Then the \npkernel{} of $f$ is \nptrivial{} if and only if, for every map $g$ such that $\comp gf$ is defined and \nptrivial{}, the map $g$ itself is \nptrivial{}.
\end{proposition}
\begin{proof}
    Let $k$ be the \npkernel{} of $f$. If $k$ is \nptrivial{} and $g$ is such that $\comp gf$ is defined and \nptrivial{}, then $g$ factors through $k$, which is a \nptrivial{} map, and so $g$ is itself \nptrivial{}. The converse is immediate.
\end{proof}
\begin{proposition}
\label{ne-ort-tk}
In $\cat C$, \npnormepi{}s satisfy the left lifting property with respect to maps with \nptrivial{} \npkernel{}.
\end{proposition}
\begin{proof}
    Consider the following commutative square,
    \begin{equation*}
    \begin{tikzcd}
    \cdot \arrow[r,"v"] \arrow[d,normepi, "f"'] &\cdot\arrow[d,tker, "g"]
    \\
    \cdot \arrow[r,"u"']&\cdot
    \end{tikzcd}
    \end{equation*}
    where $f$ is the \npcokernel{} of a map $a$ and and $g$ is a map whose  \npkernel{} $b$ is \nptrivial{}. Since $\mcomp{a,v,g}$ is \nptrivial{}, it follows from \cref{charact-tker} that $\comp av$ is \nptrivial{} as well. Hence, there exists a unique map $d$ such that $v=\comp fd$, and by the epimorphicity of $f$, we further deduce that $\comp dg =u$.
\end{proof}
\section{Non-pointed \pnormal{} categories}
\label{non-p-normal}
Building on the preparatory material of the previous section, we are now ready to formalise the generalisation of \pnormal{} categories to the non-pointed setting.
\begin{definition}
\label{normal-def}
Let $\cat C$ be a category and $\cat Z$ a subcategory. We say that $\cat C$ is \emph{\pnormal{} with respect to $\tobj$}, or that $\cat C$ is \emph{\normal{}}, if $\tobj$ is mono-coreflective in $\cat C$ and the following properties hold.
\begin{enumerate}
    \item $\cat C$ has finite limits.
    \item $\cat C$ has \npcokernel{}s of \npkernel{}s.
    \item \npnormepi{}s are pullback-stable in $\cat C$.
\end{enumerate}
In what follows, when we say that $\cat C$ is a \normal{} category, it is understood that $\tobj$ is a subcategory of $\cat C$, and that $\cat C$ and $\tobj$ satisfy the conditions stated above.
\end{definition}
\begin{remark}
Since (pointed) kernels are limits, in (pointed) \pnormal{} categories the existence of kernels follows  by finite completeness. In the non-pointed case the situation is less straightforward: the existence of \npkernel{}s of identity maps is not automatic, but it is equivalent to the mono-coreflectivity of $\tobj$, by \cref{monocoref}. Once the existence of such kernels is ensured, the existence of every other \npkernel{} follows from finite completeness, again by \cref{monocoref}.
\end{remark}
We can now state one of the main features of \pnormal{} categories in the non-pointed case.
\begin{proposition}
\label{norm-fs}
Let $\cat C$ be a \normal{} category. Then $\cat C$ admits the pair \facsys{} as a stable factorisation system.
\end{proposition}
\begin{proof}
    For any map $f$ consider the following diagram,
    \begin{equation*}
    \begin{tikzcd}
    \cdot\arrow[r, "k", normmono]\arrow[d,"{e'}"']&\cdot\arrow[r, "f"]\arrow[d, "e",normepi]&\cdot
    \\
    \cdot \arrow[r, "h"', normmono]&\cdot\arrow[ur, "m"', bend right]
    \end{tikzcd}
    \end{equation*}
    where $k$ is the \npkernel{} of $f$, $e$ is the \npcokernel{} of $k$ and $m$ is the unique map such that $f=\comp e m$, by the universal property of $e$. The morphism $h$ is the \npkernel{} of $m$ and $e'$ is the unique map such that $\comp ke=\comp{e'}{h}$ by the universal property of $h$. The left square is a pullback, and therefore $e'$ is a \npnormepi{}. Since $\comp{e'}h=\comp ke $ is \nptrivial, it follows from the dual of \cref{triv-cancel} that $h$ is itself \nptrivial{}, and thus $f$ factors as a \npnormepi{} followed by a map with a \nptrivial{} \npkernel{}, as desired.

    We have already verified in \cref{ne-ort-tk} that maps in $\NEpi$ satisfy the left lifting property with respect to the maps in $\TKer$. It only remains to check that the two classes are closed under composition and contain isomorphisms.

    Clearly, any isomorphism is the \npcokernel{} of the coreflection in $\tobj$ of its domain, and it is therefore a \npnormepi{}. Given a pair of composable \npnormepi{}s
    \(
    \begin{tikzcd}[cramped, sep=1.5em]
    \cdot\arrow[r, "f",normepi]&\cdot\arrow[r,"g",normepi]&\cdot
    \end{tikzcd}
    \), write $\comp fg = \comp em$ with $e\in\NEpi$ and $m\in\TKer$. Since both $f$  and $g$ satisfy the left lifting property with respect to $m$, we obtain maps $s$ and $t$ making the following diagrams commute.
    \begin{equation*}
    \begin{tikzcd}
        \cdot\arrow[r,"e",normepi]\arrow[d,normepi,"f"']&\cdot\arrow[d,tker,"m"]&[4em]\cdot\arrow[r,"s"]\arrow[d,"g"',normepi]&\cdot\arrow[d,tker,"m"]
        \\
        \cdot\arrow[r,normepi, "g"']\arrow[ur,dashed, "s"{description}]&\cdot&\cdot\arrow[r,equal]\arrow[ur,"t"{description},dashed] &\cdot
    \end{tikzcd}
    \end{equation*}
    By the diagram on the left we have that $s$ is an epimorphism; by the diagram on the right, we have that $t$ is both an epimorphism and a split monomorphism, and thus an isomorphism. We conclude that $m$ is an isomorphism and therefore $\comp fg\iso e$ is a \npnormepi{}.

    Next, it is clear that any isomorphism has a \nptrivial{} \npkernel{} by \cref{eq-tker}. Given composable maps 
    \(
    \begin{tikzcd}[cramped, sep=1.5em]
    \cdot\arrow[r, "f",tker]&\cdot\arrow[r,"g",tker]&\cdot
    \end{tikzcd}
    \) with \nptrivial{} \npkernel{}s, we may consider the factorisation $\comp fg=\comp e m$, with $e\in\NEpi$ and $m\in\TKer$. Since $e$ satisfies the left lifting property with respect to $f$ and to $g$, we obtain maps $s$ and $t$ making the following diagrams commute.
    \begin{equation*}
    \begin{tikzcd}
        \cdot\arrow[r,"f",tker]\arrow[d,normepi,"e"']&\cdot\arrow[d,tker,"g"]&[4em]\cdot\arrow[r,equal]\arrow[d,"e"',normepi]&\cdot\arrow[d,tker,"f"]
        \\
        \cdot\arrow[r, "m"',tker]\arrow[ur,dashed, "s"{description}]&\cdot&\cdot\arrow[r,"s"']\arrow[ur,"t"{description},dashed] &\cdot
    \end{tikzcd}
    \end{equation*}
    From the diagram on the right we deduce that $e$ is a split monomorphism. As $e$ is already an epimorphism, we conclude that $e$ is in fact an isomorphism, and thus $\comp fg\iso m$ has a \nptrivial{} \npkernel{}.
\end{proof}
{
