\begin{proposition}
\label{characterisation-fs}
    Let $\cat C$ be a category with finite limits, and let $\cat Z$ be a mono-coreflective subcategory of $\cat C$. Then the following are equivalent.
    \begin{enumerate}[(i)]
        \item \label{pnfs1} $\cat C$ is \normal{}.
        \item\label{pnfs2} $\cat C$ admits \facsys{} as a stable factorisation system.
