\end{proposition}
\begin{proof}
    We have already proved that \ref{pnfs1} $\!\implies\!$ \ref{pnfs2} in \cref{norm-fs}, and obviously \ref{pnfs2}$\implies$\ref{pnfs3} and \ref{pnfs2}$\implies$\ref{pnfs4}. We now prove the remaining implications. Let us begin by showing that \ref{pnfs2}$\implies$\ref{pnfs1}.
    \begin{itemize}
        \item Suppose \ref{pnfs2} holds. To show that $\cat C$ is \normal{} we just need to prove that $\cat C$ admits \npcokernel{}s of \npkernel{}s. Let $(A,f)$ be the \npkernel{} of a map $g\colon B \to C$. Consider the factorisation $g=\comp em$, with $e\in\NEpi$ and $m\in\TKer$. It follows from \cref{charact-tker} that $(A,f)$ is also the \npkernel{} of $e$, and therefore  $e$ is the \npcokernel{} of $f$ by the dual of \cref{coker-of-ker}. \end{itemize}
    We now proceed to prove that \ref{pnfs3}$\implies$ \ref{pnfs2} and that \ref{pnfs4}$\implies$\ref{pnfs2} under the assumption that $\tobj$ is \sreflective{}.
    \begin{itemize}
        \item Suppose \ref{pnfs3} holds. We show that $\rcl=\TKer$. We know from \cref{ne-ort-tk} that \npnormepi{}s satisfy the left lifting property with respect to maps with a \nptrivial{} \npkernel{}. It then follows from \cref{fs-property} in \cref{fs-properties} that $\TKer\subseteq\rcl$. It remains to prove the reverse inclusion. Let $f\colon A\to B$ be a map in $\rcl$, and let $(K,k)$ be its \npkernel{}. Since the composite $\comp k f\colon K\to B$ is \nptrivial{}, \sreflectivity{} of $\tobj$ ensures that $K$ admits a reflection $(\refl K,\uni K)$ in $\cat Z$. We thus obtain the following commutative square for some map $\refl K \to B$.
        \begin{equation*}
        \begin{tikzcd}
            K\arrow[r,"k"]\arrow[d,"\uni K"'] &A\arrow[d,"f"]
            \\
            \refl K\arrow[r] & B
        \end{tikzcd}
        \end{equation*}
        By \cref{cp4} in \cref{closure-property}, $\uni K$ is a \npnormepi{}, and hence it satisfies the left lifting property with respect to maps in $\rcl$. We then obtain a map $d\colon \refl K\to A$ such that $k=\comp{\uni K}d$, and so $k$ is trivial, as desired.
        \item Suppose now that \ref{pnfs4} holds. We show that $\lcl=\NEpi$. Arguing as in the previous point, we have that $\NEpi\subseteq\lcl$. We need to prove the reverse inclusion. We proceed in steps.
        \begin{enumerate}[a)]
        \item\label{letter-a} First let us show that  if $f\colon A\to B$ lies in $\lcl$, and $g\colon B\to C$ is such that the composite $\comp fg$ is \nptrivial{}, then  $g$ is itself \nptrivial{}. Consider a coreflection $(\corefl C,\cuni C)$ of $C$ in $\cat Z$, so that we have the following factorisation for some map $A\to\corefl C$.
        \begin{equation*}
        \begin{tikzcd}
            A\arrow[r]\arrow[d,"f"'] &\corefl C\arrow[d,"\cuni C"]
            \\
            B\arrow[r,"g"']& C 
        \end{tikzcd}
        \end{equation*}
        Since $\cuni C$ has a \nptrivial{} \npkernel{} (as it is a \npnormmono{} -- see \cref{sec-triv-obj}) and $f\in\lcl$, there exists a map $d\colon B\to\corefl C$ such that $g=\comp d{\cuni C}$. Hence, $g$ is \nptrivial{}.

        \item\label{letter-b} Now let $f\colon A\to B$ be a map in $\lcl$ and let $(K,k)$ be its \npkernel{}. We claim that if $g\colon A\to C$ is an arrow such that $\comp kg$ is \nptrivial{}, then there exists a map $g'$ such that $g=\comp f{g'}$; in other words, $(B,f)$ satisfies the universal property of a \npcokernel{} of $k$, but without uniqueness.

        Consider the product $B\times C$, with projections $p_B$ and $p_C$,
and let $h\colon A\to B\times C$ be the map with components $f$ and $g$, as shown in the following diagram.
        \[
        \begin{tikzcd}[row sep =1 em]
        & B
        \\
        A\arrow[ur,"f"]\arrow[dr, "g"']\arrow[rr, "h" description] & &B\times C\arrow[ul, "p_B"']\arrow[dl, "p_C"]  \\
        &C
        \end{tikzcd}
        \]
        We can factor $h$ as $h=\comp e m$, for some $e\colon A\to M$ in $\lcl$ and $m\colon M\to B\times C$ in $\TKer$.  Since $f$ and $e$ are both in $\lcl$, we can apply \cref{fs-property-cancel} of \cref{fs-properties} to the equality $f=\mcomp{e,m,p_B}$ and immediately conclude that $\phi\coloneqq\comp m{p_B}\in\lcl$.

        Next, let $(\corefl B,\cuni B)$ be a coreflection of $B$ in $\tobj$. Since $(K,k)$ is the \npkernel{} of $f$, there exists a (unique) map  $w\colon K\to\corefl B$ such that the square of sides $f$, $\cuni B$, $w$ and $k$  is a pullback (see \cref{monocoref}). We can then construct the diagram below, where $(L,l,y)$ is the pullback of $\cuni B$ and $\comp m{p_B}$, and $x$ is the unique map such that $\comp x y=w$ and $\comp xl =\comp ke$.
        \begin{equation*}
        \begin{tikzcd}[column sep= 4em]
        K\arrow[r,"x"]\arrow[d,"k"]\arrow[rr, bend left, "w"]& L\arrow[r,"y"]\arrow[d,"l"] & \corefl B\arrow[d,"\cuni B"]
        \\
        A\arrow[r, "e"']\arrow[rr,"f"', bend right ] & M\arrow[r,"{\comp m {p_B}}"'] & B
        \end{tikzcd}
        \end{equation*}
        First, since the right-hand square is a pullback, it follows from \cref{monocoref} that $(L,l)$ is a \npkernel{} of $\comp m{p_B}$. Second, since the outer rectangle is a pullback (as mentioned above), we deduce the left-hand square is also a pullback. Hence, $x\in\lcl$ as it is a pullback of $e\in\lcl$. 

        Consider now the morphism
        \(
            \mcomp{x,l,m}=\mcomp{k,e,m}=\comp kh
        \) into the product $B\times C$. The components of this morphism are $\comp kf$ and $\comp kg$, both \nptrivial{} by hypothesis.  By \sreflectivity{} of $\tobj$  it follows that $\comp hk$, and hence $\mcomp{x,l,m}$, is \nptrivial{} (see \cref{closure-property}, \cref{cp3}). 
        We can then apply \cref{letter-a} above and \cref{charact-tker}  to cancel $m$ on the left and $x$ on the right, and conclude that $l$ itself is \nptrivial{}. 

        As previously observed, $(L,l)$ is the \npkernel{} of $\phi=\comp m{p_B}$, and so we have shown that $\phi\in\TKer$. We also established earlier that $\phi\in\lcl$ as well, and hence $\phi$ is an isomorphism (use \cref{fs-properties}). We can therefore define the map $g'=\mcomp{\phi^{-1},m,p_C}$, which satisfies $\comp f{g'}=g$.
         \item\label{letter-c} Finally, we show that any map in $\lcl$ is an epimorphism. By \cref{closure-property} (\cref{cp5}), every strong monomorphism has a \nptrivial{} \npkernel{}. It follows that every map in $\lcl$ satisfies the left lifting property with respect to strong monomorphisms, which implies -- in the presence of equalisers -- that they are epimorphisms.
        \end{enumerate}
       Combining \cref{letter-b,letter-c} we obtain that any map in $\lcl$ is the \npcokernel{} of its \npkernel{}, as required.\qedhere
    \end{itemize}
\end{proof}
}
\section{General properties of (non-pointed) \pnormal{} categories}
\label{sec-properties}
In this section, we extend to the general non-pointed case the properties previously established for \pnormal{} categories in \cref{pointed-case}, this time providing full proofs. We begin with a result generalising some well-know properties of pullbacks holding for regular categories.
\begin{lemma}
\label{pullback-lemmas}
   Let $\cat C$ be a category with pullbacks.
    \begin{enumerate}
        \item\label{pb-po-part} Consider the following pullback diagram in $\cat C$.
        \begin{equation}
    \label{pb-po-square}
    \begin{tikzcd}
    \cdot\arrow[r, "q",epi]\arrow[d, "g"',epi]&\cdot\arrow[d, "f"]
    \\
    \cdot\arrow[r,regepi, "p"']&\cdot
    \end{tikzcd}
    \end{equation}
    If $p$ is a regular epimorphism, $g$ is a pullback-stable epimorphism and $q$ is an epimorphism, then \ref{pb-po-square} is also a pushout square.
    \item\label{pf-pb-part} Consider then the following commutative diagram in $\cat C$.  
    \begin{equation}
    \label{pf-pb-diag}
\begin{tikzcd}
    A\arrow[r,"f"]\arrow[d, "a"] & B\arrow[r, "g"]\arrow[d,"b"] & C\arrow[d, "c"]
    \\
    A'\arrow[r, "{f'}"', regepi] & B'\arrow[r, "{g'}"'] &C'
\end{tikzcd}
\end{equation}
    If $f'$ is a pullback-stable regular epimorphism and both the outer rectangle and the left-hand square are pullbacks, then the right-hand square is also a pullback.
\item \label{B-K} (Generalised Barr-Kock theorem) Consider the following commutative diagram where $f$ is a pullback-stable regular epimorphism, $(r_0,r_1)$ is the kernel pair of $f$ and $(s_0,s_1)$ is the kernel pair of $g$.
\begin{equation}
\label{B-K-diag}
   \begin{tikzcd}
        \cdot \arrow[r, yshift=.3em, "r_0"]\arrow[r,yshift=-.3em, "r_1"']\arrow[d]& \cdot\arrow[r,regepi, "f"] \arrow[d] & \cdot\arrow[d]
        \\
        \cdot \arrow[r, yshift=.3em, "s_0"]\arrow[r,yshift=-.3em, "s_1"']& \cdot\arrow["g"',r] & \cdot
    \end{tikzcd}
\end{equation}
If either of the left-hand squares is a pullback, then the right-hand square is a pullback.
    \end{enumerate}
\end{lemma}
\begin{proof}
\Cref{pf-pb-part} may be proved essentially as in the regular case. \Cref{B-K} may also be proved as in the regular case, using \cref{pf-pb-part} (see, for example, \cite[Theorem~1.16]{GRAN21}).
For \cref{pf-pb-part}, we adapt the proof given in  \cite{GRAN21} for the analogous result. Consider the following commutative diagram.
\begin{equation*}
\begin{tikzcd}[column sep =2.5 em, row sep = 2 em]
    A &[-1em]&[.5em]B &[-1em]&[.5em] C
    \\
    & P&&Q&& C
    \\
    A' && B' && C'
    \arrow[from =1-1, to=1-3, "f",regepi]
    \arrow[from=1-3, to =1-5, "g"]
    \arrow[from=2-2, to=2-4, "p" near start,regepi]
    \arrow[from=2-4,to=2-6, "q" near start]
    \arrow[from=3-1,to=3-3, "{f'}"', regepi]
    \arrow[from=3-3,to=3-5, "{g'}"']
\arrow[from=1-1,to=3-1, "a"' near end]
    \arrow[from=1-3,to=3-3, crossing over, "b"' near end]
    \arrow[from=1-5, to=3-5, crossing over, "c"' near end]
\arrow[from=1-1,to=2-2, "\alpha"]
    \arrow[from=2-2,to=3-1, "{p'}"{xshift=.2em, yshift=.5em}]
    \arrow[from=1-3,to=2-4, "\beta"]
    \arrow[from=2-4,to=3-3,"{q'}"{xshift=.2em, yshift=.5em}]
    \arrow[from=1-5,to=2-6, equal]
    \arrow[from=2-6,to=3-5, "{c}"{xshift=.4em, yshift=.3em}]
\end{tikzcd}
\end{equation*}
Here $(Q,q,q')$ is the pullback of $g'$ and $c$, $(P,p,p')$ is the pullback of $f'$ and $q'$, while $\alpha$ and $\beta$ are the induced maps. Note that $p$ and $f$ are regular epimorphisms, as they arise as pullbacks of $f'$, while $\alpha$ is an isomorphism, since the outer rectangle is a pullback. Therefore, the following square
\begin{equation}
\label{some-square-pb-transf}
\begin{tikzcd}
    A\arrow[r, "f", regepi]\arrow[d, "\alpha"'{xshift=-.4em}, "\iso"{description}]& B\arrow[d, "\beta"]
    \\
    P\arrow[r, "p"', regepi] & Q
\end{tikzcd}
\end{equation} 
is a pullback square where $p$ and $f$ are regular epimorphisms and $\alpha$ is an isomorphism. We can then apply \cref{pb-po-part} and deduce that \ref{some-square-pb-transf} is also a pushout, which proves that  $\beta$ is an isomorphism.
\end{proof}
Specialising \cref{pullback-lemmas} to the context of non-pointed \pnormal{} categories we immediately obtain the following proposition.
\begin{proposition}
\label{normal-pullback-lemmas}
    In a \normal{} category, the following properties hold.
    \begin{enumerate}
        \item Any pullback square as in \ref{pb-po-square} is also a pushout square whenever $p$ is a regular epimorphism, $g$ is a \npnormepi{} and $q$ is an epimorphism. In particular, pullback squares of normal epimorphisms are pushouts.
        \item Suppose  \npnormepi{}s in $\cat C$ are also regular epimorphisms. Then, in any diagram as in \ref{pf-pb-diag}, if $f'$ is a \npnormepi{} and both the outer rectangle and the left-hand square are pullbacks, it follows that the right-hand square is also a pullback.
        \item Suppose  \npnormepi{}s in $\cat C$ are also regular epimorphisms. Then, in any diagram as in \ref{B-K-diag}, if $f$ is a \npnormepi{} and either of left-hand squares is a pullback, it follows that the right-hand square is also a pullback.
    \end{enumerate}
\end{proposition}
We now resume our list of properties.
\begin{proposition}
\label{lemma-pb-ex-seq}
    Let $\cat C$ be a \normal{} category, and consider the following commutative diagram where $f$ is the \npkernel{} of $g$.
    \begin{equation*}
    \begin{tikzcd}
        A'\arrow[r,"{f'}"]\arrow[d,"a"']&B'\arrow[r,"{g'}"]\arrow[d,"b"']&C'\arrow[d,"c"']
        \\
        A\arrow[r, "f"',
        normmono]& B\arrow[r,"g"']& C
    \end{tikzcd}
    \end{equation*}
    \begin{enumerate}
    \item\label{pb-e-1} If the left square is a pullback and $g'$ is the \npcokernel{} of $f'$, then $c\in\pTKer$. 
    \item \label{pb-e-2}Conversely, if $c\in\pTKer$ and $f'$ is the \npkernel{} of $g'$, then the left square is a pullback.
    \end{enumerate}
\end{proposition}
    \begin{proof}
    To prove \cref{pb-e-1}, notice that by \cref{stable-nm} we have that $f'$ is the \npkernel{} of the map $d=\comp bg=\comp {g'}c$. Since $g'$ is the \npcokernel{} of $f'$, by the construction provided in the proof of \cref{norm-fs}, we find that $\comp{g'}c$ is the \facsys{}-factorisation of $d$, and so $c\in\TKer$.

    The partial converse in \cref{pb-e-2} does not rely on \normality. It readily follows from the universal property of \npkernel{}s and the characterisation of maps in $\TKer$ given in \cref{charact-tker}.
    \end{proof}
    \begin{lemma}
    \label{product-norm-epi}
        In a \normal{} category $\cat C$, if $f\colon A\nepito B$ and $f'\colon A'\nepito B'$ are \npnormepi{}, then $f\times f'\colon A\times A'\to B\times B'$ is also a \npnormepi{}.
    \end{lemma}
    \begin{proof}
    The following squares (where the vertical arrows are the appropriate product projections) are pullbacks, and therefore $f\times B'$ and $A\times f'$ are obtained as pullbacks of \npnormepi{}s, and thus they are \npnormepi{}s themselves.
    \begin{equation*}
    \begin{tikzcd}
        A\times B'\arrow[r, "{f\times B'}"]\arrow[d] &[1.3 em]B\times B'\arrow[d] & A\times A'\arrow[r, "{A\times f'}"]\arrow[d] &[1.3em] A\times B'\arrow[d]
        \\
        A\arrow[r,"f"', normepi] & B & A'\arrow[r, "{f'}"',normepi] & B'
    \end{tikzcd}
    \end{equation*}
    Since \npnormepi{}s are stable under composition (as they are part of a factorisation system), we have that $f\times f' = \comp {(A\times f')}{(f\times B')}$ is a \npnormepi{}.
    \end{proof}
\begin{proposition}
\label{slice-is-normal}
    Let $\cat C$ be a \normal{} category. If $C$ is an object in $\cat C$, then the slice category $\slice CC$ is a a $(\slice Z C)$-\pnormal{} category. If $\cat B$ is any category, then the functor category $\Fun BC$ is a $\Fun BZ$-\pnormal{} category.
\end{proposition}
\begin{proof}
See \cref{ex-slices,ex-fun-cat}.
\end{proof}
In the final part of this section, we highlight some relationships between the notions introduced in this paper and the one in \cite{NORMAL}. The main difference between  \pnormal{} categories and normal categories as defined in \cite{NORMAL} is that, in the former, we do not ask for any relation between normal epimorphisms and regular epimorphisms. This distinction becomes particularly relevant if one wants to work in a non-pointed setting, as highlighted by the following propositions.
\begin{proposition}
\label{subterminal}
    Let $\cat C$ be a finitely complete category and $\tobj$ a class of trivial objects (closed under retracts). If $\RegEpi\subseteq\NEpi$, then every object in $Z$ in $\tobj$ is subterminal.
\end{proposition}
\begin{proof}
In the presence of kernel pairs, maps having the right lifting property with respect to regular epimorphisms are monomorphisms. Therefore, if $\RegEpi\subseteq\NEpi$, then by \cref{ne-ort-tk} we have that $\Mono\supseteq \TKer$. In particular, for any object $Z$ in $\tobj$ the terminal map $Z\to1$ is a monomorphism, since it has a \nptrivial{} \npkernel{} -- namely $(Z,\id Z)$. 
\end{proof}
\begin{proposition}
Let $\cat C$ be a pointed category, and suppose that $\cat C$ is \normal{} for some class $\tobj$ of trivial objects. The following conditions are equivalent:
\begin{enumerate*}[(i)]
    \item \label{pn-vs-n-1} $\TKer\subseteq \Mono$,
    \item \label{pn-vs-n-2} $\NEpi\supseteq\StrEpi$,
    \item \label{pn-vs-n-3} $\NEpi\supseteq\RegEpi$,
    \item \label{pn-vs-n-4} $\tobj$ is the class of zero objects of $\cat C$ and $\cat C$ is normal (in the sense of \cite{NORMAL}).
\end{enumerate*}
\end{proposition}
\begin{proof}




    The only non-obvious implication is \ref{pn-vs-n-3}$\implies$\ref{pn-vs-n-4}. Suppose 
    that \ref{pn-vs-n-3} holds. By \cref{subterminal}, it follows that $\tobj$ is the class of zero objects (subterminal objects are obviously zero objects in a pointed category), and 
    that $\NEpi=\pNEpi=\RegEpi$. Therefore, $\cat C$ is a pointed, finitely complete category where regular epimorphisms are stable and coincide with normal epimorphisms, i.e.\ $\cat C$ is normal.
\end{proof}
\section{Exact sequences in \pnormal{} categories}
In this section, we study the properties of exact sequences in (non-pointed) \pnormal{} categories. We also consider functors that preserve such sequences along with finite limits, and show that they preserve much of the extra structure of \pnormal{} categories.
\label{sec-ex-seq}
\begin{proposition}
\label{ex-seq-pb-po}
Let $\cat C$ be a \normal{} category, and let \(
\begin{tikzcd}[cramped, column sep =2em]
    A\arrow[r, "f",normmono]&B\arrow[r, "g",normepi]&C
\end{tikzcd}
\)
be a \npexact{} sequence in $\cat C$. Then the composite $\comp fg$ factors through an object $Z$, i.e.\ there exist morphisms $\unin\colon A\to Z$ and $\cunn\colon Z\to C$ such that the following diagram commutes. 
\begin{equation}
\begin{tikzcd}
\label[diagram]{exact-sequence-square}
    A\arrow[r, "f"]\arrow[d, "\unin"']& B\arrow[d, "g"]
    \\
    Z\arrow[r, "\cunn"'] & C
\end{tikzcd}
\end{equation}
For any such factorisation, the following conditions are equivalent:
\begin{enumerate*}[(a)]
    \item\label[condition]{ex-a}\cref{exact-sequence-square} is both a pullback and a pushout; 
    \item \label[condition]{ex-b}$(Z,\cunn)$ is a $\tobj$-coreflection of $C$; 
    \item \label[condition]{ex-c}$(Z,\unin)$ is a $\tobj$-reflection of $A$. 
\end{enumerate*}
\end{proposition}
\begin{proof}
    By \cref{monocoref}, we may  consider a $\tobj$-coreflection $\cunn\colon Z\to C$ of $C$, and obtain a map $\unin\colon A\to Z$ such that \cref{exact-sequence-square} is a pullback. Since $g$ is a \npnormepi{} and \cref{exact-sequence-square} is a pullback, it follows that $\unin$ is also a \npnormepi{}. By the dual of \cref{eq-tker}, $\unin$ is a $\tobj$-epi-reflection of $A$, and by the dual of \cref{monocoref}, \cref{exact-sequence-square} is a pushout. 


    Now, given any diagram of the form of \ref{exact-sequence-square} satisfying either \ref{ex-b} or \ref{ex-c}, it must be isomorphic to the one constructed in the previous paragraph. This shows that \cref{ex-b,ex-c} are equivalent, and that each of them implies \ref{ex-a}. 

    Conversely, given a diagram like \ref{exact-sequence-square} satisfying \cref{ex-a}, then $\unin$ is a \nptrivial{} \npnormepi{}, and thus \ref{ex-b} holds by the dual of \cref{eq-tker}.
\end{proof}
\begin{proposition}
\label{stability-of-ex-seq}
In a \normal{} category $\cat C$:
\begin{enumerate}
    \item\label{pr-ex-seq}binary products of \npexact{} sequences are \npexact{};
    \item\label{pb-ex-seq}  the pullback of a \npexact{} sequence along a morphism $c$ is \npexact{} if and only if $c\in\TKer$.
\end{enumerate} 
\end{proposition}
\begin{proof}
    Given two \npexact{} sequences
    \[
    \begin{tikzcd}
        A\arrow[r, "f",normmono]& B\arrow[r, "g",normepi] & C &\text{and}&  A'\arrow[r, "f'",normmono] &B' \arrow[r, "g'",normepi]&C',
    \end{tikzcd}
    \]
    we know that $g\times g'$ is a \npnormepi{} by \cref{product-norm-epi}. The fact that $f\times f'$ is the \npkernel{} of $g\times g'$  follows from the observation that the product of mono-coreflections is a mono-coreflection of the product, together with \cref{monocoref}.

    Consider the following diagram,
    \[
    \begin{tikzcd}
     A'\arrow[r,"{f'}"]\arrow[d,"a"']&B'\arrow[r,"{g'}"] \arrow[d,"b"']&C'\arrow[d,"c"']
        \\
        A\arrow[r, "f"', normmono]& B\arrow[r,"g"',normepi]& C
    \end{tikzcd}
    \]
    with both squares being pullbacks and the lower row \npexact{}. In general, $g'\in\NEpi$ by \normality{}, and $f'$ is the \npkernel{} of $\comp bg=\comp{g'}c$ by \cref{stable-nm}. Moreover, if $c\in\TKer$ one readily verifies that $f'$ is also the \npcokernel{} of $g'$.  The converse implication follows from \cref{lemma-pb-ex-seq}.
\end{proof}
